NAME = 'ACV: A Conservative Version'
BOOK = 'Isaiah'

CHAPTERS = {
    1: {
        1: 'Prikazen Izaiju, sinu Amozovemu, ki jo je videl za Judo in za Jeruzalem v dneh Uzija, Jotama, Ahaza in Ezekija, kraljev Judovih.',
        2: 'Čujte, o nebesa, in poslušaj, o zemlja, kajti Gospod je govoril: Otroke sem vzredil in povišal, oni pa so se uprli zoper mene.',
        3: 'Vol pozna gospodarja svojega in osel gospoda svojega jasli, ali Izrael ne pozna, ljudstvo moje ne ume.',
        4: 'Gorje grešnemu narodu, ljudstvu obloženemu s krivdo, zarodu hudodelnikov, otrokom, ki popačeno ravnajo! Zapustili so Gospoda, zavrgli so Svetnika Izraelovega, odvrnili so se od njega.',
        5: 'Čemu naj bi vas še tepel, ko le bolj in bolj odpadate! Vsa glava je bolna in vse srce medlo.',
        6: 'Od stopala do temena ni nič zdravega na njem: zgolj rane in proge in vedno novi tvori, ki jih ne iztiskajo in ne obvezujejo in ne mečé z oljem.',
        7: 'Dežela vaša je pusta, mesta vaša so požgana z ognjem; zemlja vaša – tujci jo požirajo vpričo vas, in opustošena je že tako, kakor da so jo razdejali tujci.',
        8: 'In hči sionska je ostala zapuščena kakor koča v vinogradu, kakor hišica na kumarišču, kakor oblegano mesto.',
        9: 'Ko bi nam ne bil Gospod nad vojskami ostavil ostanka, čeprav majhnega, bi bili kakor Sodoma, bi bili podobni Gomori.',
        10: 'Čujte besedo Gospodovo, vodniki sodomski, poslušajte Boga našega postavo, ljudstvo gomorsko!',
        11: 'Čemu mi daritev vaših množina? pravi Gospod; sit sem žgalnih daritev ovnov in masti pitane živine ter krvi juncev in jagnjet in kozlov se ne veselim.',
        12: 'Ko prihajate, da se prikažete pred obličjem mojim – kdo je zahteval to od roke vaše, da teptate veže moje?',
        13: 'Ne prinašajte več daril ničevih! Kadilo mi je gnusoba; ob mlaju in v soboto in kadar sklicujete zbor, ne morem prenašati krivice in hkrati prazničnega zborovanja.',
        14: 'Mlaje vaše in praznike vaše sovraži duša moja, zoprni so mi, težko jih prenašam.',
        15: 'In ko iztezate roke svoje, skrivam oči svoje pred vami; ko tudi mnogo molite, ne slišim: roke vaše so polne krvi.',
        16: 'Umijte se, očistite se, odpravite hudobnost dejanj svojih izpred mojih oči, nehajte delati hudo;',
        17: 'učite se delati dobro, iščite pravice, tlačenemu pomagajte, pravico sodite siroti, potezajte se za vdovo!',
        18: 'Pridite vendar, in razložimo si pravdo svojo, pravi Gospod. Ako so grehi vaši kakor škrlat, bodo beli kakor sneg; ako so rdeči kakor karmezin, bodo beli kakor volna.',
        19: 'Če ugodite in boste poslušali, boste uživali dobrote dežele.',
        20: 'Ako pa se boste branili in se upirali, bodete pokončani z mečem; zakaj usta Gospodova so govorila.',
        21: 'O kako se je v nečistnico izprevrglo mesto zvesto! Polno je bilo pravice, pravičnost je stanovala v njem, a sedaj morilci!',
        22: 'Srebro tvoje se je izpremenilo v žlindro, žlahtno vino tvoje je z vodo zmešano.',
        23: 'Knezi tvoji so uporniki in tovariši tatov; vsak izmed njih ljubi darila in hodi za podkupili, siroti ne sodijo pravice in vdove pravda ne prihaja do njih.',
        24: 'Zato pravi Gospod, Jehova nad vojskami, Mogočni Izraelov: Aha, tolažbe si dobodem pri svojih nasprotnikih in maščeval se bom nad svojimi sovražniki.',
        25: 'In iztegnem roko svojo proti tebi, da dočista izžgem žlindro tvojo in odpravim vso primes kovine tvoje.',
        26: 'In zopet postavim sodnike tvoje, kakor so bili prej, in svetovalce tvoje kakor v začetku. Potem te bodo imenovali Mesto pravičnosti, zvesto mesto.',
        27: 'Sion bo odkupljen s sodbo in njegovi, ki se vrnejo, s pravičnostjo.',
        28: 'Ali odpadniki in grešniki bodo vsi hkrati strti, in kateri zapuste Gospoda, poginejo.',
        29: 'Zakaj osramočeni bodo spričo malikovalskih hrastov, ki ste jih želeli, in rdečica vas oblije zaradi vrtov, ki ste jih izvolili.',
        30: 'Kajti podobni bodete hrastu, ki mu vene listje, in podobni vrtu, ki nima nič vode.',
        31: 'In najhrabrejši bode kakor predivo in delo njegovo kakor iskra, in oboje bo gorelo skupaj, in ne bode nikogar, ki bi pogasil.',
    },
    2: {
        1: 'Beseda, ki jo je v prikazni slišal za Judo in Jeruzalem Izaija, sin Amozov.',
        2: 'In zgodi se v poslednjih dneh, da bo gora hiše Gospodove trdno postavljena na vrhu drugih gorá in povišana nad hribe, in vsi narodi se bodo stekali k njej.',
        3: 'In mnoga ljudstva pojdejo, govoreč: Pridite, da gremo na goro Gospodovo, v hišo Boga Jakobovega, da bi nas učil o potih svojih in da bomo hodili po stezah njegovih! Zakaj s Siona izide nauk in beseda Gospodova iz Jeruzalema;',
        4: 'in on bo sodil med narodi in pravico izvršil mnogim ljudstvom. In pokujejo meče svoje v lemeže in sulice svoje v srpe; narod ne dvigne meča nad narod, in več se ne bodo učili bojevati.',
        5: 'O hiša Jakobova, pridite in hodimo v svetlobi Gospodovi!',
        6: 'Kajti zavrgel si, Bog, ljudstvo svoje, hišo Jakobovo, ker so polni razvad z Jutrovega in so vedeži kakor Filistejci in se družijo z otroki tujcev.',
        7: 'In njih dežela je polna srebra in zlata in njih zakladom ni konca; polna je tudi njih dežela konj in njih vozom ni konca.',
        8: 'Polna je tudi njih dežela malikov; klanjajo se rok svojih delu, temu, kar so njih prstje storili.',
        9: 'A pripognjen bo človek prostak in ponižan bo mož odličnjak, ker jim ne moreš prizanesti.',
        10: 'Zlezi v pečino ter skrij se v prahu izpred groze Gospodove in izpred slave veličastva njegovega!',
        11: 'Ponižan bo človek prevzetnih oči in visokost človeška se potlači, in povišan bo Gospod sam tisti dan.',
        12: 'Kajti Gospod nad vojskami ima določen dan proti vsemu, kar je prevzetno in visoko, in proti vsakemu, ki se povišuje, da se poniža;',
        13: 'in proti vsem cedram na Libanonu, visokim in ponosnim, in proti vsem hrastom v Basanu',
        14: 'in proti vsem visokim goram in proti vsem vzvišenim gričem',
        15: 'in proti vsakemu visokemu stolpu in proti vsakemu trdnemu zidu',
        16: 'in proti vsem ladjam tarsiškim in proti vsem podobam najmilejšim.',
        17: 'Tedaj se potlači prevzetnost človeška in vzvišenost ljudi se poniža, in povišan bo Gospod sam tisti dan.',
        18: 'In maliki izginejo dočista.',
        19: 'In pojdejo v skalne brloge in v razpoke zemlje izpred groze Gospodove in izpred slave veličastva njegovega, kadar se vzdigne, da ostraši zemljo.',
        20: 'Tisti dan vrže človek krtom in netopirjem malike svoje srebrne in zlate malike svoje, ki so mu jih naredili, da se jim poklanja,',
        21: 'da bi zlezel v votline pečin in v skalne razpoke izpred groze Gospodove in izpred slave veličastva njegovega, ko se vzdigne, da ostraši zemljo.',
        22: 'Opustite up v človeka, ki mu je dihanje v nosu! kajti koliko ga je ceniti?',
    },
    3: {
        1: 'Kajti glej, Gospod, Jehova nad vojskami, vzame iz Jeruzalema in od Jude oporo in podporo, vso podporo kruha in vso podporo vode,',
        2: 'junaka in vojščaka, sodnika in proroka, vedeža in starca,',
        3: 'petdesetnika in veljaka, svetovalca in spretnega umetnika in izvedenca v čarovništvu.',
        4: 'In dati jim hočem dečke za kneze, in razposajenci jim bodo gospodovali.',
        5: 'In zatirali se bodo v ljudstvu med seboj, vsak svojega bližnjega; prešerno se bo vedel deček proti starcu in nizki proti imenitnemu.',
        6: 'Ako zgrabi brat brata v svojega očeta hiši, rekoč: Obleko imaš, vodnik nam bodi in ta razsip bodi pod tvojo roko!',
        7: 'zažene on svoj glas tisti dan in poreče: Ne morem biti ranocelnik, zakaj še kruha ni v hiši moji, ne obleke; nikar me ne stavite za vodnika ljudstvu!',
        8: 'Kajti Jeruzalem je porušen in Juda je padel, ker njih jezik in njih dejanja so zoper Gospoda, da dražijo oči slave njegove.',
        9: 'Pogled njih obraza priča zoper nje, in greh svoj razglašajo kakor Sodomljani, ga ne skrivajo. Gorje njih duši, ker pripravljajo hudo sami sebi.',
        10: 'Recite o pravičnem, da mu bode dobro; kajti uživali bodo dejanja svojega sad.',
        11: 'Gorje krivičnemu! hudo mu bode, ker se mu povrne, kar so zaslužile roke njegove.',
        12: 'Oni, ki tlačijo ljudstvo moje, so otroci, in ženske mu gospodujejo. O ljudstvo moje! oni, ki te vodijo, te zapeljujejo ter v zmešnjavo spravljajo stezo potov tvojih.',
        13: 'Gospod je nastopil, da začne pravdo, stoji, da sodi ljudstva.',
        14: 'Gospod se bliža, da bo sodil ljudstva svojega starejšine in kneze njegove: Vi ste, ki ste popasli ta vinograd, rop siromakov je v hišah vaših.',
        15: 'Zakaj tarete ljudstvo moje ter razbijate siromakom obličje? govori Gospod, Jehova nad vojskami.',
        16: 'Še pravi Gospod: Ker so hčere sionske prevzetne ter hodijo z napetim grlom in drzno migajoč z očmi in vedno stopajo z drobnimi stopinjami in rožljajo z obročki na nogah:',
        17: 'zato udari Gospod hčere sionske s plešo na temenu, in Gospod ogolí njih sramoto.',
        18: 'Tisti dan jim pobere Gospod lepotino obročkov na nogah in načelke in lunice,',
        19: 'ušesne zvončke, zapestne verižice, zastore,',
        20: 'oglavnice, drobilke na nogah, pasove, vonjalnice, amulete,',
        21: 'prstane in nosne obročke,',
        22: 'praznična oblačila in plašče, ogrinjače in mošnje,',
        23: 'ogledala, tenčice, turbane in lahka krila.',
        24: 'In zgodi se, da bode namesto dišave smrad po plesnobi in namesto pasa vrv in namesto spletenih las pleša in namesto dičnega plašča raševnik, opeklina namesto lepote.',
        25: 'Možje tvoji padejo od meča in junaki tvoji v vojski.',
        26: 'In vrata hčere sionske bodo žalovala in plakala, ko bo opustošena sedela na tleh.',
    },
    4: {
        1: 'In sedem žen zgrabi enega moža tisti dan, govoreč: Jed svojo bomo jedle in v obleko svojo se oblačile, samo da se imenujemo po tvojem imenu; odvzemi nam sramoto!',
        2: 'Tisti dan bode Odraslek Gospodov v diko in slavo in sad zemlje v odliko in hvalo njim, ki se ohranijo Izraelu.',
        3: 'In zgodi se: Kdor preostane na Sionu in kdor preostane v Jeruzalemu, ga bodo svetega imenovali, vsakega, ki je za življenje zapisan v Jeruzalemu;',
        4: 'ko bo Gospod opral nesnago hčer sionskih in kri, v Jeruzalemu prelito, poplaknil izsredi njega z duhom sodbe in z duhom pokončanja.',
        5: 'In Gospod ustvari nad vsakim prebivališčem gore Sionske in nad zbori njenimi oblak in dim po dnevi in svit plamtečega ognja po noči; zakaj nad vso slavo bo okrilje.',
        6: 'In koča bode za senčnico proti vročini po dnevi in za pribežališče in zavetje pred viharjem in pred dežjem.',
    },
    5: {
        1: 'Daj, da zapojem o ljubljencu svojem, ljubega svojega pesem o vinogradu njegovem: Vinograd je imel ljubljenec moj na griču prerodovitnem.',
        2: 'Prekopal ga je in mu potrebil kamenje in ga posadil s plemenitimi trtami; in sezidal je stolp sredi njega in tudi tlačilnico je izdolbel v njem. In je čakal, da obrodi grozdje, toda rodil je viniko.',
        3: 'Sedaj pa, prebivalci jeruzalemski in možje Judovi, sodite vendar med menoj in vinogradom mojim!',
        4: 'Kaj bi se še storilo vinogradu mojemu, česar bi ne bil že storil v njem? Zakaj, ko sem čakal, da obrodi grozdje, je rodil viniko?',
        5: 'Sedaj torej naj vam naznanim, kaj bom storil vinogradu svojemu: ograjo njegovo odpravim, da se bo paslo po njem, obzidje mu razvalim, da bodo teptali po njem.',
        6: 'Dam ga v opustošenje: ne bo se obrezaval ne okopaval, a grmovje požene v njem in trnje, vrhutega zapovem oblakom, naj ne izpuščajo dežja nanj.',
        7: 'Vinograd Gospoda nad vojskami je namreč hiša Izraelova in možje Judovi so rastlina radosti njegove. In ko je čakal pravoljubja, glej krvoprelitje, pravičnosti, a glej tožno vpitje!',
        8: 'Gorje vam, ki stikate hišo s hišo, ki devate njivo k njivi, da ni več prostora za druge, in vi sami prebivate sredi dežele!',
        9: 'Meni na ušesa je rekel Gospod nad vojskami: Res, mnoge hiše bodo opustošene, velike in lepe, da ne bode prebivalca.',
        10: 'Zakaj deset oral vinogradov bo dalo le eno vedro in homer semena bo dal efo.',
        11: 'Gorje jim, ki vstajajo rano zjutraj, da hodijo za pijačo opojno, ki sede pozno v noč, da jih vname vino!',
        12: 'Pri njih pojedinah so strune in harfe, bobnice in piščal in vino; ali dela Gospodovega ne gledajo in stvaritve rok njegovih ne premišljajo!',
        13: 'Zato pojde ljudstvo moje v sužnost, ker nima spoznanja; in imenitniki njegovi bodo stradali in množica njegova bode suha od žeje.',
        14: 'Zato poveča pekel pohlepnost svojo in razširi žrelo svoje brezmerno, in vanj pade Jeruzalemcev dika in njih množica s hrupom svojim in kdor se raduje med njimi.',
        15: 'In pripognjen bo človek prostak in ponižan mož odličnjak in oči prevzetnih se ponižajo.',
        16: 'A povišan bo Gospod nad vojskami po sodbi, in Bog mogočni, Sveti, se izkaže svetega v pravičnosti. –',
        17: 'In ovce se bodo ondi pasle kakor na pašniku svojem in tujci se bodo živili na opustošenih njivah bogatinov.',
        18: 'Gorje jim, ki vlečejo za seboj krivico z vrvmi ničemurnosti, greh pa kakor z debelo žrdjo!',
        19: 'ki govore: Hiti naj, pospeši naj delo svoje, da bomo videli; in približa se naj in pride, kar je sklenil Svetnik Izraelov, da to spoznamo!',
        20: 'Gorje jim, ki pravijo hudemu dobro in dobremu hudo, ki imajo temo za luč in luč za temo, ki delajo grenko za sladko in sladko za grenko!',
        21: 'Gorje jim, ki so modri v svojih očeh in razumni sami pri sebi!',
        22: 'Gorje jim, ki so junaki v pitju vina in vrli v mešanju pijače opojne;',
        23: 'ki opravičujejo krivičnega zaradi daru in pravičnim jemljejo njih pravico!',
        24: 'Zato kakor pokončuje strnišče ognja jezik in kakor gine suha trava od plamena, tako postane njih korenina kakor trhljad in njih cvet sprhne kakor prašek: ker so zaničevali postavo Gospoda nad vojskami in zavrgli besedo Svetnika Izraelovega.',
        25: 'Zato se je vnel srd Gospodov zoper ljudstvo njegovo, in je iztegnil roko svojo in ga udaril tako, da so se potresle gore, in njih trupla so bila kakor smetje po ulicah. Pri vsem tem se ne odvrne jeza Njegova, še je roka Njegova iztegnjena.',
        26: 'In povzdigne zastavo narodom iz daljave in jih sikajoč pokliče k sebi od kraja zemlje, in glej, hitro, urno pridejo.',
        27: 'Nobeden ne bo pešal in nobeden se zadeval med njimi, nobeden ne bo dremal, ne spal, tudi se ne bo razvezaval pas ledja njegovega in ne bo se trgalo jermenje obuvala njegovega.',
        28: 'Njih pšice bodo preostre in vsi njih loki napeti; njih konj kopita bodo podobna skali in njih kolesa podobna vrtincu.',
        29: 'Njih rjovenje bo kakor levinje, rjoveli bodo kakor mladi levi; in rohneč bodo zgrabili plen in ga odnesli na varno, in nihče jim ga ne iztrga.',
        30: 'In rohneli bodo nad Judo tisti dan, kakor ko besni morje; in če kdo pogleda na zemljo, glej, tema in stiska, in svetloba je otemnela vsled oblakov njenih.',
    },
    6: {
        1: 'V letu, ko je umrl kralj Uzija, sem videl Gospoda, sedečega na prestolu visokem in vzvišenem, in vlečke oblačila njegovega je bilo polno svetišče.',
        2: 'Serafi so mu stali odzgoraj, vsak je imel šest peruti: z dvema si je pokrival obličje in z dvema je pokrival noge in z dvema je letal.',
        3: 'In klicali so drug proti drugemu, govoreč: Svet, svet, svet Gospod nad vojskami, vsa zemlja je polna slave njegove!',
        4: 'In tresle so se podstave pragov od glasu kličočih in hiša se je napolnila z dimom.',
        5: 'Tedaj sem rekel: Gorje mi, ker poginem, kajti mož sem z nečistimi ustnami in bivam sredi ljudstva nečistih usten; zakaj oči moje so videle Kralja, Gospoda nad vojskami.',
        6: 'A prileti k meni tistih serafov eden, v roki držeč živ ogel, ki ga je bil s kleščami vzel z oltarja.',
        7: 'In ž njim se dotakne mojih ust in reče: Glej, to se je doteknilo usten tvojih; že je odvzeta krivica tvoja in greh tvoj je očiščen.',
        8: 'In slišal sem glas Gospodov, ki je dejal: Koga naj pošljem? in kdo nam pojde? Tedaj rečem: Glej, jaz; pošlji me!',
        9: 'In veli: Pojdi in reci temu ljudstvu: Poslušajoč čujte, a ne umejte, in gledajoč vidite, a ne spoznajte!',
        10: 'Stóri, da se odebeli temu ljudstvu srce, in zamaši mu ušesa in zatisni mu oči, da ne bi videli z očmi svojimi in ne slišali z ušesi svojimi in ne umeli s srcem svojim, da se ne izpreobrnejo ter jim ne pride zdravje.',
        11: 'Nato rečem: Doklej, Gospod? In odgovori: Dokler se ne opustošijo mesta, da ne bo prebivalca, in hiše, da bodo brez ljudi, in dokler ne bo dežela opustošena in zapuščena',
        12: 'in Gospod ne požene daleč ljudi ter bode veliko zapuščenih krajev v deželi.',
        13: 'In ako jih še desetina ostane v njej, pokonča se tudi ta; toda kakor od terebinte in od hrasta, ko se posekata, ostane korenika, tako je sveto seme njih korenika.',
    },
    7: {
        1: 'In zgodilo se je v dnevih Ahaza, sinu Jotama, sinu Uzija, kralja Judovega, da je šel Rezin, kralj sirski, in Pekah, sin Remalijev, kralj Izraelov, gori bojevat se zoper Jeruzalem; ali ni ga mogel vzeti.',
        2: 'In sporočili so hiši Davidovi, rekoč: Sirija se zanaša na Efraima! In srce njegovo je trepetalo in srce njegovega ljudstva, kakor trepečejo drevesa v gozdu od vetra.',
        3: 'Tedaj veli Gospod Izaiju: Pojdi vendar Ahazu naproti, ti in sin tvoj Šear-jašub, na konec vodotoka gornjega ribnika, proti potu ob valjalčevi njivi,',
        4: 'in mu povej: Pazi, da bodeš miren; ne boj se in srce naj se ti ne plaši spričo teh dveh glavenj, ki se toliko kadita, spričo razvnete jeze Rezina in Sirije in Remalijevega sina.',
        5: 'Ker je osnovala Sirija hudoben naklep zoper tebe, tudi Efraim in Remalijev sin, govoreč:',
        6: 'Idimo gori nad Judejo, da jo spravimo v strah ter jo siloma odpremo sebi in postavimo za kralja v njej Tabeelovega sina;',
        7: 'zato pravi tako Gospod Jehova: Ne zgodi se in ne bode tega.',
        8: 'Kajti Siriji je glava Damask in Damasku glava Rezin; in še po petinšestdesetih letih bo zrušen Efraim, da ne bode več ljudstvo.',
        9: 'In glava Efraimu je Samarija in Samariji glava sin Remalijev. Ako ne verjamete, zares, nimate obstanka.',
        10: 'In Gospod je še dalje govoril Ahazu, rekoč:',
        11: 'Prosi si znamenja od Gospoda, Boga svojega, prosi ga iz globočine ali z višine.',
        12: 'Ahaz pa reče: Ne bom prosil, ne izkušal Gospoda.',
        13: 'Nato reče prorok: Čujte torej, hiša Davidova! Je li vam kaj malega nadlegovati ljudi, da celo nadlegujete Boga mojega?',
        14: 'Zatorej vam da Gospod sam znamenje: Glej, devica bo spočela in rodila sina, in imenovala bo ime njegovo Imanuel.',
        15: 'Smetano in med bo jedel, ko bo vedel zametati hudo in voliti dobro.',
        16: 'Kajti še preden bo vedel ta deček zametati hudo in voliti dobro, bo zapuščena dežela, ki te je groza dveh kraljev njenih.',
        17: 'Gospod stori, da pridejo nad tebe in nad ljudstvo tvoje in nad hišo očeta tvojega dnevi, kakršnih ni bilo, odkar se je Efraim ločil od Jude: pripelje nadte kralja asirskega.',
        18: 'In zgodi se tisti dan, da Gospod požvižga muhi, ki je ob koncih potokov egiptovskih, in čebeli, ki je v deželi Asirski.',
        19: 'In pridejo in posedejo vse, kar jih je, po dolih med strminami in po skalnih razpokah in po vsem grmovju in po vseh pašnikih.',
        20: 'Tisti dan obrije Gospod z najeto britvijo, ki je onkraj velereke, namreč s kraljem asirskim, lase po glavi in po nogah, celó brado pokonča.',
        21: 'In v tistem času bode, da bo kdo redil le kravico in dve ovci,',
        22: 'a ker bo molzel obilo mleka, bo jedel smetano; kajti smetano in med bo jedel, kdorkoli preostane v deželi.',
        23: 'Zgodi se tudi v tistem času, da bo vsak kraj, kjer je bilo tisoč vinskih trt vrednih tisoč srebrnikov, preraslo grmovje in trnje.',
        24: 'S pšicami in z lokom bodo morali hoditi tja, ker bo z grmovjem in trnjem obrasla vsa dežela.',
        25: 'Na vse gore pa, ki so jih kopali z motiko, tja ne prideš boječ se grmovja in trnja, ondi pa bode kraj, kamor bodo izpuščali vole in po katerem bo teptala drobnica.',
    },
    8: {
        1: 'In Gospod mi je rekel: Vzemi si veliko ploščo in nanjo napiši z razločnimi črkami: Maher-šalal-haš-baz.',
        2: 'In vzel sem si zvesti priči: Urija, duhovnika, in Zeharija, sina Jeberekijevega.',
        3: 'In približal sem se prorokinji, in je spočela in rodila sina. Tedaj mi je rekel Gospod: Imenuj ga Maher-šalal-haš-baz.',
        4: 'Zakaj preden bo deček znal klicati ‚Oče moj‘in ‚Mati moja‘, bodo nesli bogastvo iz Damaska in plen iz Samarije v Asirijo pred kraljem asirskim.',
        5: 'In Gospod je zopet govoril k meni, rekoč:',
        6: 'Zato ker je to ljudstvo zaničevalo vodo v Siloahu, lahno tekočo, in mu je veselje pri Rezinu in Remalijevem sinu,',
        7: 'zato, glej, stori Gospod, da pridere nadnje voda velereke, presilna in preobilna, namreč kralj asirski in vsa slava njegova; in prestopi vse svoje struge in se prevali čez vse bregove svoje',
        8: 'in pridere na Judovo, ga preplavi in se razlije, da mu bo do grla segalo; in razpete peruti njegove napolnijo širokost dežele tvoje, Imanuel!',
        9: 'Združite se na upor, o ljudstva, a bodite potrti! In ušesa nagnite, kolikorkoli vas je po daljnih deželah! Opasujte se na boj in bodite potrti, opasujte se in bodite potrti!',
        10: 'Storite sklep, in uničen bo; govorite besedo, a ne obvelja; zakaj Bog je z nami!',
        11: 'Kajti tako mi je govoril Gospod, ko me je roka njegova močno prijela in ko me je učil, da mi ni hoditi po tega ljudstva potu, rekoč:',
        12: 'Ne imenujte zarotbe vsega, kar to ljudstvo imenuje zarotbo, in ne bojte se tega, česar se oni boje, in ne plašite se!',
        13: 'Gospoda nad vojskami samega posvečujte, in on vam bodi strah, on vam bodi groza.',
        14: 'In on vam bode v zavetno svetišče, toda za kamen spotike in skalo pohujšanja obema hišama Izraelovima, za zanko in za zadrgo prebivalcem jeruzalemskim.',
        15: 'In mnogo izmed njih se jih spotakne in padejo in bodo strti, se zapleto v mrežo in ujamejo.',
        16: 'Zaveži to pričevanje, zapečati postavo med mojimi učenci! –',
        17: 'In jaz bom čakal Gospoda, ki skriva obličje svoje pred hišo Jakobovo, in upal bom vanj.',
        18: 'Glej, jaz in otroci, ki mi jih je dal Gospod, smo za znamenja in predpodobe v Izraelu od Gospoda nad vojskami, ki prebiva na gori Sionski.',
        19: 'In ko vam poreko: Povprašajte rotilce mrtvih in vedeže, ki čivkajo in ki šepetajo, recite: Ali naj ne povprašuje ljudstvo Boga svojega? Za žive naj vpraša mrtve?',
        20: 'Postave in pričevanja naj se oklepajo! Ako ne govore po tej besedi, ni zanje jutranje zarje;',
        21: 'in bode se jim klatiti po deželi hudo pobitim in gladnim, in zgodi se, ko bodo stradali, da se bodo srdili in kleli s kraljem svojim in z Bogom svojim; in če se ozro kvišku',
        22: 'in če bodo gledali v tla: glej, povsod le nadloga in tema, tesnoben mrak; in bodo zagnani v gosto temo.',
    },
    9: {
        1: 'Toda ne ostane v temi dežela, ki je sedaj v stiski. V prejšnjem času je v zaničevanje spravil deželo Zebulonovo in deželo Neftalijevo, a v poslednjem jo pripravi v čast, ono na poti k morju, onkraj Jordana, Galilejo poganov.',
        2: 'Ljudstvo, ki je hodilo po temi, je videlo svetlobo veliko; in kateri so bivali v deželi smrtne sence, jim je zasijala luč.',
        3: 'Pomnožil si narod, povečal si mu veselje: veselé se pred teboj kakor v veselju ob žetvi in enako njim, ki se radujejo, ko plen delé.',
        4: 'Zakaj ti si zlomil bremena njegovega jarem in šibo za njegova pleča, palico zatiralca njegovega, kakor ob dnevi Madiana.',
        5: 'Kajti vsako obuvalo tistih, ki obuti stopajo v bojnem hrupu, in vsaka okrvavljena obleka se sežge, bode za jed ognju.',
        6: 'Zakaj dete nam je rojeno, sin nam je dan, in vladarstvo pride na ramo njegovo, in ime njegovo se bo imenovalo: Čudoviti, Svetovalec, Mogočni Bog, Oče večnosti, Knez miru.',
        7: 'Pomnoževanju njegovega vladarstva in miru ne bode konca na prestolu Davidovem in nad kraljestvom njegovim, da ga utrdi in podpre s pravico in pravičnostjo od tega časa do vekomaj. Gorečnost Gospoda nad vojskami stori to.',
        8: 'Besedo je poslal Gospod zoper Jakoba in je zadela Izraela.',
        9: 'In vse ljudstvo jo bo spoznalo, Efraim in prebivalci v Samariji, ki govore s ponosnim in prevzetnim srcem:',
        10: 'Opeka je razpadla, ali zidali bomo iz rezanega kamena, posekane so divje smokve, ali nadomestimo jih s cedrami.',
        11: 'A Gospod povzdigne zoper njega nasprotnike Rezinove in razdraži sovražnike njegove:',
        12: 'Sirce od vzhoda in Filistejce od zahoda, da požro Izraela na vsa usta. Pri vsem tem se ne odvrne jeza Njegova, a še je roka Njegova iztegnjena.',
        13: 'A to ljudstvo se ni obrnilo k njemu, ki ga tepe, in niso iskali Gospoda nad vojskami.',
        14: 'Zato bo Gospod odsekal Izraelu glavo in rep, vejevje palmovo in bičje na en dan.',
        15: 'Starček in imenitnik je glava, prorok pa, ki uči krivo, je rep.',
        16: 'Kajti voditelji tega ljudstva so zapeljivci in ti, katere vodijo, so pogubljeni.',
        17: 'Zato se mladeničev njegovih ne bo radoval Gospod in ne bo se usmilil sirot in vdov njegovih; zakaj vsi vkup so hinavci in hudobneži in vsaka usta govore budalost. Pri vsem tem se ne odvrne jeza Njegova, a še je roka Njegova iztegnjena.',
        18: 'Kajti krivičnost se je vnela kakor ogenj, pokončava trnje in grmovje, požiga gosto drevje v gozdu, vije se navzgor v debelih oblakih dima.',
        19: 'Od srda Gospoda nad vojskami je zemlja požgana, tudi ljudstvo je kakor paša ognju; nihče ne prizanaša bratu svojemu.',
        20: 'Požirajo na desno, pa vendar so lačni, in jedo na levo, pa vendar niso siti. Vsak jé svoje rame meso:',
        21: 'Manase Efraima in Efraim Manaseja, in oba skupaj sta zoper Judo. Pri vsem tem se ne odvrne jeza Njegova, a še je roka Njegova iztegnjena.',
    },
    10: {
        1: 'Gorje jim, ki sklepajo krivične postave, in pisateljem, ki spisujejo nadlogo,',
        2: 'da izpodrinejo siromake iz pravde in da ugrabijo pravico ubožcem ljudstva mojega, da jim bodo vdove za plen ter da oropajo sirote!',
        3: 'Kaj boste počeli ob dnevi obiskovanja in ob nevihti, ki pride iz daljave? h komu se zatečete za pomoč? in kam spravite bogastvo svoje?',
        4: 'Nič drugega vam ne bo mogoče, nego sključiti se med ujetniki in pasti med ubitimi. Pri vsem tem se ne odvrne jeza Njegova, a še je iztegnjena Njegova roka.',
        5: 'Gorje Asircu, ki je šiba jeze moje in palica v roki njegovi togota moja!',
        6: 'Nad hinavski rod ga pošljem in zoper ljudstvo, s katerim se srdim, mu dam povelje, da naj pleni plen in da naj ropa rop in naj jih potepta kakor na ulicah blato.',
        7: 'On seveda ne meni tako in srce njegovo ne misli tako; pogubiti mu je le namera in potrebiti narodov ne malo.',
        8: 'Kajti govori: Niso li vsi knezi moji tudi kralji?',
        9: 'Ni li Kalno kakor Karkemiš? ni li Hamat kakor Arpad? ni li kakor Damask Samarija?',
        10: 'Kakor je roka moja dosegla kraljestva malikov, katerih rezane podobe so bile lepše od jeruzalemskih in samarijskih –',
        11: 'ali ne bom, kakor sem storil Samariji in malikom njenim, enako storil Jeruzalemu in njegovim podobam?',
        12: 'Zato se zgodi, ko Gospod dovrši vse delo svoje na gori Sionski in v Jeruzalemu, da bom kaznoval sad prevzetnega srca kralja asirskega in bahanje ponosnih oči njegovih.',
        13: 'Kajti govoril je: Z roke svoje krepkostjo sem storil to in z modrostjo svojo, ker sem razumen; in premaknil sem ljudstvom meje in uplenil sem njih zaklade in pahnil kot mogočnjak s prestolov nje, ki so na njih sedeli;',
        14: 'in roka moja je dosegla kakor gnezdo bogastvo ljudstev, in kakor bi pobiral jajca zapuščena, sem obral vso deželo, in ni ga bilo, da bi bil ganil s perutjo ali odprl usta ali začivkal. –',
        15: 'Se li more ponašati sekira proti njemu, ki seka ž njo? ali rezilo se poviševati proti njemu, ki ga rabi? kakor da bi šiba vihtela njega, ki jo dviga, kakor da bi privzdigovala palica človeka, ki ni od lesa!',
        16: 'Zato pošlje Gospod, Jehova nad vojskami, med debeluhe njegove sušico, in pod slavo njegovo se vname požar, podoben ognjenemu požaru.',
        17: 'In luč Izraelova bode za ogenj in Svetnik njegov za plamen, ki zapali in požge grmovje in trnje njegovo en dan.',
        18: 'In pokonča slavo gozda njegovega in rodovitnih njiv njegovih z dušo in z mesom, da bode, kakor ko hira jetičnik.',
        19: 'In majhen bode ostanek drevja v gozdu njegovem, da ga bo deček mogel zapisati.',
        20: 'In zgodi se tisti dan, da se ne bode ostanek Izraelov in kdor se ohrani hiši Jakobovi več opiral nanj, ki jih je tepel, marveč opiral se bo na Gospoda, Svetnika Izraelovega, v resnici.',
        21: 'Ostanek se preobrne, ostanek Jakobov k mogočnemu Bogu.',
        22: 'Kajti ko bi bilo ljudstva tvojega, Izrael, kakor peska morskega, le ostanek se preobrne iz njega. Določeno je pokončanje, ki razliva obilno pravičnost.',
        23: 'Zakaj pokončanje, in to določeno, dovrši Gospod, Jehova nad vojskami, sredi vse zemlje.',
        24: 'Zatorej pravi tako Gospod, Jehova nad vojskami: Ne boj se, ljudstvo moje, ki prebivaš na Sionu, Asirca! S šibo te bo tepel in palico svojo bo vzdignil zoper tebe, kakor se je v Egiptu godilo.',
        25: 'Kajti še malo, prav malo časa, potem bode konec srditosti in jeza moja se obrne nanje, da jih pokonča.',
        26: 'In Gospod nad vojskami zavihti zoper njega bič kakor v poboju Madiancev pri skali Orebski; in palica Njegova bode nad morjem in jo vzdigne, kakor jo je vzdignil nad Egiptom.',
        27: 'In zgodi se v tistem času, da se razprta breme njegovo z rame tvoje in jarem njegov z vratu tvojega, da, jarem razpade spričo maziljenja.',
        28: 'Pride v Ajat, pojde skozi Migron, pri Mikmasu odloži prtljago svojo;',
        29: 'preidejo prelaz, veleč: v Gebi bo naše prenočišče! Rama trepeta, Gibea Savlova beži.',
        30: 'Glasno vpij, hči galimska! Poslušaj, o Lajsa! O ubožica Anatot!',
        31: 'Madmena beži, prebivalci gebimski so se zbrali, da pobegnejo.',
        32: 'Še danes se ustavi v Nobu, že zavihti roko svojo proti gori hčere sionske, proti hribu jeruzalemskemu. –',
        33: 'Glej, Gospod, Jehova nad vojskami, poseka veje z grozno močjo, in tisti, ki so visoke postave, bodo posekani, in prevzetni bodo ponižani;',
        34: 'in posekal bo gozdno goščavo z železom svojim, in Libanon pade po Veličastnem.',
    },
    11: {
        1: 'In mladika požene iz obsekanega debla Jesejevega, in odraslek iz korenin njegovih prinese sad;',
        2: 'in duh Gospodov bo počival nad njim, duh modrosti in razumnosti, duh sveta in moči, duh spoznanja in strahu Gospodovega.',
        3: 'In blagougodje njegovo bode v strahu Gospodovem; in ne bo sodil po videzu svojih oči, ne pravde odločeval po sluhu svojih ušes;',
        4: 'temuč v pravičnosti bo sodil siromake in nepristranski bo odločeval pravdo krotkim na zemlji. In udari zemljo s šibo svojih ust in z dihom usten svojih usmrti krivičnika.',
        5: 'In pravičnost bode ledij njegovih pas in zvestoba pas bedra njegovega.',
        6: 'In prebival bo volk z jagnjetom in leopard bo ležal pri kozliču, in tele in mladi lev in pitana ovca bodo skupaj, in majhen deček vodnik med njimi.',
        7: 'In krava in medvedka se bosta skupaj pasli, njuni mladiči skupaj ležali; lev pa bo jedel slamo kakor vol.',
        8: 'In dete dojeno se bo igralo nad modrasovo luknjo, in odstavljenec bo ročico vtikal v gadovo votlino.',
        9: 'Nič zlega ne bodo storili, nič pogubnega naredili po vsej gori svetosti moje; zakaj vsa zemlja bode polna spoznanja Gospodovega, kakor vode pokrivajo morja globočino.',
        10: 'In zgodi se v tistem času: po korenini Davidovi, ki stoji v znamenje ljudstvom, bodo vprašali poganski narodi; in počivališče njegovo bode slavno.',
        11: 'In zgodi se v tistem času, da iztegne zopet, v drugič, Gospod roko svojo, da odkupi ostanek ljudstva svojega, ki preostane v Asiriji, v Egiptu, v Patrosu, v Etiopiji, v Elamu, v Sinearju, v Hamatu in na otokih morskih.',
        12: 'In vzdigne znamenje poganskim narodom, in spravi vkup pregnance Izraelove in zbere razkropljence Judove od četverih koncev zemlje.',
        13: 'Izgine tudi zavist Efraimova, in zatiralci Judovi bodo zatrti; Efraim ne bo zavidal Judi in Juda ne bo ravnal sovražno z Efraimom.',
        14: 'A poletita na ramo Filistejcem proti zahodu, skupaj bosta plenila sinove jutrovih dežel; na Edomce in Moabce iztegneta roko svojo, in sinovi Amonovi jima bodo pokorni.',
        15: 'In Gospod s prokletjem uniči zaliv Egiptovskega morja, in zavihti roko svojo z žarom diha svojega nad velereko in jo udari ter razdeli na sedem tokov in stori, da bodo mogli iti čeznjo obuti.',
        16: 'In tako bo cesta napravljena ostanku ljudstva njegovega, kar ga preostane, iz Asirije, kakor je bila cesta Izraelu v dan, ko je šel gori iz dežele Egiptovske.',
    },
    12: {
        1: 'In tisti dan porečeš: Zahvaljujem te, o Gospod, ker si se jezil nad menoj, ali odvrnila se je jeza tvoja, in potolažil si me.',
        2: 'Glej, Bog mogočni je rešenje moje; upal bom in ne bode me strah, zakaj Gospod, Jehova, je moč in pesem moja, in on mi je bil v zveličanje!',
        3: 'In zajemali boste vodo iz studencev zveličanja,',
        4: 'in porečete tisti dan: Hvalite Gospoda, razglašajte ime njegovo, med ljudstvi oznanjujte dejanja njegova, spominjajte, da je vzvišeno ime njegovo.',
        5: 'Psalme pojte Gospodu, kajti prekrasno je storil; razvedi se to po vsej zemlji!',
        6: 'Glasno vpij in radostno poj, prebivalka sionska! zakaj velik je sredi tebe Svetnik Izraelov.',
    },
    13: {
        1: 'Prorokovanje o Babilonu, ki ga je v prikazni prejel Izaija, sin Amozov.',
        2: 'Na goli gori vzdignite zastavo, zaženite glas k njim, vihtite roko, da stopijo skozi vrata prvakov.',
        3: 'Jaz sem ukazal posvečencem svojim, tudi sem poklical na jezo svojo junake svoje, ki se radujejo v moji veličasti.',
        4: 'Množice glas se čuje na gorah kakor obilega ljudstva, hrup kraljestev narodov, ki so se zbrali! Gospod nad vojskami pregleduje vojno krdelo.',
        5: 'Prihajajo iz daljne dežele, od kraja nebes – Gospod in srda njegovega orodje – pogubit vso deželo Babilonsko.',
        6: 'Tulite, ker blizu je dan Gospodov, prihaja kot razdejanje od Vsegamogočnega.',
        7: 'Zatorej bodo omahovale vse roke in tajalo se bo vsako srce človeško;',
        8: 'in izbegani bodo, krč in bolečine jih zgrabijo, kakor porodnica bodo imeli bolečine; vsak bo strmel ob bližnjem svojem, zaripljeno obličje bode njih obličje.',
        9: 'Glej, dan Gospodov prihaja, grozoviten, poln srda in goreče jeze, da izpremeni v puščavo to deželo, da iztrebi njene grešnike iz nje.',
        10: 'Kajti zvezde nebes in njih ozvezdja ne bodo dajala luči svoje; mračno bode solnce ob vzhodu svojem, in mesec ne bo svetil z lučjo svojo.',
        11: 'In izpokorim naseljeno zemljo za njih hudobnost in brezbožnike za njih krivico, in konec storim napuhu prevzetnih ter silovitnikov ponos ponižam.',
        12: 'Storim, da bode mož dražji mimo prečistega zlata in človek mimo zlata ofirskega.',
        13: 'Zato hočem potresti nebesa, in zemlja se gane s svojega mesta v togoti Gospoda nad vojskami in v dan goreče jeze njegove.',
        14: 'In godilo se jim bo kakor srni splašeni in kakor čredi, ko je nihče ne zbira: obrnejo se vsak k svojemu ljudstvu in zbeže vsakteri v svojo deželo.',
        15: 'Vsak, kogar najdejo, bo preboden, in vsak, kogar zasačijo, pade od meča.',
        16: 'In njih otročiče bodo razbijali pred njih očmi, njih hiše bodo plenili in njih žene oskrunjali.',
        17: 'Glej, obudim zoper nje Medce, ki ne bodo čislali srebra in ne radovali se samega zlata.',
        18: 'In njih loki bodo prestreljevali mladeniče, in smilil se jim ne bo sad telesa, otrokom ne bo prizanašalo njih oko.',
        19: 'In Babilon, dika kraljestev, s katerim so se ponašali prevzetni Kaldejci, bode podoben Sodomi in Gomori, ki ju je Bog razdejal.',
        20: 'Ne bo se vekomaj v njem prebivalo, nihče se v njem ne nastani od roda do roda, tudi Arabec ne postavi tam šatora, niti pastirjem ne bodo tam počivale črede.',
        21: 'Ampak ležale bodo tam zverine puščave, in njih hiše bodo polne sov, in bivali bodo tam noji ter pošasti bodo tam skakale.',
        22: 'In volkovi bodo tulili po njih opustošenih palačah in šakali po njih zabavnih gradovih. Skoraj pa pride čas njegov, in dnevi njegovi se ne podaljšajo.',
    },
    14: {
        1: 'Zakaj Gospod se usmili Jakoba in še enkrat izvoli Izraela, in jih postavi na domača tla; in tujci se jim pridružijo ter se bodo oklepali hiše Jakobove.',
        2: 'In ljudstva jih vzemo pod svojo skrb ter jih pripeljejo na njih mesto; in hiša Izraelova si jih prisvoji v deželi Gospodovi, da bodo hlapci in dekle; tako bodo ujete peljali nje, katerim so bili prej ujetniki, in bodo gospodovali njim, ki so jih nekdaj tlačili.',
        3: 'In zgodi se tisti dan, ko ti Gospod podeli pokoj po trudu tvojem in po nepokoju tvojem in po trdi službi, v katero so te usužnjili,',
        4: 'da boš pravil to zabavljico o kralju babilonskem, ter porečeš: Kako je preminil tlačilec, kako je minilo oderuštvo!',
        5: 'Zlomil je Gospod palico krivičnikov, žezlo gospodovalčevo,',
        6: 'ki je tepel ljudstva v togoti z udarci neprenehoma, ki je gospodoval v jezi narodom z zatiranjem brez zadržka.',
        7: 'Pokojna, mirna je zdaj vsa zemlja; nastalo je glasno petje.',
        8: 'Tudi ciprese se radujejo nad teboj, cedre na Libanonu: „Odkar si se zvrnil, ne hodi nihče sem gori, da bi nas posekal!“',
        9: 'Pekel zdolaj se je vznemiril zaradi tebe, ker čaka prihoda tvojega: drami zavoljo tebe mrtve, vse mogotce zemlje, vsem kraljem narodov veli vstati s prestolov.',
        10: 'Vsi izpregovore tebi in poreko: „Tudi ti si brez moči kakor mi, nam si postal podoben?“',
        11: 'V pekel je stopilo veličastvo tvoje in strun tvojih šum. Glist je polno pod teboj in črv te pokriva.',
        12: 'Kako si padel z neba, o lucifer, jutranje zarje sin! kako si posekan na tla, ki si poraze napravljal narodom!',
        13: 'Ti si pač govoril v srcu svojem: V nebesa se dvignem, nad zvezde Boga mogočnega povišam prestol svoj, in sedel bom na gori zborovanja, na skrajnem severu.',
        14: 'Dvignem se nad višave, ogrnjene z oblaki, enak bodem Najvišjemu.',
        15: 'Ali pahnjen boš v pekel, v jamo najglobočjo.',
        16: 'Kateri te vidijo, te natanko ogledujejo in se ozirajo v te, govoreč: „Je li ta tisti mož, ki je majal zemljo, ki je pretresal kraljestva?',
        17: 'ki je delal iz naseljenega sveta puščavo in je podiral mesta ne njem, ki jetnikov svojih ni izpuščal domov?“',
        18: 'Vsi kralji narodov, kolikor jih je, so zaspali s častjo, vsak v hiši svoji;',
        19: 'tebe pa so vrgli daleč od tvojega groba kakor ostuden izrastek. Pokrit si z ubitimi, s prebodenimi z mečem, ki so jih vrgli v jamo in zasuli s kamenjem, si kakor razteptano truplo.',
        20: 'Ne združiš se ž njimi v grobu, ker si ugonabljal deželo svojo, moril ljudstvo svoje. Hudobnikov seme se ne bo imenovalo vekomaj.',
        21: 'Pripravite se, da pokoljete sinove njegove zaradi krivice njih očetov! Da ne vstanejo ter ne podedujejo dežele in površja zemlje ne napolnijo z mesti.',
        22: 'In vstanem zoper nje, govori Gospod nad vojskami, in iztrebim ime in ostanek Babilona, sina in vnuka, govori Gospod.',
        23: 'In naredim, da bode Babilon posestvo ježu in močvirje, in pometem ga z metlo pokončanja, govori Gospod nad vojskami.',
        24: 'Prisegel je Gospod nad vojskami, rekoč: Gotovo, kakor sem se namenil, tako se zgodi, in kakor sem sklenil, tako ostane:',
        25: 'da zdrobim Asurja v deželi svoji in ga pogazim na gorah svojih. Tako se jim razprta jarem njegov in njegovo breme jim pade z rame.',
        26: 'To je tisti sklep, ki je storjen nad vso zemljo, in to je roka, ki je iztegnjena nad vsemi narodi.',
        27: 'Zakaj Gospod nad vojskami je storil sklep, in kdo naj ga uniči? in roka njegova je iztegnjena, kdo naj jo odvrne?',
        28: 'V letu, v katerem je umrl kralj Ahaz, je bilo to prorokovanje:',
        29: 'Ne raduj se, ti vsa Filisteja, ker je zlomljena šiba, ki te je tepla; kajti iz korenine kačje pride modras, in sad njegov bode ognjen leteč zmaj.',
        30: 'In prvenci siromakov bodo pasli in ubožni počivali brez skrbi; a tvojo korenino pokončam z lakoto in ostanek tvoj pomori zmaj.',
        31: 'Tulite, vrata, vpij, mesto, obup te zgrabi, vsa Filisteja; kajti od severa prihaja sovražnik kakor dim in presledka ni v četah njegovih.',
        32: 'Kaj torej naj se odgovori poslancem narodovim? Da je Gospod ustanovil Sion in da ne njem dobé zavetje ubožci ljudstva njegovega.',
    },
    15: {
        1: 'Prorokovanje o Moabu. Res, po noči bo razdejan Ar Moabov, uničen; da, po noči bo razdejan Kir Moabov, uničen.',
        2: 'Pojdejo gori v tempelj in v Dibon na višave jokat; nad Nebom in nad Medebo bo tulil Moab, na vseh glavah njegovih bode pleša, ostrižena bo vsaka brada.',
        3: 'Po ulicah njegovih se bodo opasovali z raševnikom, po strehah njegovih in po trgih njegovih bo vse tulilo, razlivajoč se v solzah.',
        4: 'In vpil bo Hesbon in Eleale, do Jahaza se bo čul njih glas; zato bodo kričali vojščaki moabski, duša jim bo trepetala.',
        5: 'Duša moja vpije zaradi Moaba; ubežniki njegovi bežé v Zoar kakor k triletni junici; jokaje stopajo gori po klancu Luhitskem, ker na potu proti Horonaimu vpijejo o pogubi.',
        6: 'Kajti vode nimrimske se premenijo v puščavo; zakaj trava se je posušila, nežno zelišče vene, ni več zelenjave nobene.',
        7: 'Zato odneso ostanek svojega imetja, kolikor so še mogli spraviti, čez Vrbov potok.',
        8: 'Kajti tisto vpitje se razlega okoli po mejah moabskih, tja do Eglaima stokanje njegovo in do Ber-elima tuljenje njegovo.',
        9: 'Kajti vode dimonske so polne krvi; da, jaz pripravim še več nad Dimon: leva za nje, ki beže iz Moaba, in za ostanek v deželi.',
    },
    16: {
        1: 'Pošljite jagnje gospodovalcu dežele od Sele tja po puščavi do gore hčere sionske.',
        2: 'In zgodi se, da bodo hčere moabske ob brodih arnonskih kakor ptice tavajoče, kakor razpuščeno gnezdo.',
        3: 'Posvetuj se, odloči se; senco svojo, Sion, naredi temno kakor noč opoldne; skrij pregnance, tavajočega ne izdaj!',
        4: 'Bivajo naj pri tebi pregnanci moji, skrivališče bodi Moabu pred pokončevalcem! Kajti stiskalcu je določen konec, pokončevanje bo nehalo, zatiralci izginejo z zemlje.',
        5: 'In prestol se utrdi po milosti, in na njem bo sedel v resnici v šatoru Davidovem on, ki bo sodil in iskal pravice in bo vrlo izvrševal pravičnost.',
        6: 'Slišali smo o prevzetnosti Moabovi, da je silno ošaben, o napuhu njegovem in oholosti njegovi in togoti njegovi; bahanje njegovo je ničevo.',
        7: 'Zato bo tulil Moab nad Moabom, vsak bo tulil. Za grozdne gruče kir-haresetske boste zdihovali, zelo pobiti.',
        8: 'Kajti njive hesbonske so zvenile, tudi trta sibemska; narodov gospodje so razbili prelepe rozge njene: segale so tja do Jazerja, vile so se po puščavi, mladike njene so se razširjale, šle čez morje.',
        9: 'Zato jokam z jokom Jazerjevim za trto sibemsko, rosim te s solzami svojimi, o Hesbon in Eleale; kajti ob spravljanju letnih sadežev tvojih in ob trgatvi tvoji te je doletelo bojno vpitje.',
        10: 'In vzeto je veselje in radovanje z rodovitnega polja, in v vinogradih ne pojo, ni veselega vpitja, vina v kadi ne masti tlačilec; petju v tlačilnici sem naredil konec.',
        11: 'Zato zveni kakor harfa osrčje moje zavoljo Moaba in moj drob zaradi Kir-heresa.',
        12: 'In zgodi se, ko se Moab prikaže, ko se bo trudil na mališki višavi in stopi v svetišče svoje, da bi molil, da nič ne opravi.',
        13: 'To je beseda, ki jo je Gospod takrat govoril o Moabu.',
        14: 'Sedaj pa govori Gospod takole: V treh letih, kakor so leta najemnikova, pride slava Moabova v nečast z vso svojo veliko množico vred; in ostanek bode jako majhen in neznaten.',
    },
    17: {
        1: 'Prorokovanje o Damasku. Glej, Damask neha biti mesto in bode kup razvalin.',
        2: 'Mesta aroerska so prazna, prepuščena čredam, ki bodo ondi ležale, in nihče jih ne bo plašil.',
        3: 'In konec bode trdnjavi v Efraimu in kraljestvu v Damasku, tudi ostanku Sirije: ž njimi bode kakor s slavo sinov Izraelovih, govori Gospod nad vojskami.',
        4: 'Zgodi se pa v tistem času, da se zmanjša slava Jakobova in shujša mesa njegovega tolšča.',
        5: 'In bode, kakor če kdo ob žetvi prijema žitna stebla in z ramo svojo žanje klase; bode, pravim, kakor če kdo pobira klasje v dolini Refaimov.',
        6: 'Vendar pa ostanejo paberki v njem, kakor ko se otrese oljka in dvoje ali troje jagod obvisi v vršiču drevesa, četvero ali petero na vejah rodovitnega debla, govori Gospod, Bog Izraelov.',
        7: 'V tistem času se bo oziral človek v Stvarnika svojega in oči njegove bodo gledale na Svetnika Izraelovega.',
        8: 'In ne bo se oziral v oltarje, v delo rok svojih; tudi ne bo gledal tega, kar so storili prstje njegovi, ne Ašer, ne solnčnih stebrov.',
        9: 'V tistem času bodo trdna mesta njegova podobna zapuščenim podrtinam v gozdu in na vrhu gorá, ki so jih zapustili Kanaanci pred sinovi Izraelovimi, in bode pustinja.',
        10: 'Ker si pozabil Boga zveličanja svojega in se nisi spominjal Skale moči svoje: zato si napravljaš prelepe nasade in jih obsajaš z inostranskimi trtami;',
        11: 'v dan, ko jih sadiš, jih precej ogradiš, in zjutraj skrbiš, da se razcvete seme tvoje – a žetev ti izgine v dan bridkosti in smrtne bolečine.',
        12: 'Gorje, upor ljudstev mnogobrojnih, ki šume kakor šume morja! in bučanje narodov, ki je kakor bučanje mogočnih vodá!',
        13: 'Narodi buče kakor velike vode bučeče! A On se zadere nad njimi, in pobegnejo kar najdalje, in podili se bodo kakor pleva na gorah pred vetrom in kakor se prah vrtinči v nevihti.',
        14: 'Ob času večernem, glej, smrtni strah! in preden nastane jutro, jih ni več. To je delež njih, ki nas plenijo, in usoda njih, ki naše siloma jemljejo.',
    },
    18: {
        1: 'Gorje deželi s šumečimi perutmi, ki je onkraj rek etiopskih,',
        2: 'ki pošilja poslance po morju in v ladjah iz papirovega trstja po površju vodá: Pojdite, hitri sli, k narodu visoke postave in gladkemu, k ljudstvu strahovitemu od svojega začetka in doslej, k narodu, ki strogo zapoveduje in vse tepta, čigar deželo cepijo reke.',
        3: 'Vsi prebivalci naseljenega sveta in stanovalci zemeljski, ko se povzdigne zastava na gorah, glejte tja, ko se zatrobi na trombo, čujte!',
        4: 'Kajti tako mi je rekel Gospod: Mirno hočem gledati v svojem prebivališču, bom kakor jasna vročina ob solnčnem svitu, kakor gosta rosa ob gorki žetvi.',
        5: 'Kajti pred trgatvijo, ko je trtje odcvetlo in jagode dozorevajo, poreže trte s kosirjem in odpravi ročice, poseče.',
        6: 'Vsi vkup bodo prepuščeni ropnim pticam gorskim in zemeljskim zverinam, in ropne ptice prežive na njih leto, vse zveri zemeljske pa bodo zimovale na njih.',
        7: 'V tistem času prineso Gospodu nad vojskami v dar: ljudstvo visoke postave in gladko; in ljudstvo strahovito od svojega začetka in doslej, narod, ki strogo zapoveduje in vse tepta, čigar deželo cepijo reke, pride na mesto imena Gospoda nad vojskami, na goro Sionsko.',
    },
    19: {
        1: 'Prorokovanje o Egiptu. Glej, Gospod, sedeč na hitrem oblaku, pride v Egipt; in maliki egiptovski bodo trepetali pred njegovim obličjem in Egipčanom se bo srce tajalo v životu.',
        2: 'In razdražim, pravi, Egipčane med seboj, da se bodo bojevali vsak zoper svojega brata in vsak zoper prijatelja svojega, mesto zoper mesto, kraljestvo zoper kraljestvo.',
        3: 'In duh Egiptov bo opešal sredi njega, in uničim svet njegov, in popraševali bodo malike in zaklinjalce duhov in rotilce mrtvih in vedeže.',
        4: 'In zaklenem Egipčane v roko trdega gospoda, in neusmiljen kralj jim bo gospodoval, pravi Gospod, Jehova nad vojskami.',
        5: 'In vode se razteko iz morja, in reka se posuši in usahne,',
        6: 'in panoge reke bodo smrdele, vodotoki Spodnjega Egipta postanejo plitvi in se posuše, trstje in ločje zvene.',
        7: 'Trate poleg Nila, ob potokih njegovih in vsa setev ob potokih usahne, izgine in ne bode je več.',
        8: 'Tedaj bodo žalovali ribiči in plakali vsi, ki mečejo trnke v Nil, in kateri razgrinjajo mrežo po vodnem površju, bodo medleli.',
        9: 'In rdečica oblije nje, ki obdelujejo omikani lan in ki tkó bombaževino.',
        10: 'In stebri države bodo potrti, vsi, ki delajo za plačilo, bodo žalostni v duši.',
        11: 'Zgolj neumneži so knezi zoanski, kar so svetovali modri svetovalci Faraonovi, se je izkazalo abotno. Kako morete praviti Faraonu: „Modrijanov sin sem, sin kraljev starodavnih“?',
        12: 'Kje neki so modrijani tvoji? Naj ti vendar naznanijo in naj spoznajo, kaj je sklenil Gospod nad vojskami zoper Egipt!',
        13: 'Pamet so izgubili knezi zoanski, prevarani so knezi v Nofu; zapeljali so Egipt, kateri so vogelni kameni njegovim rodom.',
        14: 'Gospod je razlil sredi njega duha vrtoglavosti, in povzročili so, da je Egipt taval v vseh dejanjih svojih, kakor se bljujoč zaletava pijanec.',
        15: 'In Egipt ne bo imel nikogar, ki bi kaj prav dovršil, bodisi glava ali rep, palmova veja ali trst.',
        16: 'Tisti dan bodo Egipčani podobni ženskam, ker bodo v trepetu in strahu zavoljo vihteče roke Gospoda nad vojskami, ki jo bo vihtel proti njim.',
        17: 'In dežela Judova bode Egiptu v strah: kadar jo omeni kdo pri Egipčanih, se bodo tresli zavoljo sklepa Gospoda nad vojskami, ki ga je sklenil zoper nje.',
        18: 'Tisti dan bode v deželi Egiptovski petero mest, ki bodo govorila v jeziku kanaanskem in prisegala pri Gospodu nad vojskami; eno se bo imenovalo Ir-heres.',
        19: 'Tisti dan bo imel Gospod oltar sredi dežele Egiptovske in spomenik Gospodu bo stal blizu njene meje.',
        20: 'In to bode v znamenje in v pričevanje za Gospoda nad vojskami v deželi Egiptovski; zakaj klicali bodo h Gospodu zaradi zatiralcev, in pošlje jim rešitelja in branilca in jih otme.',
        21: 'In Gospod se razodene Egipčanom, in spoznajo Egipčani Gospoda tisti dan, in služili mu bodo s klalnimi in jedilnimi daritvami in obljube bodo delali Gospodu in jih izpolnjevali.',
        22: 'Tako udari Gospod Egipt; udari ga in zopet ozdravi; in obrnejo se do Gospoda, in dá se jim izprositi ter jih ozdravi.',
        23: 'Tisti dan bode iz Egipta v Asirijo cesta, po kateri bodo hodili Asirci v Egipt in Egipčani v Asirijo, in Egipčani bodo služili Gospodu z Asirci.',
        24: 'Tisti dan bode Izrael tretji v zvezi z Egiptom in z Asirijo, blagoslov sredi zemlje;',
        25: 'zato ker ga Gospod nad vojskami blagoslovi, govoreč: Blagoslovljeno bodi ljudstvo moje, Egipt, in rok mojih delo, Asirija, in Izrael, dediščina moja!',
    },
    20: {
        1: 'V letu, ko je prišel Tartan v Asdod, poslan od Sargona, kralja asirskega, in ko je oblegal Asdod in ga zmagal,',
        2: 'v tistem času je govoril Gospod po Izaiju, sinu Amozovem, rekoč: Pojdi in sleci si tisti raševnik z ledij in sezuj obuvalo z nog svojih. In storil je tako, hodeč slečen in bos.',
        3: 'Tedaj reče Gospod: Kakor je hodil hlapec moj Izaija slečen in bos tri leta v znamenje in zgled Egiptu in Etiopiji:',
        4: 'tako odpelje kralj asirski usužnjene Egipčane in pregnane Etiopce, mlade in stare, slečene in bose in z nago zadnjo oplatjo, Egiptu v sramoto.',
        5: 'In bodo prestrašeni in se bodo sramovali Etiopije, ki so vanjo upali, in Egipta, s katerim so se hvalili.',
        6: 'In prebivalci tega primorja poreko tisti dan: Glejte, takšno je upanje naše, kamor smo se zatekali po pomoč, da bi bili oteti izpred kralja asirskega! In kako bi mogli ubežati mi?',
    },
    21: {
        1: 'Prorokovanje o morski puščavi. Kakor besné silni viharji na Jugu, tako pride poguba iz puščave, iz grozovite dežele.',
        2: 'Prikazen trda se mi poroča: „Nezvestnik ravna nezvesto in pokončevalec pokončuje. Idi gori, Elam! oblezite ga, o Medi! Vsemu zdihovanju pred njim storim konec.“',
        3: 'Vsled tega so ledja moja polna bolečine, muke me popadajo kakor muke porodnice; krč me vije, da ne slišim, prestrašen sem, da ne vidim.',
        4: 'Srce mi divje polje, groza me plaši; mrak, ki sem ga želel, mi je napravil trepetanje.',
        5: 'Pripravljajo mizo, postavljajo stražo, jedo, pijejo... „Vstanite, o knezi, mažite ščit!“–',
        6: 'Kajti tako mi je velel Gospod: Pojdi, postavi pazuna; kar bo videl, naj naznani!',
        7: 'In videl je vozove, dvojne jahače, jezdece na oslih in jezdece na velblodih. In poslušal je napeto, z največjo pozornostjo,',
        8: 'in je zavpil kakor lev: Gospod, na stražnem stolpu vedno stojim po dnevi in pazeč postajam cele noči;',
        9: 'in glej, v tem prihaja truma mož, dvojni jahači... In je izpregovoril, rekoč: „Padel je, padel Babilon, in vse izdolbene podobe bogov njegovih je treščil ob tla!“',
        10: 'O mlatev moja in žito gumna mojega! Kar sem slišal od Gospoda nad vojskami, Boga Izraelovega, sem vam oznanil.',
        11: 'Prorokovanje o Dumi. K meni kličejo iz Seira: Čuvaj, mine li skoraj noč? Čuvaj, mine li skoraj noč?',
        12: 'Čuvaj pravi: Pride jutro, pa tudi noč. Če hočete vpraševati, vprašajte; vrnite se, pridite!',
        13: 'Prokovanje o Arabiji. Po gozdih v Arabiji boste prenočevale, o potujoče čete Dedancev!',
        14: 'Prinesite žejnemu naproti vode! Prebivalci Temske pokrajine naj postrežejo s kruhom ubežniku!',
        15: 'Kajti beže zaradi mečev, pred potegnjenim mečem in pred napetim lokom in pred nadlogami vojne.',
        16: 'Zakaj tako mi je dejal Gospod: V enem letu, kakor so leta najemnikova, propade vsa slava kedarska.',
        17: 'In preostalo število lokostrelcev junakov in sinov kedarskih bode neznatno; kajti Jehova, Bog Izraelov, je govoril to.',
    },
    22: {
        1: 'Prorokovanje o dolini prikazni. Kaj ti je že, da si stopilo vse na strehe?',
        2: 'O ropota polno, hrumeče mesto, o grad, radosti poln! Prebodeni tvoji niso prebodeni z mečem in ne umorjeni v vojski.',
        3: 'Vsi voditelji tvoji so zbežali skupaj, zvezani so bili, ne da bi bil kdo lok napel zoper nje; kar se je zasačilo tvojih, so bili zvezani skupaj, dasi so hoteli daleč zbežati.',
        4: 'Zato pravim: Obrnite se od mene, da bridko jočem; ne trudite se, tolažeč me zaradi pokončanja hčere ljudstva mojega!',
        5: 'Kajti dan je prestrašenja in teptanja in zmešnjave od Gospoda, Jehove nad vojskami, v dolini prikazni, dan podiranja zidu in kričanja proti gori.',
        6: 'In Elam nosi tul, pelje zasedene vozove in konjike, in Kir odkriva ščit.',
        7: 'In zgodi se, da bodo tvoje izbrane doline polne voz, in konjiki se razpostavijo proti vratom.',
        8: 'In odgrnejo ogrinjalo Judovo. In oziral se boš tisti dan po orožju v gozdni hiši.',
        9: 'In ogledujoč razpoke mesta Davidovega, vidite, da jih je mnogo; in nabirate vode iz spodnjega ribnika;',
        10: 'in štejete hiše jeruzalemske in podirate hiše, da utrdite zid;',
        11: 'in nabirališče delate med dvema zidoma za vode starega ribnika – ali ne ozirate se v Njega, ki je to naredil, in ne gledate Njega, ki je to osnoval zdavnaj.',
        12: 'Gospod, Jehova nad vojskami, pač kliče tisti dan na jok in plakanje in britje in opasovanje z raševino,',
        13: 'ali glej: pri vas radost in veselje, pobijanje goved in klanje drobnice, uživanje mesa in pitje vina: „Jejmo in pijmo, kajti jutri umremo!“',
        14: 'A razodel se je Gospod nad vojskami ušesom mojim: Res, ta krivica vam ne bo odpuščena, dokler ne umrete! govori Gospod, Jehova nad vojskami.',
        15: 'Tako pravi Gospod, Jehova nad vojskami: Dej, stopi k tistemu oskrbniku, Sebnu, ki gospoduje hiši, in reci:',
        16: 'Kaj hočeš ti tukaj? in koga imaš tukaj, da si tu izsekal grob sebi? izsekavaš si grob na višini, votliš v skali prebivališče sebi!',
        17: 'Glej, Gospod te s silo stran vrže kakor močan mož in krepko te zgrabi',
        18: 'in trdo te zvije v klobčič, kakor kepo te vrže v kraj prostoren; tam umreš in tam ostanejo slavni vozovi tvoji, ti sramota hiši gospodarja svojega!',
        19: 'Odslovim te iz službe tvoje, s stališča tvojega te zvrnejo.',
        20: 'In zgodi se tisti dan, da pokličem hlapca svojega Eljakima, Hilkijevega sina.',
        21: 'In oblečem ga v suknjo tvojo in ga utrdim s tvojim pasom, in tvoje gospostvo dam njemu v roke, in bode za očeta prebivalcem jeruzalemskim in hiši Judovi.',
        22: 'In ključ hiše Davidove položim na ramo njegovo: ko on odpre, nihče ne zapre, in ko zapre, nihče ne odpre.',
        23: 'In zabijem ga kakor klin na trdnem mestu, in za časten prestol bode očetovi hiši svoji.',
        24: 'Nanj obesijo vso slavo očetove hiše njegove: mladike in izrastke, vsako posodico, od pitnih posod do vrčev. –',
        25: 'Tisti dan, govori Gospod nad vojskami, se gane tisti klin, ki je bil zabit na trdnem mestu, in se zlomi in pade, breme pa, ki je na njem viselo, izgine; kajti Gospod nad vojskami je govoril.',
    },
    23: {
        1: 'Prorokovanje o Tiru. Tulite, ladje tarsiške! kajti opustošen je Tir, da ni hiše nobene, nobenega vhoda več. Iz dežele Kitimske jim je prišlo naznanilo.',
        2: 'Molčite, prebivalci otoka Tirskega! Kupci sidonski, ki se prepeljavajo po morju, so te napolnjevali;',
        3: 'in po velikih vodah je bila setev Sihorjeva, žetev Nilova njegov pridelek, in bil je tržišče narodom.',
        4: 'Sram te bodi, Sidon, ker morje govori, trdnjava morska pravi: Nisem imela porodnih bolečin, nisem porodila, ne vzredila mladeničev, ne odgojila devic.',
        5: 'Ko pride poročilo v Egipt, bodo trepetali ob tem naznanilu iz Tira.',
        6: 'Pojdite na drugo stran v Tarsis; tulite, prebivalci na otoku!',
        7: 'Je li to vaše veselo mesto, ki mu je postanek od starodavnih dni, ki ga noge vodijo, da se naseli v daljavi?',
        8: 'Kdo je sklenil to zoper Tir, ki je dajal krone drugim, katerega kupci so bili knezi, katerega trgovci najbolj češčeni na zemlji?',
        9: 'Gospod nad vojskami je sklenil to, da oskruni vse slave napuh, da spravi v zaničevanje vse najbolj češčene na zemlji.',
        10: 'Razlij se po deželi svoji kakor Nil, o hči tarsiška; ni več brzde zate.',
        11: 'Roko svojo je iztegnil Bog čez morje, potresel je kraljestva; Gospod je ukazal zoper Kanaana pogubiti trdnjave njegove',
        12: 'in je velel: Nič več se ne raduj, o devica oskrunjena, hči sidonska! Vstani, pojdi na ono stran v Kitim; tudi tam ti ne bode pokoja.',
        13: 'Glej deželo Kaldejcev – to ljudstvo, ki ga prej ni bilo (Asur jo je določil zverem v puščavi), si gradi obležne stolpe, razdeva palače njegove, ga ruši v razvaline.',
        14: 'Tulite, ladje tarsiške, ker je trdnjava vaša pokončana!',
        15: 'In zgodi se v tistem času, da bo Tir pozabljen sedemdeset let, kolikor je življenja enega kralja; ko preteče sedemdeset let, se bo godilo Tiru, kakor se poje v pesmi o vlačugi:',
        16: '„Vzemi strune, hodi po mestu, o vlačuga pozabljena! vrlo bij na strune, pevaj pridno, da se ponovi spomin tvoj.“',
        17: 'Zgodi se namreč, ko preteče sedemdeset let, da obišče Gospod Tir, ki se povrne k svojemu zaslužku in bode ljubovnica vsem kraljestvom zemlje, po vsem svetu.',
        18: 'A njegova kupčija in zaslužek njegov bode svet Gospodu, ne položi se v zaklad in shranjeval se ne bo; kajti njegova kupčija bode za nje, ki stanujejo pred Gospodom, da jedo dositega in se krasno oblačijo.',
    },
    24: {
        1: 'Glej, Gospod izprazni deželo in jo pokonča; in preobrnivši ji lice, razkropi prebivalce njene.',
        2: 'In godilo se bo kakor ljudstvu tako duhovniku, kakor hlapcu tako gospodarju njegovemu, kakor dekli tako gospodinji njeni, kakor kupcu tako prodajalcu, kakor posojevalcu tako njemu, ki naposodo jemlje, kakor dolžniku tako upniku njegovemu.',
        3: 'Docela bo izpraznjena dežela in vsa oplenjena, kajti Gospod je govoril to besedo.',
        4: 'Žaluje, vene dežela; medli in hira naseljeni svet; medlé prvaki ljudstva v deželi.',
        5: 'Tudi zemlja je oskrunjena pod prebivalci svojimi, ker so prestopali zakone, preobračali postavne naredbe, prelomili večno zavezo.',
        6: 'Zato je prokletstvo požrlo zemljo, in pokoriti se morajo, ki prebivajo na njej; zato so pogoreli prebivalci zemlje, in malo ljudi je ostalo.',
        7: 'Žaluje trgatev, hira trta, zdihujejo vsi, ki so bili veselega srca.',
        8: 'Konec je veselju bobnov, minil je radujočih se šum, konec je radosti strun.',
        9: 'S petjem ne bodo več pili vina, grenela bo opojna pijača njim, ki jo pijo.',
        10: 'Razdrto je mesto zmešnjave; zaprta je sleherna hiša, ni več nobenega vhoda.',
        11: 'Jadikovanje zaradi vina je po ulicah; zatonilo je vse veselje, izginila je radost zemlje.',
        12: 'Po mestu je ostalo le razdejanje, in v razvaline so razbita vrata.',
        13: 'Kajti tako se bo godilo sredi zemlje, med ljudstvi, kakor ko se otresajo oljke, kakor ob paberkovanju, ko je trgatev končana.',
        14: 'Ti ohranjenci bodo zagnali svoj glas, veselo bodo peli. Zaradi veličasti Gospodove se močno oglašajo tam od morja:',
        15: 'Zato poveličujte Gospoda v jutrovih krajih, ime Gospoda, Boga Izraelovega, na otokih morskih!',
        16: 'Od zadnjega kraja zemlje čujemo petje: Slava pravičnemu! – A jaz pravim: Hiram, hiram, gorje mi! Nezvestniki ravnajo nezvesto in krivičen rop ropajo roparji!',
        17: 'Groza in jama in zadrga ti prete, o prebivalec zemlje!',
        18: 'In zgodi se, da kdor zbeži, ker začuje grozo, pade v jamo; in kdor prileze iz jame, se ujame v zadrgo. Kajti zatvornice se odpro na višavi, in stresnejo se podslombe zemlje.',
        19: 'Zemlja se vsepovsod podere, zemlja vsa se razpoči, zemlja se bo hudo majala;',
        20: 'zemlja bo omahovala kakor pijanec, zibala se bo kakor viseča rogoznica; in hudo jo bo težila pregreha njena, in padla bo, da več ne vstane.',
        21: 'In zgodi se tisti dan, da bo Gospod kaznoval vojsko višave na višavi in pozemeljske kralje na zemlji.',
        22: 'In zbrani bodo, kakor zbirajo ujetnike v zaporu, in bodo vklenjeni in čez mnogo dni bodo obiskani.',
        23: 'Tedaj se zastre mesec s sramom in solnce se bo sramovalo, zakaj Gospod nad vojskami bo kraljeval na gori Sionu in v Jeruzalemu, in pred starejšinami njegovimi bode slava.',
    },
    25: {
        1: 'O Gospod, ti si moj Bog; poviševal te bom, poveličeval ime tvoje; kajti storil si čuda, sklepe od starodavna, zvestobo in resnico.',
        2: 'Zakaj naredil si kup kamenja iz mesta, iz trdnega gradu razvalino, tujcev palačo si podrl, da ne bodi več mesto, na veke se ne sezida.',
        3: 'Zato te bo slavilo mogočno ljudstvo, mesta silovitih narodov te bodo častila.',
        4: 'Kajti bil si grad siromaku, grad potrebnemu, ko je bil v stiski, zavetje pred nevihto, senca pred vročino, ko je bilo srdito pihanje silovitnikov podobno nalivu, ki podira zid.',
        5: 'Kakor vročina na suhem kraju skrči vse, tako si ukrotil tujcev ropotanje, kakor oblakova senca uteši vročino, si zadušil zmagovalno petje silovitnikov.',
        6: 'In Gospod nad vojskami napravi vsem ljudstvom na tej gori gostovanje z mastnimi jedili, gostovanje s čistim vinom, pojedino s tolstimi pitanci, z vinom, očiščenim droži.',
        7: 'In na tej gori uniči tisto zagrinjalo, ki zagrinja vsa ljudstva, in tisti zastor, ki je razprostrt čez vse narode.',
        8: 'Smrt bo požrta za vekomaj; in Gospod, Jehova, obriše solze z obličij vseh in ljudstva svojega sramoto odpravi z vse zemlje. Kajti govoril je Gospod.',
        9: 'In poreko tisti dan: Glej, Bog naš je ta! čakali smo ga, da nas reši; ta je Gospod, ki smo ga čakali! Poskakovali bomo in se radovali zveličanja njegovega!',
        10: 'Zakaj na tej gori bo počivala roka Gospodova; in Moab bo poteptan na mestu svojem, kakor se tepta slama v gnojnici.',
        11: 'In razpne roke svoje v deželi svoji, kakor jih razpenja plavač, da bi plaval; On pa poniža prevzetnost njegovo, čeprav je tako umetnih rok.',
        12: 'In trdnjave tvojih trdnih, visokih zidov zvrne, podere in zruši na tla, prav v prah.',
    },
    26: {
        1: 'Tisti dan bodo peli to pesem v deželi Judovi: Trdno mesto imamo; zveličanje nam Bog postavlja za obzidje in nasip.',
        2: 'Odprite vrata, da vnide narod pravični, ki hrani vso zvestobo.',
        3: 'Njemu, ki je stanoviten v misli, hraniš večni mir, ker upa vate.',
        4: 'Upajte v Gospoda vekomaj, kajti v Gospodu Jehovi je skala vekov.',
        5: 'Zakaj on je ponižal stanujoče na visokem, ponižal je kvišku moleči grad; podrl jih je, zvrnil na tla, položil prav v prah.',
        6: 'Tepta jih noga, ubožcev noge, siromakov stopinje.',
        7: 'Pot pravičnega je ravna; naravnost ravnaš stezo pravičnemu.',
        8: 'Da, na potu sodb tvojih, o Gospod, smo te čakali; k imenu tvojemu in k spominu tvojemu je bilo hrepenenje duše.',
        9: 'Iz srca sem te želel po noči in z duhom svojim znotraj sebe sem zgodaj hitel k tebi: zakaj ko zadevajo sodbe tvoje zemljo, se uče pravičnosti prebivalci sveta.',
        10: 'Če se izkaže milost brezbožniku, se ne uči pravičnosti: v deželi pravičnosti ravna krivično in noče videti visokosti Gospodove.',
        11: 'Gospod, roka tvoja se je vzdignila, pa ne vidijo. A videli bodo gorečnost tvojo za to ljudstvo, in bodo osramočeni; da, ogenj pokonča nasprotnike tvoje.',
        12: 'Za nas pa, Gospod, pripraviš mir; saj si tudi dovršil vsa dela naša za nas.',
        13: 'Gospod, Bog naš, zapovedovali so nam drugi gospodje razen tebe; samo s teboj združeni hvalno spominjamo imena tvojega.',
        14: 'Mrtvi so, ne ožive, mrliči so, ne vstanejo več: zato ker si jih obiskal in pogubil, in pokončal si ves njih spomin.',
        15: 'Pomnožil si ta narod, o Gospod, pomnožil si ta narod, poveličal si sebe; razširil si vse meje dežele.',
        16: 'Gospod, v stiski so te iskali; molili so ponižno, kadar jih je trla pokora tvoja.',
        17: 'Kakor se noseča blizu poroda zvija in vpije v bolečinah svojih, tako smo bili pred obličjem tvojim, Gospod.',
        18: 'Noseči smo bili, zvijali smo se, a bilo je, kakor da bi rodili le sapo: rešitve nobene nismo napravili zemlji in niso se porodili prebivalci svetu.',
        19: 'Ožive mrtveci tvoji; mrtva trupla moja vstanejo. Zbudite se in veselo pojte, kateri prebivate v prahu! kajti rosa svetlobe je rosa tvoja, in zemlja izvrže mrtve.',
        20: 'Pojdi, ljudstvo moje, stopi v hrame svoje in zapri si duri za seboj: skrij se za malo časa, dokler ne preide jeza.',
        21: 'Zakaj, glej, Gospod prihaja iz kraja svojega, kaznovat prebivalce zemlje za njih krivico; in zemlja odkrije kri svojo in ne bo pokrivala več ubitih svojih.',
    },
    27: {
        1: 'Tisti dan bo Gospod kaznoval z mečem svojim, trdim in velikim in močnim, leviatana, hitro bežečo kačo, in leviatana, kačo zvito, in ubije zmaja, ki je v morju.',
        2: 'Tisti dan prepevajte o prekrasnem vinogradu:',
        3: 'Jaz, Gospod, ga stražim, vsak trenotek ga bom močil; da ga kdo ne oškodi, ga bom stražil noč in dan.',
        4: 'Srda ni pri meni. O da bi imel trnje in grmovje pred seboj, v boju bi stopal po njem, požgal bi ga hkratu docela!',
        5: 'Ali pa naj se izroči v varstvo meni, sklene mir z menoj, sklene naj mir z menoj!',
        6: 'V prihodnjih dneh se ukoreni Jakob, Izrael bo cvetel in popke poganjal; in napolnijo površje vsega sveta s sadom. –',
        7: 'Ali ga je Bog udaril, kakor je udaril tiste, ki so ga tepli? ali pa je ubit, kakor so bili ubiti morilci njegovi?',
        8: 'Zmerno ga je kaznoval, ko ga je poslal v pregnanstvo, odpodil ga je s silovitim dihom svojim ob dnevi vzhodnega vetra.',
        9: 'Zato bo s tem poravnana krivica Jakobova; in to bode obilni sad, ko se odpravi greh njegov: da naredi vse oltarjevo kamenje enako zdrobljenemu apnencu in ne postavi več nobene Ašere in solnčne podobe.',
        10: 'Kajti trdno mesto je postalo samotno, bivališče porušeno in zapuščeno kakor puščava; tam se bodo pasla teleta in tam ležala in objedala brstje njegovo.',
        11: 'Ko mu usahnejo veje, jih odlomijo, žene pridejo ter jih zažgo; zakaj to ljudstvo nima nikakega razuma, zato se ga ne usmili on, ki ga je ustvaril, in on, ki ga je upodobil, mu ne izkaže milosti.',
        12: 'In zgodi se tisti dan, da bo Gospod sadje otepal od toka Evfrata do potoka Egiptovskega, in vi boste zbrani vkup, drug k drugemu, o sinovi Izraelovi.',
        13: 'In tisti dan se zatrobi na veliko trobento, in pridejo oni, ki so bili blizu pogina v deželi Asirski in ki so bili pregnanci v deželi Egiptovski, in molili bodo Gospoda na sveti gori v Jeruzalemu.',
    },
    28: {
        1: 'Gorje kroni napuha pijancev v Efraimu in venočemu cvetju slavne dike njegove, ki biva na vrhu rodovitne doline njih, ki so ubiti od vina.',
        2: 'Glej, krepak in močan od Gospoda pride, podoben viharju s točo, vrtincu pogubnemu; podoben povodnji močnih vodá deročih, bo podiral na tla s silo.',
        3: 'Krona napuha pijancev v Efraimu bo z nogami poteptana;',
        4: 'in venočemu cvetju slavne dike, ki biva na vrhu rodovitne doline, se bo godilo kakor zgodnji smokvi pred poletjem: komaj jo dobi v roke, kdor jo zagleda, jo precej pogoltne.',
        5: 'Tisti dan bode Gospod nad vojskami za krono slave in za venec dike ostanku ljudstva svojega',
        6: 'in za duha pravice njemu, ki bo vodil sodbo, in za junaško moč njim, ki potiskajo boj nazaj do vrat.',
        7: 'A tudi ti tavajo od vina in od pijače opojne blodijo: duhovnik in prorok tavata od pijače opojne, vino ju utaplja, blodita vsled pijače opojne; tavajo, ko vidijo prikazen, omahujejo, ko vrše sodbo.',
        8: 'Kajti vse mize so polne izbljuvkov in nesnage, mesta čistega ni več.',
        9: 'Koga naj bi učil znanja? in komu naj bi podajal poročilo, da ga umeje? Odstavljenim od mleka, odtrganim od prsi?',
        10: 'Kajti zapoved je na zapoved, zapoved na zapoved, ukaz na ukaz, ukaz na ukaz, nekoliko tu, nekoliko tam! –',
        11: 'Da, po ljudstvu brbljavih usten in tujega jezika bo govoril temu ljudstvu,',
        12: 'on, ki jim je rekel: To je pravi pokoj, pokoja dajte trudnemu; in to je odpočitek! A niso hoteli poslušati.',
        13: 'Zato jim bode beseda Gospodova „zapoved na zapoved, zapoved na zapoved, ukaz na ukaz, ukaz na ukaz, nekoliko tu, nekoliko tam“, da gredo dalje ter padejo vznak in se polomijo, se zapleto in ujamejo v mrežo.',
        14: 'Zato čujte besedo Gospodovo, možje posmehovalci, gospodarji tega ljudstva, ki je v Jeruzalemu:',
        15: 'Ker pravite: Sklenili smo zavezo s smrtjo in s peklom smo storili pogodbo; ko pojde bič povodnji mimo, ne zadene nas, zakaj storili smo laž za zavetje svoje in zvijača nam je skrivališče.',
        16: 'Zatorej pravi tako Gospod Jehova: Glej, za podstavo sem jaz položil na Sionu kamen, kamen izkušen, dragocen vogelnik, za temelj najtrdnejši; kdor veruje, se ne prenagli.',
        17: 'In pravo sodbo storim za pravilo in pravičnost za tehtnico; in toča iztrebi zavetje laži in vode poplavijo njih skrivališče.',
        18: 'Tedaj se ovrže zaveza vaša s smrtjo in pogodba vaša s peklom ne ostane; ko pojde bič povodnji mimo, tedaj vas pogazi.',
        19: 'Kadar pojde mimo, vas prestreže; kajti vsako jutro pojde mimo, po noči in po dnevi; in samo groza vas bode, ko le začujete poročilo.',
        20: 'Kajti prekratka je postelja, da bi se iztegnil, in odeja preozka, da bi se zavil.',
        21: 'Kajti kakor na gori Perazimski vstane Gospod, razsrdi se kakor v dolini ob Gibeonu, da opravi dejanje svoje – čudno je dejanje njegovo, in da izvrši delo svoje – neobičajno je delo njegovo.',
        22: 'Sedaj torej se ne posmehujte, da se ne utrdijo vezi vaše; zakaj čul sem od Gospoda, Jehove nad vojskami, da je pokončanje trdno določeno nad vso zemljo.',
        23: 'Nagnite ušesa in čujte glas moj, poslušajte in čujte govor moj!',
        24: 'Ali neprestano orje oratar za setev? brazdi li in vlači vedno zemljo svojo?',
        25: 'Ni li tako? Ko je poravnal površje njeno, seje koper ali trosi kumino ali deva vanjo po vrsti pšenico in ječmen na obtaknjeno leho in pirjevico na obmejek njen.',
        26: 'Tako ga poučuje Bog njegov, da prav ravna, in ga uči.',
        27: 'Kajti kopra ne mlatijo z mlatilnico, tudi po kumini ne vlačijo voznega kolesa, temuč s palico otepajo koper in s šibo kumino.',
        28: 'Drobi se li krušno žito? Ne, ne bo ga neprenehoma trl; ko žene kolesa voza svojega in konje svoje čeznje, ga ne razdrobi.',
        29: 'Tudi to prihaja od Gospoda nad vojskami, ki je čudovit v svetu, velik v razumnosti.',
    },
    29: {
        1: 'Gorje Arielu, Arielu, mestu, v katerem si je David napravil stanišče! Pridenite leto k letu, vrsté naj se zaporedoma prazniki –',
        2: 'vendar pripravim v stisko Ariela in bo v njem žalovanje in javkanje. In bode mi pravi Ariel.',
        3: 'In napravim ostrog okoliinokoli zoper tebe in te tesno obkrožim z vojnimi stražami in naredim nasipe proti tebi.',
        4: 'Tedaj boš ponižan govoril na tleh in iz prahu bo zamolklo šumel govor tvoj, in glas tvoj bode kakor kakega duha iz zemlje, iz prahu bo šepetal govor tvoj.',
        5: 'In kakor droben prah bode sovražnikov tvojih množica in kakor pleva mimo leteča silnikov množica, in zgodi se naglo, v trenotku.',
        6: 'Od Gospoda nad vojskami pride obiskovanje z gromom in potresom in ropotom močnim, z vrtincem in nevihto in s plamenom požrešnega ognja.',
        7: 'In kakor sanje, prikazen ponočna, bode množica vseh tistih narodov, ki se vojskujejo zoper Ariela, in izginejo vsi, ki se bojujejo zoper njega in grad njegov ter ga stiskajo.',
        8: 'Bode, pravim, kakor ko se lačnemu sanja, in glej, jé, ko se pa prebudi, je prazna duša njegova; ali kakor ko se sanja žejnemu, in glej, pije, ko se pa zbudi, glej, truden je in duša njegova čuti poželenje: tako bode množica vseh tistih narodov, ki se vojskujejo zoper goro Sionsko.',
        9: 'Osupnite in strmíte, zaslepite se in oslepite! Pijani so, ali ne od vina, opotekajo se, a ne od pijače opojne.',
        10: 'Kajti oblil vas je Gospod z duhom trdnega spanja in je zatisnil oči vaše, proroke, in pokril glave vaše, vidce.',
        11: 'Zato vam je vsaka prikazen podobna besedam zapečatenega pisma, katero dado branju veščemu človeku, rekoč: Beri, prosim, to! On pa reče: Ne morem, ker je zapečateno.',
        12: 'In dado pismo neveščemu branju, veleč: Beri, prosim, to! pa reče: Brati ne znam.',
        13: 'In Gospod je rekel: Zato ker se mi bliža to ljudstvo in me časti z usti in z ustnami, srce pa obrača daleč od mene, in ker je njih strah do mene le zapoved človeška, kakor so se je naučili:',
        14: 'glej, zato bom še dalje čudno ravnal s tem ljudstvom, čudno in čudovito; in modrost modrijanov njegovih mine in razumnost razumnikov njegovih se skrije.',
        15: 'Gorje jim, ki se zagrebajo globoko, da skrijejo svoje naklepe pred Gospodom, in katerih dela se vrše v temi in govore: Kdo nas vidi? in kdo nas pozna?',
        16: 'O vi popačenci! Lončar naj se šteje ilovici za enakega? da bi reklo delo za mojstra svojega: Ni me naredil! in tvorina za svojega tvorilca: Nima razuma!',
        17: 'Ni li še malo časa, le prav malo, in izpremeni se Libanon v rodovitno njivo, in rodovitna njiva se bo štela za gozd?',
        18: 'In tisti dan bodo glušci slišali besede pisma, in iz mraka in teme bodo videle slepcev oči.',
        19: 'In krotki bodo pomnožili veselje svoje v Gospodu, in ubožni med ljudmi se bodo radovali v Svetniku Izraelovem.',
        20: 'Kajti konec bode silovitniku in zasmehovalec izgine, in iztrebljeni bodo vsi, ki se potegujejo za krivico,',
        21: 'ki obsojajo človeka zaradi besede in stavijo zanko njemu, ki med vrati pravdo prisoja, in ki brez vzroka izpodrivajo pravičnega.',
        22: 'Zato pravi tako Gospod, ki je odrešil Abrahama, za hišo Jakobovo: Odslej ne bo več osramočen Jakob in obličje njegovo odslej ne obledi;',
        23: 'temuč ko bo videl, namreč otroci njegovi, rok mojih delo sredi sebe, bodo posvečevali ime moje, da, posvečevali bodo Svetnika Jakobovega in se bali Boga Izraelovega.',
        24: 'In kateri so se v duhu motili, zadobe razsodnost, in godrnjači bodo dovzetni za nauk.',
    },
    30: {
        1: 'Gorje sinom upornim, pravi Gospod, ki delajo naklepe, ali ne iz mene, in narejajo pogodbe, ali ne po duhu mojem, da bi kopičili greh na greh!',
        2: 'ki se napotujejo doli v Egipt, a niso poprašali ust mojih, da se okrepčajo z močjo Faraonovo in si oskrbe zavetje v senci Egipta!',
        3: 'Zato vam bode moč Faraonova v sramoto in zavetje v senci Egipta v nečast.',
        4: 'Ko bodo v Zoanu knezi Judovi in pridejo poslanci njegovi v Hanes,',
        5: 'vsi se bodo sramovali ljudstva, ki jim ne more koristiti, ki jim ni v pomoč, ne v korist, temuč v sramoto in zasmeh.',
        6: 'Prorokovanje o živini na jugu. Skozi deželo stiske in nadloge, odkoder so levinja in lev, gad in ognjena kača leteča, poneso na oslovskih plečih bogastvo svoje in na grbah velblodov zaklade svoje k ljudstvu, ki jim nič ne koristi.',
        7: 'Kajti Egipt bo ničevo pomagal in brez uspeha. Zato ga imenujem Rahab, ki mirno sedi.',
        8: 'Sedaj pojdi, zapiši to na desko vpričo njih in v knjigo začrkaj to, da bode za prihodnji čas, v pričevanje na vekomaj.',
        9: 'Zakaj to je uporno ljudstvo, otroci lažnivi, otroci, ki nočejo poslušati postave Gospodove;',
        10: 'ki velevajo videčim: Ne vidite! in gledalcem prikazni: Ne prorokujte nam, kar je prav! govorite nam dobrikavo, vidite varljive nam prikazni!',
        11: 'Zapustite pot, krenite s steze, dejte, da se umakne nam izpred obličja Svetnik Izraelov!',
        12: 'Zatorej pravi tako Svetnik Izraelov: Ker zametate to besedo, a se zanašate na zatiranje in napačno vedenje ter se opirate nanje,',
        13: 'zato vam bode tista krivičnost kakor razpoka v zidu, ki že hoče pasti, kakor izpah v visokem zidu, ki se nagloma, mahoma podere.',
        14: 'In zdrobi ga, kakor se zdrobi posoda lončarjeva, ki jo človek razbije brez usmiljenja, in od katere, ko je razbita, ni najti čepinje, da se ž njo vzame ogenj z ognjišča ali se zajme voda iz luže.',
        15: 'Kajti tako pravi Gospod Jehova, Svetnik Izraelov: Če se vrnete in bodete pokojni, boste rešeni, v mirovanju in upanju bode vaša moč. Ali niste hoteli,',
        16: 'temuč ste rekli: „Nikakor, kajti sedeč na konjih bomo bežali!“zato boste bežali; in: „Na brzih živalih bomo jezdili!“zato vas bodo preganjalci vaši prehiteli.',
        17: 'Tisoč vas bo bežalo pred grožnjo enega, pred grožnjo petih boste bežali vsi, dokler ne ostanete kakor kol na vrhu gore in kakor praporec na griču.',
        18: 'In zato bo Gospod odlašal storiti vam milost in zato se umakne v višavo, preden se vas usmili; kajti Gospod je Bog sodbe. Blagor jim vsem, ki ga čakajo!',
        19: 'Zakaj ljudstvo bo prebivalo na Sionu, v Jeruzalemu; ne boš se nikdar več jokalo, gotovo ti stori milost na glas vpitja tvojega: kakor hitro te začuje, ti odgovori.',
        20: 'Dal vam bo res Gospod stiske kruh in vodo nadloge; a učitelji tvoji se ne bodo več skrivali, temuč oči tvoje bodo videle učitelje svoje',
        21: 'in ušesa tvoja bodo slišala, ko krenete na desno ali na levo, besedo zadaj za teboj govorečih: To je tisti pot, hodite po njem!',
        22: 'In oskrunili boste prevleko svojih rezanih podob iz srebra in obleko svojih ulitih podob iz zlata; in jih proč vržeš kakor skrunobo: „Poberi se!“porečeš jim vsem.',
        23: 'Tedaj bo dal dežja setvi tvoji, s katero poseješ zemljo, in kruha kot pridelek zemlje, in ta bode obilen in tečen. Črede tvoje se bodo pasle tisti dan po pašniku širokem;',
        24: 'in voli in osliči, ki obdelujejo zemljišče, bodo jedli osoljeno zmes, ki je prevejana z velnico in rešetom.',
        25: 'In na vsaki visoki gori in na vsakem griču vzvišenem bodo potoki in reke vodá ob dnevi velikega klanja, ko bodo padali stolpi.',
        26: 'In lune svetloba bode kakor solnca svetloba, solnčna svetloba pa bode sedemkrat močnejša, kakor sedmih dni svetloba, tisti dan, ko Gospod obveže poškodbo ljudstva svojega in ozdravi vsekane mu rane.',
        27: 'Glej, ime Gospodovo prihaja iz daljave. Jeza njegova gorí in gost dim se vzdiguje; ustne njegove so polne nevolje in jezik njegov je kakor uničujoč ogenj;',
        28: 'in dih njegov je kakor poplavljajoč hudournik, ki sega prav do grla, da bi presejal narode na situ ničemurnosti in dejal uzdo, v zmotnjavo vodečo, ljudstvom na čeljusti.',
        29: 'Vi pa boste peli kakor v noči, ko se posvečuje praznik, in srčno se veselili kakor tisti, ki gredo s piščaljo, da stopijo na goro Gospodovo, k Skali Izraelovi.',
        30: 'In Gospod stori, da se začuje glasa njegovega veličastvo, in pokaže ramo svojo iztegnjeno z ljuto togoto in s plamenom požrešnega ognja, s povodnijo in z viharjem in s kameneno točo.',
        31: 'Kajti po glasu Gospodovem bo potrt Asirec, ki je bil vajen tepsti s šibo.',
        32: 'In vsak udarec določene šibe, ki bo ž njo švigal Gospod po njem, se bo godil med glasom bobnov in strun; in mahaje z ramo proti njemu, se bo bojeval ž njim.',
        33: 'Zakaj pripravljen je že oddavna pogube kraj; ta je tudi kralju samemu namenjen: globokega in širokega so ga naredili, v grmadi njegovi je ognja in drv obilo; dih Gospodov jo zapali kakor s hudournikom žveplenim.',
    },
    31: {
        1: 'Gorje njim, ki gredo doli v Egipt po pomoč in se opirajo na konje, ki zaupajo vozém, ker jih je mnogo, in konjikom, ker je njih število veliko, a ne ozirajo se v Svetnika Izraelovega in ne iščejo Gospoda!',
        2: 'Ali tudi On je moder, in pošlje nesrečo in ne dopusti, da bi se premeknile besede njegove, ampak vzpne se nad hišo hudodelnikov in nad pomoč njih, ki delajo krivico.',
        3: 'Egipčan pa je človek in ne Bog mogočni, in njih konji so meso, ne pa duh; in ko iztegne Gospod roko svojo, se zgrudi pomočnik in podpiranec pade, in skupaj poginejo ti vsi.',
        4: 'Kajti tako mi pravi Gospod: Kakor lev in levič rjoveta pri plenu svojem, ko se skliče zoper nju množica pastirjev, in se ne ustrašita njih glasu in se ne vdasta zaradi njih ropotanja: tako pride doli Gospod nad vojskami vojskovat se na gori Sionski in na višavi njeni.',
        5: 'Kakor ptiči mahljajo s perutmi, tako bo Gospod nad vojskami branil Jeruzalem, branil ga bo in otel, prizanesel mu in ga oprostil.',
        6: 'Povrnite se k njemu, od katerega ste tako daleč zašli, sinovi Izraelovi!',
        7: 'Kajti tisti dan zavržejo vsak svoje malike srebrne in zlate malike svoje, ki so vam jih vaše roke naredile v greh.',
        8: 'Tedaj pade Asirec pod mečem, pa ne moževim, in ugonobi ga meč, pa ne človeški; in bežal bo v strahu pred mečem, in mladeniči njegovi bodo sužnji.',
        9: 'In skala njegova izgine od groze in knezi njegovi bodo potrti spričo prapora, govori Gospod, ki ima svoj ogenj na Sionu in svojo peč v Jeruzalemu.',
    },
    32: {
        1: 'Glej, v pravičnosti bo kraljeval kralj in po pravici bodo kneževali knezi.',
        2: 'In mož bode kakor zavetje pred vetrom in pribežališče pred povodnjijo, kakor potoki vodá na suhem kraju, kakor senca skale velike v žejni deželi.',
        3: 'In vidcev oči ne bodo več zalepljene in ušesa poslušalcev bodo pazljivo poslušala.',
        4: 'In srce nepremišljencev bo razumelo znanje in jecljajočih jezik bo hitro govoril in gladko.',
        5: 'In nespametneža ne bodo več nazivali plemenitnika, in zvijačnika ne bodo imenovali blagosrčneža.',
        6: 'Kajti nespametnež govori nespametnost in srce njegovo se peča s krivico, da počenja bogoskrunstvo in govori zapeljive zmote proti Gospodu, da napravi prazno dušo lačnemu in žejnemu umakne pijačo.',
        7: 'Orodje zvijačnega je tudi hudobno: dela pregrešne naklepe, da pogubi ponižne z lažnivimi govori, tudi ko potrebni zagovarja pravico svojo.',
        8: 'Ali plemeniti misli plemenito in stanoviten je v stvareh plemenitih.',
        9: 'Žene brezskrbne, vstanite, čujte glas moj, hčere prezaupne, poslušajte govor moj!',
        10: 'V teh dneh, ko mine leto, bodete v strahu, prezaupne, kajti propade trgatev, pobiranja ne bode.',
        11: 'Trepetajte, o brezskrbne, strah vas bodi, o prezaupljive, slecite se in bodite nage, in opašite si z raševnikom ledja.',
        12: 'Trkali se bodo na prsi zaradi prekrasnih njiv, zaradi trte rodovitne.',
        13: 'Po zemlji ljudstva mojega bo raslo trnje in bodljikovje, tudi na vseh hišah veselih v mestu radostnem.',
        14: 'Kajti grad bode prazen, šumovito mesto bode zapuščeno, grič Ofel in stražni stolp bosta za brlog vekomaj, na veselje divjim oslom, čredam za pašnik –',
        15: 'dokler se ne razlije nad nas duh z višave in se puščava izpremeni v njivo rodovitno, in rodovitna njiva se bo štela za gozd.',
        16: 'In v puščavi se nastani pravica, in pravičnost bo prebivala na rodovitni njivi;',
        17: 'in delo pravičnosti bode mir in obrodek pravičnosti pokoj in varnost vekomaj.',
        18: 'In ljudstvo moje bo prebivalo v domovju miru in v varnih prebivališčih in v krajih za pokoj mirnih.',
        19: 'A prej se bo toča usipala, ko se bo podiral gozd, in mesto bo globoko ponižano.',
        20: 'Blagor vam, ki sejete poleg vseh vodá in puščate, da prosto hodijo noge volov in oslov!',
    },
    33: {
        1: 'Gorje ti, pokončevalec, ki sam nisi bil pokončan, in tebi, nezvestnik, zoper katerega niso delali nezvesto! Brž ko dovršiš pokončevanje, bodo tebe pokončali, brž ko nehaš ravnati nezvesto, se bo delalo nezvesto proti tebi. –',
        2: 'O Gospod, stóri nam milost! tebe čakamo: bodi svojim rama sleherno jutro in rešenje naše ob času stiske! –',
        3: 'Od donečega glasu tvojega beže ljudstva, če se ti vzdigneš, razkrope se narodi.',
        4: 'In pobere se vaš plen, kakor pobira kobilica; kakor skače kobilica, bodo skakali nanj.',
        5: 'Vzvišen je Gospod, kajti prebiva na višavi; napolnil je Sion s sodbo in pravičnostjo.',
        6: 'In vernost bode v tvojih časih, obilost rešenja, modrosti in znanja; strah Gospodov bo zaklad Izraelov.',
        7: 'Glej, njih junaki vpijejo zunaj, poslanci miru jokajo bridko.',
        8: 'Ceste so zapuščene, popotnik več ne hodi. Prelomil je zavezo, zaničeval je mesta, zmenil se ni za človeka.',
        9: 'Žaluje, hira dežela; Libanon se sramuje in vene; Saron je kakor puščava in Basan in Karmel stresata perje svoje.',
        10: 'Sedaj vstanem, reče Gospod, sedaj se vzdignem, sedaj bom povišan.',
        11: 'Spočenjate suho travo, rodili boste strnišče; dih vaš je ogenj, ki vas pokonča.',
        12: 'In ljudstva bodo kakor žgano apno in kakor trnje porezano, ki se žge v ognju.',
        13: 'Čujte, ki ste daljni, kaj sem storil, in kateri ste bližnji, spoznajte mogočnost mojo!',
        14: 'Preplašeni so grešniki na Sionu, trepet se je polastil hinavcev: Kdo izmed nas more bivati s požrešnim ognjem? kdo izmed nas more bivati z večno žerjavico?',
        15: 'Kdor hodi pravično in govori pošteno, kdor zaničuje dobiček po zvijači, kdor stresa roke svoje, da ne prejme podkupila, kdor si maši uho, da ne sliši naklepov o prelitju krvi, in zatiska oči, da ne vidi zlega:',
        16: 'ta bo prebival v krajih previsokih, skalni branik bode grad njegov, kruh njegov se mu bo dajal, vode mu ne bodo usehnile. –',
        17: 'Kralja v lepoti njegovi bodo videle tvoje oči, gledale bodo deželo daleč razprostranjeno.',
        18: 'Srce tvoje bo preudarjalo strahoto: Kje je cenilec davkov? kje pretehtovalec? kje stolpov nadzornik?',
        19: 'Ljudstva drznega ne boš videl, ljudstva s preglobokim govorom, da bi ga umel, tuje govorice, ki je ni razumeti.',
        20: 'Poglej Sion, mesto slavnostnih zborov naših! Oči tvoje bodo videle Jeruzalem, mirno prebivališče, šator, ki se ne bo prenašal več, ki se mu nikoli noben klin ne izruje in nobena vrv nikdar ne potrga –',
        21: 'marveč tam bode Gospod z nami, Veličastni, – kraj širokih rek in potokov, kamor ne pride ladja z vesli in velik brod ne bo plul skozi.',
        22: 'Zakaj Gospod je naš sodnik, Gospod postavodajec naš, Gospod kralj naš, on nas bo rešil.',
        23: 'Rahlo visé vrvi tvoje, ne drže postavljenega jadrnika, ne morejo razpeti jader. Tedaj se razdeli plen velikega ropa, še hromi bodo grabili plen.',
        24: 'In noben prebivalec ne poreče: Bolan sem! Ljudstvu, ki v njem prebiva, bo odpuščena krivica.',
    },
    34: {
        1: 'Pristopite, narodi, da poslušate, in ljudstva, čujte! Sliši naj zemlja in kar jo napolnjuje, naseljeni svet in vse, kar se rodeva na njem!',
        2: 'Zakaj goreča je jeza Gospodova zoper vse narode in srditost zoper vso njih vojsko; proklel jih je v pokončanje, izročil jih je v klanje.',
        3: 'In njih prebodenci bodo tja pometani, in od njih mrličev bo prihajal smrad, in gore se bodo topile v njih krvi.',
        4: 'In izgine vsa vojska nebeška, in nebo se zvije kakor knjiga, in vsa njegova vojska odpade, kakor odpade listje s trte in kakor odpade list s smokve.',
        5: 'Kajti upijanil se je moj meč v nebesih; glej, nad Edomce pride doli v sodbo in nad ljudstvo, ki sem ga odmenil v prokletje.',
        6: 'Meč Gospodov je poln krvi, masten od tolšče, od krvi jagnjet in kozlov, od tolšče ovnovih ledij: kajti žrtvovanje je Gospodu v Bozri in veliko klanje v deželi Edomcev.',
        7: 'Padejo tudi divji bivoli ž njimi in junci s krepkimi biki, tako da se zemlja upijani njih krvi in prah bo napojen ž njih mastjo.',
        8: 'Kajti dan Gospodovega maščevanja je leto povračila, da se reši pravda Sionova.',
        9: 'In potoki Edomovi se premene v smolo in prah njegov v žveplo, in zemlja njegova bo kakor goreča smola.',
        10: 'Po dnevi in po noči ne ugasne, vekomaj bo vzhajal dim njen; od roda do roda ostane pusta, vekomaj nihče ne pojde skozi njo.',
        11: 'Ali podedovala jo bosta pelikan in jež ter sova in vran bosta prebivala v njej. In potegne čez njo mersko vrvico pustote in svinčnico praznote.',
        12: 'Plemenitnikov njenih ne bode nobenega, da bi oklical kraljestvo, in vsi knezi njeni bodo v nič.',
        13: 'In v gradovih njenih požene trnje, kopriva in osat po trdnjavah njenih, in bode v brlog šakalom, za pašo mladim nojem.',
        14: 'In stekale se bodo zveri puščave z divjimi psi in kosmatin bo klical druga svojega; ponočni škrat bo bival ondi in našel si pokoja mesto.',
        15: 'Tam si napravi kača gnezdo in bo legla jajca, in ko se izvalé mladiči, jih bo zbirala v senco svojo; ondi se bodo zbirali jastrebi, vsak z družetom svojim.',
        16: 'Preiskujte knjigo Gospodovo in čitajte! Enega od teh ne bo manjkalo, eden ne bo pogrešal drugega, kajti usta Njegova so zapovedala in duh Njegov jih je zbral vkup;',
        17: 'in On je vrgel kocko zanje in jim je z roko svojo razdelil to zemljo po merski vrvi: v lasti jo bodo imeli vekomaj, od roda do roda bodo prebivali v njej.',
    },
    35: {
        1: 'Veselila se bosta puščava in samotni kraj, in radovala se bo pustinja in cvela kakor roža.',
        2: 'Prekrasno bo cvela in se radovala v samem radovanju in petju; slava libanonska ji bo dana, lepota Karmela in Sarona. Gledali bodo slavo Gospodovo, lepoto Boga našega.',
        3: 'Pokrepčajte onemogle roke in šibeča se kolena utrdite!',
        4: 'Recite njim, ki so plašljivega srca: Srčni bodite, ne bojte se! Glejte, Bog vaš se bliža, maščevanje prihaja, povračilo Božje; on sam pride rešit vas!',
        5: 'Tedaj izpregledajo oči slepim in gluhim se odpro ušesa.',
        6: 'Tedaj bo hromec skakal kakor jelen in nemega jezik bo prepeval; zakaj privrele so v puščavi vode in potoki v samoti.',
        7: 'Peščeno zrcaljenje se je izpremenilo v jezero in žejna tla v vrelce vodá; v brlogu šakalov, kjer leže, bode trava s trstjem in bičjem.',
        8: 'In bode tam cesta in pot, ki se bo imenovala Pot svetosti, po kateri ne bo hodil oskrunjeni, temuč bode zanje same; kdor hodi po tej poti, tudi nespametni, ne more zaiti.',
        9: 'Tam ne bode leva in nobena zver silovita ne pride nanjo in je ne bode najti tam; a odrešenci pojdejo po njej.',
        10: 'In odrešenci Gospodovi se povrnejo ter pridejo na Sion s petjem, in večno veselje bode nad njih glavo; veselje in radost jih objame, a žalovanje in zdihovanje pobegne.',
    },
    36: {
        1: 'In zgodilo se je v štirinajstem letu kralja Ezekija, da je šel Senaherib, kralj asirski, gori zoper vsa utrjena mesta Judova in se jih polastil.',
        2: 'Pošlje pa kralj asirski Rabsaka iz Lahisa v Jeruzalem proti kralju Ezekiju z mnogoštevilno vojsko. Ta se ustavi pri vodovodu gornjega ribnika ob poti valjalčeve njive.',
        3: 'Tedaj pride ven k njemu Eljakim, sin Hilkijev, ki je bil nad dvorcem, in pisar Sebna in Joah, sin Asafov, letopisec.',
        4: 'Njim reče Rabsak: Povejte vendar Ezekiju: Tako pravi kralj veliki, kralj asirski: Kakšno upanje je to, na katero se zanašaš?',
        5: 'Pravim ti: Tvoj svet in moč za vojskovanje je le prazna beseda. Na koga se torej zanašaš, da si se mi uprl?',
        6: 'Glej, zanašaš se na palico iz zlomljenega trsta, na Egipt; katera se mu, ko se kdo nasloni nanjo, zadere v dlan in jo prebode. Tako je Faraon, kralj egiptovski, vsem, ki stavijo upanje vanj.',
        7: 'Ako mi pa porečeš: V Gospoda, Boga svojega, upamo! ali ni on tisti, čigar višave in oltarje je odpravil Ezekija in je velel Judi in Jeruzalemu: Pred tem oltarjem molite!',
        8: 'A sedaj, naredi vendar stavo z gospodom mojim, kraljem asirskim, in dam ti dvakrat tisoč konj, ako boš imel jezdecev, da jih posadiš nanje.',
        9: 'Kako bi torej mogel zapoditi le enega voditelja najmanjših hlapcev gospoda mojega? Ali ti se zanašaš na Egipt zaradi voz in konjikov!',
        10: 'Sem li mar sedaj brez Gospoda prišel gori zoper to deželo, da jo pogubim? Gospod mi je velel: Idi gori v tisto deželo ter pogubi jo!',
        11: 'Tedaj reko Eljakim in Sebna in Joah Rabsaku: Govóri, prosim, hlapcem svojim po sirsko, saj razumemo, in ne govori nam po judovsko, ker sliši ljudstvo, ki je na zidovju.',
        12: 'Ali Rabsak reče: Me je li h gospodu tvojemu in k tebi poslal gospod moj, da naj govorim besede te? Ali ne k onim možem, ki sede po zidovju, da jedo blato svoje in pijo vodo svojo z vami vred?',
        13: 'Rabsak torej se ustopi in zavpije z glasom velikim po judovsko in reče: Čujte besede velikega kralja, kralja asirskega!',
        14: 'Tako pravi kralj: Naj vas ne prekani Ezekija, kajti ne bo vas mogel oteti.',
        15: 'In ne pregovóri vas Ezekija, da bi upali v Gospoda, govoreč: Gotovo nas otme Gospod; to mesto ne bo dano kralju asirskemu v roko!',
        16: 'Ne poslušajte Ezekija! Kajti tako pravi kralj asirski: Pogodite se z menoj za mir in pridite k meni ter jejte vsak svoje trte sad in vsak svoje smokve sad in pijte vsak svojega vodnjaka vodo,',
        17: 'dokler ne pridem ter vas vzamem v deželo, podobno vaši deželi, v deželo, kjer je obilo žita in vina, kruha in vinogradov.',
        18: 'Ne zapelji vas Ezekija, govoreč: Gospod nas otme. Ali so bogovi narodov oteli vsak svojo deželo iz roke kralja asirskega?',
        19: 'Kje so bogovi Hamata in Arpada, kje bogovi Sefarvaima? Ali so neki oteli Samarijo iz moje roke?',
        20: 'Kateri so med vsemi bogovi tistih dežel, ki so deželo svojo oteli iz roke moje, da bi Gospod otel Jeruzalem iz roke moje?',
        21: 'A oni so molčali in mu niso odgovorili besede, zakaj kraljev ukaz je velel: Ne odgovarjajte mu!',
        22: 'Pride torej Eljakim, Hilkijev sin, ki je bil nad dvorcem, in Sebna pisar in Joah, Asafov sin, letopisec, k Ezekiju z raztrgano obleko in mu naznanijo besede Rabsakove.',
    },
    37: {
        1: 'In ko je to slišal kralj Ezekija, si raztrga oblačila in se ogrne z raševino in stopi v hišo Gospodovo.',
        2: 'In pošlje Eljakima, ki je bil nad dvorcem, in Sebna pisarja ter starejšine duhovnikov, odete z raševino, k proroku Izaiju, sinu Amozovemu.',
        3: 'In ti mu reko: Tako pravi Ezekija: Dan stiske in strahovanja in zasramovanja je ta dan, kajti otroci so blizu do poroda, a moči ni za porod.',
        4: 'Morda bo slišal Gospod, Bog tvoj, besede Rabsakove, ki ga je poslal kralj asirski, gospod njegov, sramotit Boga živega, in bo kaznoval besede, ki jih je slišal Gospod, Bog tvoj. Zato povzdigni prošnjo za ostanke, kar jih še je.',
        5: 'Ko so torej prišli hlapci Ezekija kralja k Izaiju,',
        6: 'jim reče Izaija: Tako povejte gospodu svojemu: Tako pravi Gospod: Ne boj se spričo tistih besed, ki si jih slišal, s katerimi so me preklinjali hlapci kralja asirskega.',
        7: 'Glej, jaz mu vdahnem duha, da začuje glas in se vrne v deželo svojo, in storim, da pade od meča v deželi svoji.',
        8: 'In Rabsak se vrne in najde kralja asirskega, vojskujočega se z Libno; slišal je bil namreč, da je odpotoval od Lahisa.',
        9: 'V tem zasliši, da govorijo o Tirhaku, kralju v Etiopiji: Gre se vojskovat zoper tebe. Ko je to slišal, pošlje poslance k Ezekiju z ukazom:',
        10: 'Tako govorite Ezekiju, kralju Judovemu, in recite: Naj te ne vara Bog tvoj, ki nanj staviš upanje, govoreč: Jeruzalem ne bo dan kralju asirskemu v roko.',
        11: 'Glej, sam si slišal, kar so storili kralji asirski vsem drugim deželam, pokončavši jih docela, in ti bi se otel?',
        12: 'So li mar oteli bogovi narodov tiste, ki so jih pogubili očetje moji, Gozana in Harana in Rezefa in sinove Edena, ki so bili v Telasarju?',
        13: 'Kje je kralj hamatski in kralj arpadski in kralj mesta Sefarvaima, Hene in Ive?',
        14: 'In ko Ezekija prejme pismo iz roke poslancev in ga prebere, gre gori v hišo Gospodovo in ga razgrne pred Gospodom.',
        15: 'In molil je Ezekija h Gospodu, govoreč:',
        16: 'Gospod nad vojskami, Bog Izraelov, ki stoluješ nad kerubi, ti si Bog, ti edini, vsem kraljestvom na zemlji, ti si ustvaril nebesa in zemljo.',
        17: 'Nagni, o Gospod, uho svoje in poslušaj, odpri, Gospod, oči svoje in glej, in poslušaj vse besede Senaheriba, ki je poslal sramotit živega Boga.',
        18: 'Res je, Gospod, opustošili so kralji asirski vse one narode in njih deželo;',
        19: 'in vrgli so njih bogove v ogenj, ker niso bili bogovi, ampak rok človeških delo, les in kamen; zato so jih pogubili.',
        20: 'Sedaj torej, Gospod, Bog naš, reši nas iz roke njegove, da bi spoznala vsa kraljestva na zemlji, da si ti Gospod, ti edini.',
        21: 'Tedaj pošlje Izaija, sin Amozov, k Ezekiju, da mu reko: Tako pravi Gospod, Bog Izraelov: Ker si me prosil spričo Senaheriba, kralja asirskega,',
        22: 'to je beseda, ki jo je govoril Gospod za njega: Zaničuje te, zasmehuje te devica, hči sionska, za teboj maje glavo hči jeruzalemska.',
        23: 'Koga si sramotil in preklinjal? in zoper koga si zagnal svoj glas in ošabno povzdignil oči svoje? Zoper Svetnika Izraelovega!',
        24: 'Po hlapcih svojih si sramotil Gospoda, ko si govoril: Z množico voz svojih sem prišel na vrh gorá, do najvišje strani Libanona; in posekam na njem visoke cedre in izbrane ciprese njegove, stopim tudi na največjo višino njegovo, v gaj na vrtu njegovem.',
        25: 'Jaz sem kopal vodnjake in izpil vode, in s stopalom nog svojih hočem posušiti vse reke v Egiptu.',
        26: 'A nisi li slišal, da sem jaz to delal od zdavnaj in snoval od starih časov? Sedaj sem storil, da je prišlo to, da rušiš utrjena mesta v kupe razvalin.',
        27: 'Zato so bili njih prebivalci slabotnih rok, prestrašeni in izbegani; bili so kakor trava na njivi in kakor mehka zelenjava, kakor seno po strehah in žito posmojeno, preden gre v latje.',
        28: 'In sejo tvojo in odhod in prihod tvoj poznam, tudi divjanje tvoje zoper mene.',
        29: 'Ker divjanje tvoje zoper mene in lahkoživstvo tvoje je prišlo do ušes mojih, zato denem obroček svoj v tvoj nos in uzdo svojo med ustnice tvoje, in povedem te nazaj po tistem potu, po katerem si prišel.',
        30: 'In to ti bodi znamenje: letos boste jedli, kar samo zraste, drugo leto pa, kar po tem priraste, v tretjem letu pa sejte in ženjite in sadite vinograde ter jejte njih sad.',
        31: 'In ohranjenci hiše Judove, kar jih preostane, bodo poganjali zopet korenine spodaj in rodili sad zgoraj.',
        32: 'Zakaj iz Jeruzalema izide ostanek in s Sionske gore tisti, ki se bodo ohranili; gorečnost Gospoda nad vojskami stori to.',
        33: 'Zatorej pravi tako Gospod za kralja asirskega: Ne pride v to mesto in pšic ne sproži sem, tudi ščita mu ne postavi nasproti in nasipov ne napravi zoper njega.',
        34: 'Po istem potu, po katerem je prišel, se vrne, v to mesto pa ne pride, pravi Gospod.',
        35: 'Kajti branil bom to mesto, da ga rešim, zaradi sebe in zaradi Davida, svojega hlapca.',
        36: 'In šel je angel Gospodov ter jih pobil v asirskem ostrogu sto in petinosemdeset tisoč. In ko so vstali zjutraj, glej, bili so vsi tisti trupla mrtvih.',
        37: 'Zato se vzdigne Senaherib, kralj asirski, in odide in se vrne ter ostane v Ninivah.',
        38: 'In zgodilo se je, ko se je klanjal v hiši Nisroka, boga svojega, da ga Adramelek in Sarezer, sinova njegova, udarita z mečem in pobegneta v deželo Araratsko. In kraljeval je sin njegov Esar-hadon namesto njega.',
    },
    38: {
        1: 'V tistih dneh zboli Ezekija na smrt. In pride k njemu Izaija, sin Amozov, prorok, ter mu reče: Tako pravi Gospod: Uredi hišo svojo, kajti v kratkem umreš in ne boš živel.',
        2: 'Tedaj obrne Ezekija obličje svoje v steno in moli h Gospodu',
        3: 'in reče: Ah, Gospod, spomni se, prosim, da sem neprestano hodil pred teboj v resnici in z nerazdeljenim srcem in delal, kar je dobro v tvojih očeh! In jokal je Ezekija, silno jokal.',
        4: 'Tedaj pride beseda Gospodova Izaiju, rekoč:',
        5: 'Pojdi in reci Ezekiju: Tako pravi Gospod, Bog očeta tvojega Davida: Čul sem molitev tvojo, solze tvoje sem videl. Glej, dnem tvojim pridenem petnajst let.',
        6: 'In iz roke kralja asirskega otmem tebe in to mesto, in branil bom to mesto.',
        7: 'In to ti bodi znamenje od Gospoda, da stori Gospod tisto, kar je govoril:',
        8: 'glej, onih stopinj senco, ki je šla doli po solnčni uri Ahazovi, pomaknem za deset stopinj nazaj. In vrnilo se je solnce za deset stopinj po solnčnem kazalniku, po katerem je bilo šlo doli.',
        9: 'Spis Ezekija, kralja Judovega, ko je bil zbolel in ozdravel bolezni svoje:',
        10: 'Rekel sem: V pokojnih mi dnevih moram stopiti v vrata šeola; oropan sem ostanka svojih let.',
        11: 'Dejal sem: Ne bom videl Gospoda, Gospoda v deželi živečih; ondi, kjer prebivajo mrtvi, ne bom več ugledal človeka.',
        12: 'Dom moj je razrušen in ga nosijo od mene kakor pastirski šator. Dotkal sem kakor tkalec življenje svoje; od statev me je odrezal. Od dne do noči me boš končal!',
        13: 'Tolažil sem se do jutra – kakor lev je zdrobil vse kosti moje. Od dne do noči me boš končal!',
        14: 'Kakor lastovka in žerjav sem cvičal, grulil sem kakor golob. Koprneče so mi zrle oči kvišku: O Gospod, v stiski sem, bodi mi porok!',
        15: 'Kaj naj rečem? On mi je obljubil in On je tudi izpolnil. Tiho bom hodil vsa leta svoja zaradi bridkosti duše svoje.',
        16: 'O Gospod, ob tem žive ljudje in vsekakor je v tem življenje duha mojega; in me ozdraviš in ohraniš v življenju.',
        17: 'Glej, v mir mi je bilo, da me je zadela bridkost prebridka; ali ti si v ljubezni potegnil dušo mojo iz jame pogube, kajti vse grehe moje si vrgel za hrbet svoj.',
        18: 'Saj šeol te ne slavi, smrt te ne hvali; ni upanja v zvestobo tvojo njim, ki se pogrezajo v jamo.',
        19: 'Živeči, živeči te bo slavil kakor jaz danes; oče bo sinom oznanjal zvestobo tvojo.',
        20: 'Gospod je bil pripravljen rešiti me, zato bomo pesmi moje s strunami peli, dokler živimo, v hiši Gospodovi!',
        21: 'Izaija pa je bil velel, naj vzemo gručo smokev in jo polože na ulje, in ozdravi.',
        22: 'Ezekija pa je vprašal: Kaj je znamenje, da pojdem gori v hišo Gospodovo?',
    },
    39: {
        1: 'V tistem času je poslal Merodak Baladan, sin Baladanov, kralj babilonski, pismo in dar Ezekiju; slišal je namreč, da je bil zbolel in zopet okreval.',
        2: 'In Ezekija se jih je oveselil in jim pokazal hišo dragocenosti svojih: srebro, zlato, dišave in najboljše olje, in vso orožnico svojo in vse, kar je bilo v zakladih njegovih; ničesar ni bilo v hiši njegovi in pod vso oblastjo njegovo, da bi jim tega Ezekija ne bil razkazal.',
        3: 'Tedaj pride prorok Izaija h kralju Ezekiju in mu reče: Kaj so rekli oni možje in odkod so prišli k tebi? In Ezekija reče: Iz daljne dežele so prišli k meni, iz Babilona.',
        4: 'In vpraša: Kaj so videli v tvoji hiši? In Ezekija odgovori: Karkoli je v hiši moji, so videli; ničesar ni bilo v zakladih mojih, česar bi jim ne bil pokazal.',
        5: 'Tedaj reče Izaija Ezekiju: Čuj besedo Gospoda nad vojskami!',
        6: 'Glej, pridejo dnevi, ko se odnese v Babilon vse, kar je v hiši tvoji in kar so nabrali očetje tvoji do tega dne; nič ne ostane, pravi Gospod.',
        7: 'Tudi sinov tvojih, ki pridejo iz tebe, ki jih boš rodil, vzemo, in bodo dvorniki v palači babilonskega kralja.',
        8: 'In Ezekija reče Izaiju: Dobra je beseda Gospodova, ki si jo govoril. Še reče: Saj bode mir in stanovitnost v dneh mojih.',
    },
    40: {
        1: 'Tolažite, tolažite ljudstvo moje, govori Bog vaš.',
        2: 'Govorite na srce Jeruzalemu in kličite mu, da je dopolnjena vojna služba njegova, da je poravnana krivica njegova, da je dobil dvojno iz roke Gospodove za vse grehe svoje.',
        3: 'Glas vpijočega v puščavi: Pripravljajte pot Gospodu, ravnajte v pustinji cesto Bogu našemu.',
        4: 'Vsaka dolina naj se dvigne in vsako goro in vsak grič znižajte, in kar je krivega, naj se poravna, in hribasto bodi ravnina!',
        5: 'In razodene se slava Gospodova in vse meso vkup jo bo videlo; kajti usta Gospodova so govorila.',
        6: 'Glas govorečega: Oznanjaj! In vpraša: Kaj naj oznanjam? „Vse meso je trava in vsa milina njegova kakor cvetica na polju.',
        7: 'Trava sahne, cvetica vene, ker veje nanjo dih Gospodov. Res, ljudstvo je trava!',
        8: 'Trava sahne, cvetica vene, a beseda Boga našega ostane vekomaj!“',
        9: 'Idi na goro visoko, o Sion, ki oznanjaš veselo vest; povzdigni močno glas svoj, Jeruzalem, ki oznanjaš veselo vest; povzdigni ga, ne boj se, reci mestom Judovim: Glejte, Bog vaš!',
        10: 'Glejte, Gospod, Jehova, prihaja kot mogočni in rama njegova gospoduje zanj; glejte, plačilo njegovo je pri njem in povračilo njegovo pred njim!',
        11: 'Kakor pastir bo pasel čredo svojo, z roko svojo bo zbiral jagnjeta in jih nosil v naročju svojem, in doječe bo vodil rahlo.',
        12: 'Kdo je izmeril z dlanjo svojo vode in s pedjo svojo premeril nebesa in vtlačil zemlje prah v merico in s tehtnico pretehtal gore in hribe na njenih torilih?',
        13: 'Kdo je vodil duha Gospodovega, in kdo mu je bil svetovalec ter ga je učil?',
        14: 'S kom se je posvetoval, da bi mu dodelil razuma in ga učil poti pravice in ga vadil v znanju in mu pokazal najvišje razumnosti pot?',
        15: 'Glej, narodi so kakor kapljica v vedru in se čislajo kakor prašek na tehtničnem torilu; glej, otoke vzdiguje kakor trohico.',
        16: 'Tudi Libanona ne bi bilo dovolj za ogenj in živali njegovih ne bi bilo dovolj za žgalno daritev.',
        17: 'Vsi narodi so kakor nič pred njim, manj nego nič in ničevost.',
        18: 'Komu torej hočete primerjati Boga mogočnega? in kako podobo hočete postaviti poleg njega?',
        19: 'Podobo ulije umetnik in zlatar jo prevleče z zlatom in ji privari verižice srebrne.',
        20: 'Kdor je ubožen, da ne more toliko darovati, izbere les, ki ne trohni; poišče si spretnega umetnika, da mu napravi podobo, ki se ne omaja.',
        21: 'Ali ne veste? ali ne čujete? ali se vam ne oznanja od začetka? ali ne umejete ustanovitve zemlje?',
        22: 'On je, ki stoluje nad zemlje okrožjem, in prebivalci njeni so kakor kobilice, ki razprostira nebesa kakor tenčico in jih razpenja kakor šator v prebivanje;',
        23: 'ki deva v nič kneze, sodnike na zemlji nareja kakor ničevo stvar.',
        24: 'Komaj so zasajeni, komaj zasejani, komaj se ukorenini v zemlji njih deblo, že pihne on vanje, in posuše se in piš jih odnese kakor slamico.',
        25: 'Komu me torej hočete pripodobiti, da bi mu bil enak? pravi Sveti.',
        26: 'Povzdignite kvišku oči in glejte: Kdo je ustvaril vse te zvezde? On, ki vodi po številu njih vojsko, jih kliče vse po imenu; vsled presilne moči njegove in ker je mogočen v krepkoti, se niti ena ne pogreša.',
        27: 'Zakaj praviš, o Jakob, in govoriš, Izrael: Skrita je pot moja pred Gospodom in pravda moja gre mimo Boga mojega?',
        28: 'Ali ne veš? in nisi li slišal? Gospod je Bog večni, Stvarnik krajev zemlje; on ne opeša in se ne utrudi, nedoumna je razumnost njegova.',
        29: 'Trudnemu daje krepkosti in onemoglemu podeljuje obilo moči.',
        30: 'Pešajo res mladi in se utrujajo, in mladeniči se spotikajo in padajo;',
        31: 'oni pa, ki čakajo Gospoda, dobivajo nove moči, dvigajo se na perutih kakor orli, teko, a se ne utrudijo, hodijo, pa ne opešajo.',
    },
    41: {
        1: 'Obrnite se molče do mene, otoki, in narodi naj si oskrbe nove moči; pridejo naj bliže in tedaj govoré; snidimo se na skupno pravdo!',
        2: 'Kdo je obudil od vzhoda tistega, ki ga pravičnost srečava pri vsakem koraku? On daje narode pred njega in spravlja kralje pod njegovo oblast; nareja jih prahu podobne z mečem njegovim in razvejani plevi enake z lokom njegovim.',
        3: 'On jih podi in gre mimo v miru po poti, ki po njej nikdar ni šel z nogami svojimi.',
        4: 'Kdo je osnoval to in storil? On, ki kliče rodove od začetka. Jaz, Gospod, ki sem prvi in pri poslednjih večno isti.',
        5: 'Otoki so to videli in so se bali, kraji zemlje so trepetali; bližali so se in se shajali.',
        6: 'Drug drugemu je pomagal in bratu svojemu govoril: Bodi srčen!',
        7: 'In podobar je osrčeval zlatarja in on, ki gladi s kladivom, njega, ki bije na nakovalo, govoreč o spajanju: Dobro je! in je malika pritrjal z žeblji, da se ne gane.',
        8: 'Ti pa, Izrael, hlapec moj, Jakob, ki sem te izvolil, seme Abrahama, prijatelja mojega;',
        9: 'ti, ki sem te zgrabil od koncev zemlje in te poklical od skrajnih kotov njenih in ti rekel: Hlapec si moj, izvolil sem te in te nisem zavrgel:',
        10: 'Ne boj se, ker jaz sem s teboj, ne oziraj se plaho, ker jaz sem Bog tvoj; krepčam te, res, pomagam ti, res, podpiram te z desnico pravičnosti svoje.',
        11: 'Glej, osramočeni bodo in z nečastjo obliti vsi, ki se hudujejo nad teboj; kakor nič bodo in poginejo nasprotniki tvoji.',
        12: 'Ko jih boš iskal, jih ne najdeš, tistih, ki so se prepirali s tabo; kakor nič in ničevost bodo možje, ki se bore zoper tebe.',
        13: 'Zakaj jaz, Gospod, Bog tvoj, primem desnico tvojo, veleč ti: Ne boj se, jaz ti pomagam!',
        14: 'Ne boj se, črviček Jakobov, krdelce Izraelovo; jaz ti pomagam, govori Gospod, in odkupitelj tvoj je Svetnik Izraelov.',
        15: 'Glej, naredim te za novo mlatilnico z ostrimi dvoreznimi zobmi: mlatil boš in drobil gore in hribe boš storil v pleve.',
        16: 'Vejal jih boš, in veter jih odnese in vrtinec jih razkropi; ti pa se boš radoval v Gospodu, v Svetniku Izraelovem se boš ponašal.',
        17: 'Ubožce in siromake, ki iščejo vode, pa je ni, ki jim jezik suši od žeje, jaz, Gospod, jih uslišim, jaz, Bog Izraelov, jih ne zapustim.',
        18: 'Na golih višavah odprem reke in sredi dolin studence, v jezero vodá izpremenim puščavo in žejno zemljo v vrelce vode.',
        19: 'Cedro zasadim v puščavi, akacijo, mirto in oljkovo drevje, v pustinji hkratu postavim ciprese, platane in zelenike;',
        20: 'da bi videli in spoznali in v srce si vtisnili in razumeli vsi vkup, da je to storila roka Gospodova in da je Svetnik Izraelov to ustvaril.',
        21: 'Pridite sem s pravdo svojo, pravi Gospod; prinesite trdne dokaze svoje, veli Kralj Jakobov.',
        22: 'Predlože naj nam in naznanijo, kar se bo zgodilo; kaj so prejšnje stvari, razložite, da to razmislimo v srcu in spoznamo njih konec; ali kaj je prihodnjega, povejte nam!',
        23: 'Naznanite, kar pride pozneje; spoznamo naj, da ste bogovi! Storite vsaj kaj dobrega ali slabega kaj, da se ozremo drug na drugega in si skupaj ogledamo tisto.',
        24: 'Glejte, vi ste manj nego nič in delo vaše je ničevost; gnusoben je, kdor vas voli.',
        25: 'Obudil sem ga od severa in je prišel – od solnčnega vzhoda njega, ki kliče ime moje. In pride in pogazi vladarje kakor blato in kakor lončar gnete ilovico.',
        26: 'Kdo je to naznanil od početka, da bi vedeli? in od starodavnosti, da rečemo: Prav pravi! A ni ga bilo, da bi bil naznanil, ni ga bilo, ki bi bil napovedal, ni ga bilo, ki bi bil slišal besede vaše.',
        27: 'Prvi jaz sem rekel Sionu: Glej, glej, tu je! In Jeruzalemu dam blagovestnika!',
        28: 'In ozrl sem se, in ni bilo nikogar, in med temi ni bilo svetovalca, da bi bil odgovoril besedo, ko sem jih vprašal.',
        29: 'Glej, vsi ti skup so ničemurnost, nič niso njih dela; veter in pusta blodnja so njih ulite podobe.',
    },
    42: {
        1: 'Glej, hlapec moj, ki ga podpiram, izvoljenec moj, ki je duši moji po volji: duha svojega sem del nanj, pravico bo oznanjal poganskim narodom.',
        2: 'Vpil ne bo, ne hrupa napravljal, in glas njegov se ne bo čul po ulicah.',
        3: 'Trsta nalomljenega ne zlomi in tlečega stenja ne pogasi; po resnici bo oznanjeval pravico.',
        4: 'Ne bo opešal, ne bo potrt, dokler ne ustanovi pravice na zemlji; in otoki bodo čakali nauka njegovega.',
        5: 'Tako pravi Bog mogočni, Jehova, ki je ustvaril nebesa in jih razpel, ki je raztegnil zemljo ž njenim rastlinjem, ki daje dihanje ljudstvu, živečemu na njej, in duhá njim, ki hodijo po njej:',
        6: 'Jaz, Gospod, sem te poklical v pravičnosti, in primem te za roko in te bom čuval, in dam te v zavezo ljudstvu, v svetlobo poganskim narodom,',
        7: 'da odpreš slepe oči, da izvedeš iz zapora jetnike, iz ječe nje, ki sede v temi.',
        8: 'Jaz sem Gospod, to je ime moje, in slave svoje ne dam drugemu, ne hvale svoje rezanim podobam.',
        9: 'Prejšnje, glejte, se je zgodilo in novo naznanjam; preden nastane, vam napovedujem to.',
        10: 'Pojte Gospodu novo pesem, hvalo njegovo od konca zemlje vi, ki se vozite po morju, in vse, kar je v njem, otoki in njih prebivalci!',
        11: 'Zaženo naj glas puščava in mesta njena, vasi, v katerih prebiva Kedar; pojo naj prebivalci skalnega kraja, s temena gorá naj vpijejo.',
        12: 'Dajo naj slavo Gospodu in hvalo njegovo naj oznanjajo po otokih.',
        13: 'Gospod izide kakor junak, kakor mož bojevit zbudi gorečnost svojo, vpil bo in bojni krik zagnal, zoper sovražnike svoje se bo vedel junaško.',
        14: 'Molčal sem dolgo časa, bil sem tih in se zdrževal; sedaj pa bom vpil kakor porodnica in sopihal in hkrati duškal.',
        15: 'Opustošim gore in hribe in vso njih travo posušim in reke naredim v otoke in jezera posušim.',
        16: 'In popeljem slepce po potu, ki ga ne poznajo, po stezah, ki so jim tuje, jim dam hoditi; temo pred njimi naredim v svetlobo in hribast kraj v ravan. Te reči storim in jih ne opustim.',
        17: 'Umakniti se morajo, sramota jih oblije, kateri upajo v rezane podobe, kateri pravijo ulitim podobam: Vi ste bogovi naši.',
        18: 'Oj glušci, poslušajte, in vi slepci, odprite oči, da vidite!',
        19: 'Kdo je slep, če ne hlapec moj? in gluh kakor poslanec moj, ki ga pošiljam? Kdo je slep kakor on, ki je v miru z menoj, slep kakor hlapec Gospodov?',
        20: 'Videl si mnogo, a ne meniš se za to; ušesa odpira, vendar ne sliši.',
        21: 'Gospod je blagovolil zaradi pravičnosti svoje poveličati postavo in jo postaviti v čast.',
        22: 'A to je ljudstvo oplenjeno in oropano; vsi vkup so ujeti v luknjah in skrivajo se po ječah; v plen so, in nihče jih ne otimlje, ropanju so izročeni, in nihče ne pravi: Povrni jim!',
        23: 'Kdo je med vami, ki bi nagnil ušesa za to, ki bi pazil in poslušal v prihodnje?',
        24: 'Kdo je dal Jakoba v ropanje in Izraela njim, ki plenijo? Ali ne Gospod, zoper katerega smo grešili? Niso namreč hoteli hoditi po potih njegovih, in poslušali niso postave njegove.',
        25: 'Zato je razlil čezenj jeze svoje srd in vojske silo; ali dasi ga je zažgala kroginkrog, ni spoznal, zapalila ga je, a ni mu seglo v srce.',
    },
    43: {
        1: 'Sedaj pa pravi tako Gospod, ki te je ustvaril, Jakob, in ki te je upodobil, Izrael: Ne boj se! kajti odkupil sem te, poklical sem te po imenu tvojem; ti si moj!',
        2: 'Ko pojdeš skozi vode, bodem pri tebi, in preko rek, te ne poplavijo; ko pojdeš skozi ogenj, ne zgoriš in plamen te ne zapali.',
        3: 'Zakaj jaz sem Gospod, tvoj Bog, Svetnik Izraelov, rešitelj tvoj; v odkup tvoj sem dal Egipt, Etiopijo in Sebo zate.',
        4: 'Zato ker si drag v mojih očeh in čislan in ker te ljubim, hočem dati ljudi zate in narode za življenje tvoje.',
        5: 'Ne boj se, ker jaz sem s teboj. Od vzhoda privedem nazaj seme tvoje in zberem te od zahoda.',
        6: 'Severu zapovem: Daj nazaj! in poldnevu: Ne pridržuj, privedi sinove moje iz daljave in hčere moje od kraja zemlje,',
        7: 'vsakega, ki se imenuje po imenu mojem, ki sem ga ustvaril v slavo svojo, ki sem ga upodobil in naredil!',
        8: 'Izpelji ljudstvo slepo, ki ima oči, in glušce, ki imajo ušesa!',
        9: 'Vsi narodi naj se zbero in ljudstva naj se snidejo! Kdo med njimi more napovedati to? ali prejšnje reči naj nam oznanijo! postavijo naj priče svoje, da se opravičijo, da se bo slišalo in reklo: Res je.',
        10: 'Vi ste priče moje, govori Gospod, in hlapec moj, ki sem ga izvolil: da bi spoznali in verovali meni in umeli, da sem jaz večno isti. Pred menoj ni bil upodobljen Bog mogočni in ne bode ga za menoj.',
        11: 'Jaz, jaz sem Gospod, in ni ga razen mene rešitelja.',
        12: 'Jaz sem napovedoval in reševal in oznanjal, ne pa tuj bog med vami; in vi ste mi priče, govori Gospod, da sem jaz Bog mogočni.',
        13: 'Tudi od tega dne bodem večno isti, in ni ga, ki bi rešil iz roke moje. Delam, in kdo more zabraniti?',
        14: 'Tako pravi Gospod, odrešenik vaš, Svetnik Izraelov: Zaradi vas sem poslal v Babilon, in hočem jih vse kakor ubežnike gnati doli, tudi Kaldejce na ladjah, katerih so se veselili.',
        15: 'Jaz, Gospod, sem Svetnik vaš, stvarnik Izraelov, kralj vaš.',
        16: 'Tako pravi Gospod, ki dela pot po morju in stezo po silnih vodah,',
        17: 'ki izpeljava vozove in konje, krdela in moč – vkup bodo ležali, ne vstanejo več, izdahnejo, ugasnejo kakor predivo:',
        18: 'Ne spominjajte se prejšnjih reči in ne pečajte se za stare!',
        19: 'Glej, jaz storim novo stvar: zdajci že klije, ali bi je ne spoznali? Da, v puščavi naredim pot in reke v samoti.',
        20: 'Častila me bo žival poljska, šakali in noji, ker dam v puščavo vode, reke v samoto, da bodo v pijačo mojemu ljudstvu, izvoljenemu mojemu.',
        21: 'To ljudstvo, ki sem si ga izobrazil, bo pripovedovalo hvalo mojo. –',
        22: 'Kajti mene nisi klical, o Jakob, da bi se bil utrudil zame, o Izrael!',
        23: 'Nisi mi prinašal drobnice žgalnih darov svojih in z žrtvami svojimi me nisi častil. Nisem te tlačil, da mi služiš z jedilnim darom, in nisem ti prizadeval truda s kadilom;',
        24: 'nisi mi kupil z denarjem trsta dišečega in s tolščo žrtev svojih me nisi krepčal. Ali hlapčevsko delo si mi storil z grehi svojimi, utrudil si me s krivicami svojimi.',
        25: 'Jaz, jaz sam izbrisujem prestopke tvoje zaradi sebe, in grehov tvojih se ne spominjam več.',
        26: 'Opomni me, pravdajva se skupaj, razloži vendar svoje, da se opravičiš!',
        27: 'Tvoj prvi oče je grešil, in sredniki tvoji so se mi izneverili.',
        28: 'Zato sem onečastil poglavarje svetišča in prokletstvu izročil Jakoba in Izraela zasramovanju.',
    },
    44: {
        1: 'Sedaj pa poslušaj, Jakob, hlapec moj, in Izrael, ki sem ga izvolil.',
        2: 'Tako pravi Gospod, ki te je ustvaril in upodobil iz materinega telesa, ki ti pomaga: Ne boj se, hlapec maj Jakob, in Ješurun, ki sem te izvolil.',
        3: 'Kajti vode razlijem čez žejno in potoke na suho; duha svojega razlijem na seme tvoje in blagoslov svoj na potomce tvoje.',
        4: 'In razcveto se kakor med travo, kakor vrbe poleg vodotokov.',
        5: 'Ta poreče: Gospodov sem! in oni proglasi ime Jakobovo za svoje; oni pa se zapiše z roko svojo Gospodu, in častno ime mu bode Izrael.',
        6: 'Tako pravi Gospod, kralj Izraelov in odrešenik njegov, Gospod nad vojskami: Jaz sem prvi in jaz poslednji, in razen mene ni Boga.',
        7: 'In kdo kakor jaz more oznanjati – naj torej oznani in mi po vrsti ražloži! – odkar sem ustanovil starodavno ljudstvo? Naj torej oznanijo, kar bode in kar se zgodi!',
        8: 'Ne plašite se in ne bojte se! Nisem li tega oddavnaj ti dal slišati in ti naznanil? in vi ste priče moje. Ali je Bog razen mene? Gotovo ni nobene Skale, ne poznam nobene.',
        9: 'Kateri izrezujejo podobe, so vsi ničemurneži, in njih ljubčki ne morejo koristiti; in kateri so malikom priče, ne vidijo ničesar in ne spoznavajo, da bi jih bilo sram.',
        10: 'Kdo je kdaj upodobil boga in ulil podobo, da ne bi bil hotel nobene koristi?',
        11: 'Glej, vsi, ki se družijo z malikom, bodo osramočeni, in podobarji so goli ljudje. Zbero naj se vsi in skup se postavijo: preplašeni, osramočeni bodo vsi skupaj.',
        12: 'Kovač napravlja sekiro in dela z žerjavico in s kladivi upodablja malika in ga obdelava s krepko roko svojo; strada tudi, da mu peša moč, ne pije vode, da onemore.',
        13: 'Lesorezec potegne ravnalo, očrta s črtalom, izgladi s stružcem in nariše s šestilom, in ga naredi kakor podobo moža, kakor človeško lepoto, da prebiva v hiši.',
        14: 'Poseka si cedro ali vzame graden ali hrast in si izbira med drevjem v gozdu; in ko je vsadil jesen in ga je dež vzredil,',
        15: 'tedaj je človeku v sežig, ker vzame od njega, da se ogreje, in zakuri ž njim, da speče kruh; naredi tudi iz njega boga in se mu klanja; napravi iz njega podobo in pada prednjo na tla.',
        16: 'Polovico ga je požgal v ognju, pri polovici njegovi jé meso, peče pečenko in se siti; tudi greje se in pravi: Aha! ogrel sem se, čutim ogenj.',
        17: 'Iz ostanka njegovega naredi boga, podobo svojega malika, pada na tla pred njim ter se klanja in ga prosi, govoreč: Reši me, kajti bog mogočni si moj!',
        18: 'Ne spoznajo in ne razvidijo; zakaj zalepil jim je oči, da ne vidijo, in srca, da ne umejo.',
        19: 'In nihče ne pomisli v srcu in nima spoznanja in razsodnosti, da bi rekel: Polovico njega sem požgal v ognju in tudi pri žerjavici njegovi sem pekel kruh, pekel meso in sem jedel; in kar je ostalo od njega, naj napravim v stvar ostudno? pred lesenim hlodom naj padam na tla?',
        20: 'S pepelom se pase, srce prevarano ga zapeljuje, da ne more rešiti duše svoje, niti ne reče: Ni li prevara v desnici moji?',
        21: 'Spominjaj se tega, o Jakob, in Izrael, ker si hlapec moj. Upodobil sem te, hlapec si moj, Izrael, ne pozabim te.',
        22: 'Izbrisal sem kakor gost oblak prestopke tvoje in kakor meglo grehe tvoje. Vrni se k meni, kajti odkupil sem te.',
        23: 'Pojte, nebesa, zakaj Gospod je storil to! Ukajte, zemlje globočine, pojoč bobnite, gore, gozd in sleherno drevo v njem, zakaj Gospod je odkupil Jakoba in v Izraelu se oslavlja!',
        24: 'Tako pravi Gospod, odkupitelj tvoj in obrazovatelj tvoj iz materinega telesa: Jaz, Gospod, sem, ki delam vse: nebesa sem razpel sam, zemljo sem raztegnil – kdo je bil z menoj?',
        25: 'Jaz sem, ki uničujem znamenja lažnikov in iz vedeževalcev narejam neumneže, ki zavračam modre in abotno delam njih znanje;',
        26: 'ki potrjujem hlapca svojega besedo in dovršujem poslancev njegovih svèt, ki govorim o Jeruzalemu: Imel bo prebivalce! in o mestih Judovih: Zidala se bodo, in podrtine njegove postavim pokonci!',
        27: 'ki velim globočini: Posúši se, in reke tvoje posušim!',
        28: 'ki velim Ciru: Pastir moj je, in dopolni vso voljo mojo, ko ukaže za Jeruzalem: Bodi sezidan! in za tempelj: Ustanovi se!',
    },
    45: {
        1: 'Tako pravi Gospod maziljencu svojemu, Ciru, ki sem ga prijel za desnico, da porazim pred njim narode, in hočem razpasati ledje kraljem, da odprem duri pred njim in vrata ne ostanejo zaprta:',
        2: 'Jaz bom hodil pred teboj in poravnaval, kar ni ravno; vrata jeklena razbijem in polomim železne zapahe,',
        3: 'in dam ti zaklade, zakopane v temi, in blago, shranjeno na skrivnem, da spoznaš, da sem jaz Gospod, ki sem te poklical po imenu tvojem, Bog Izraelov.',
        4: 'Zaradi hlapca svojega Jakoba in Izraela, izvoljenca svojega, sem te klical po imenu tvojem, dal ti priimek, dasi me nisi poznal.',
        5: 'Jaz sem Gospod in nobenega drugega ni, razen mene ni Boga. Opašem te, dasi me ne poznaš,',
        6: 'da naj spoznajo od solnčnega vzhoda in od zahoda njegovega, da ni nobenega drugega razen mene. Jaz sem Gospod in nobenega drugega ni!',
        7: 'ki ustvarjam svetlobo in delam temo, narejam mir in napravljam nesrečo; jaz Gospod sem, ki delam vse to.',
        8: 'Rosite z viška, nebesa, in najvišji oblaki, dežíte pravičnost! odpri se, zemlja, in ródi zveličanje in hkratu naj vzraste pravičnost. Jaz, Gospod, sem ustvaril to.',
        9: 'Gorje mu, ki se prepira z obrazovateljem svojim, čepinja med čepinjami prstenimi! Sme li pač reči glina obrazovatelju svojemu: Kaj delaš? ali tvoje delo o tebi: Rok nima!',
        10: 'Gorje njemu, ki pravi očetu: Čemu rodiš? in ženi: Čemu si v porodnih bolečinah?',
        11: 'Tako pravi Gospod, Svetnik Izraelov in obrazovatelj njegov: Vprašajte me za to, kar ima priti, za otroke moje in za rok mojih delo mi naročajte!',
        12: 'Jaz sem naredil zemljo in ustvaril človeka na njej; jaz, moje roke so razpele nebesa in sleherni njih vojski sem dal povelja.',
        13: 'Jaz sem ga zbudil v pravičnosti in poravnam vsa pota njegova; on sezida mesto moje in odgnance moje pošlje nazaj, ne za kupno ceno ne za denar, govori Gospod nad vojskami.',
        14: 'Tako pravi Gospod: Pridelek egiptovski in dobiček Etiopije in Sabejci, možje visoke postave, preidejo na tvojo stran in bodo tvoji; za teboj pojdejo, zvezani preidejo k tebi in tebi se bodo klanjali, tebe bodo prosili, govoreč: Zares, Bog mogočni je pri tebi, in nobenega drugega Boga ni nikjer drugod.',
        15: 'Resnično, ti si Bog mogočni, skrivajoči se, o Bog Izraelov, Rešitelj!',
        16: 'Sramovali se bodo in osramočeni bodo vsi, s sramoto odidejo vsi podobarji!',
        17: 'Izrael bo rešen po Gospodu z večnim rešenjem; ne bode vas sram in osramočeni ne boste na večne veke.',
        18: 'Kajti tako pravi Gospod, stvarnik nebes (on sam je Bog!), obrazovatelj zemlje in stvaritelj njen; on jo je utrdil, ni je ustvaril puste, ampak upodobil jo je v prebivanje: Jaz sem Gospod in drugega ni nobenega.',
        19: 'Nisem govoril na skrivnem, v kraju temne zemlje; nisem velel semenu Jakobovemu: Iščite me brezuspešno! Jaz sem Gospod, ki govorim pravičnost, oznanjam, kar je pravo.',
        20: 'Zberite se in pridite, bližajte se vsi, ki ste ušli iz poganskih narodov! Nimajo spoznanja, ki nosijo les rezane podobe svoje in molijo k bogu, ki ne more rešiti.',
        21: 'Napovejte in blizu prinesite! Tudi posvetujejo naj se med seboj! Kdo je oznanjal to od prvih dni, kdo je napovedoval to od davnega časa? Ali ne jaz, Gospod? in nobenega drugega Boga ni razen mene; mogočnega Boga, pravičnega in rešitelja ni drugega razen mene.',
        22: 'Ozrite se v mene in rešeni bodete, vsi kraji zemlje, zakaj jaz sem Bog mogočni in drug nobeden.',
        23: 'Pri sebi sem prisegel, iz ust pravičnosti je prišla beseda, ki se ne prekliče: da se meni pripogne vsako koleno, meni bo prisegal vsak jezik.',
        24: 'Samo v Gospodu, poreko o meni, je vsa pravičnost in moč. K njemu pridejo, ali osramočeni bodo vsi, ki so se vnemali zoper njega.',
        25: 'V Gospodu bo opravičeno in se bo hvalilo vse seme Izraelovo.',
    },
    46: {
        1: 'Zgrudil se je Bel, omahnil je Nebo; njih maliki so bili naloženi živalim in govedom; stvari, ki ste jih prenašali, so tovor, breme utrujeni živali.',
        2: 'Omahnili so, zgrudili so se vsi, niso mogli oteti bremena, temuč sami so odšli v sužnost.',
        3: 'Poslušajte me, o hiša Jakobova in ves ostanek hiše Izraelove, ki vas nosim od materinega telesa, pestujem od materinega naročja!',
        4: 'In prav do starosti sem jaz vedno isti, in do sivosti vas bom jaz nosil; jaz sem storil in jaz bom prenašal, jaz, pravim, bom nosil in rešil.',
        5: 'Komu me hočete prilikovati in enačiti ali me primerjati, da bi bili podobni?',
        6: 'Kateri trosijo zlato iz mošnje in tehtajo srebro na tehtnici, najmejo za plačo zlatarja, ki naj naredi iz njega boga; padajo na tla ter se mu klanjajo,',
        7: 'vzdigujejo ga, nosijo ga na rami, nato ga postavijo na mesto svoje, kjer stoji; z mesta svojega se ne gane. Tudi vpijejo k njemu, a ne odgovori, nikogar ne reši iz stiske njegove.',
        8: 'Pomnite to in bodite možje, premislite v srcu, odpadniki!',
        9: 'Spominjajte se početkov od večnosti, da sem jaz Bog mogočni in nobenega ni drugega, da sem Bog, in nihče ni meni enak,',
        10: 'ki oznanjam od početka konec in od starodavnosti, kar se ni še zgodilo; ki velim: Sklep moj bo stal in storil bom vse, kar me veseli;',
        11: 'ki kličem od vzhoda ptico roparico, iz daljne dežele izvršitelja svojega sklepa. Govoril sem in tudi storim, da pride tisto; načrt sem napravil, pa tudi izvršim tisto.',
        12: 'Poslušajte me, uporni v srcu, ki ste daleč od pravičnosti!',
        13: 'Blizu sem pripravil pravičnost svojo, ni daleč, in zveličanje moje se ne bo obotavljalo; in na Sionu dam zveličanje, Izrael bode slava moja.',
    },
    47: {
        1: 'Stopi doli in sedi v prah, o devica, hči babilonska! Sedi na tla, brez prestola, hči Kaldejcev! kajti ne boš se več imenovala nežna in mehkužna.',
        2: 'Vzemi mlinske kamene in melji moko; odgrni zastor svoj, vzdigni vlečke, odkrij stegno, gazi skozi reke.',
        3: 'Odkrije se nagota tvoja, videla se bo tudi sramota tvoja. Maščeval se bom in ne prizanesem nobenemu človeku. –',
        4: 'Naš odrešenik, Gospod nad vojskami je ime njegovo, Svetnik Izraelov. –',
        5: 'Sédi molčé in pojdi v temo, hči Kaldejcev! zakaj ne boš se več imenovala Gospa kraljestev.',
        6: 'Razsrdil sem se bil zoper ljudstvo svoje, oskrunil sem dediščino svojo in dal sem jih tebi v pest: nisi jim izkazala nobene milosti, celó starcu si nakladala težki jarem svoj silno.',
        7: 'In rekla si: Večno bodem gospa! in tako nisi tega premislila v srcu, pomislila nisi konca temu.',
        8: 'Sedaj torej čuj to, razkošnica, ki brez skrbi sediš in praviš v srcu svojem: Jaz sem, in nobene več ni razen mene; ne bom sedela vdova in okusila ne bom brezotročnosti!',
        9: 'Ali prigodi se ti oboje nagloma, v isti dan: brezotročnost in vdovstvo; docela te zadene oboje navzlic obilemu vražarstvu tvojemu, vkljub silno številnemu čaranju tvojemu.',
        10: 'Zakaj ti si se zanašala na hudobnost svojo, govorila si: Nihče me ne vidi. Modrost tvoja in vednost tvoja, ti sta te premotili; in govorila si v srcu svojem: Jaz sem, in nobene druge več razen mene!',
        11: 'Zatorej te zadene nesreča, ki je ne boš znala s čaranjem odpraviti, zgrne se nadte poguba, ki je ne boš mogla odvrniti, in zadene te nagloma pokončanje, ki ga še ne slutiš.',
        12: 'Postavi se, pravim, s čaranjem svojim in z množino svojega vražarstva, v katerem si se trudila od mladih nog svojih, če boš morda imela kaj uspeha, če morebiti koga prestrašiš!',
        13: 'Opešala si vsled tolikega posvetovanja svojega. Postavijo naj se torej razkladalci nebes, ogledovalci zvezd, ki oznanjajo na mesece, kar te bo zadelo, in naj te rešijo!',
        14: 'Glej, kakor strnišče so, ogenj jih požge, ne rešijo se sami plamena; ne ostane od njih žerjavice, da bi se človek grel, ne ognja, da bi mu sedel nasproti.',
        15: 'Tako ti bodo oni, za katere si se trudila, s katerimi si kupčevala od mladosti svoje: vsak bo blodil na svojo stran, nihče te ne reši.',
    },
    48: {
        1: 'Poslušajte to, hiša Jakobova, ki se kličete po imenu Izraelovem in ste izšli iz vodá Judovih, ki prisegate pri imenu Gospodovem in hvalno omenjate Boga Izraelovega, a ne v resnici in ne v pravičnosti;',
        2: 'zakaj imenujejo se po svetem mestu in opirajo se na Boga Izraelovega, Gospod nad vojskami je ime njegovo:',
        3: 'Prejšnje sem naznanjal od nekdaj, in iz mojih ust je izšlo in sem to razglasil; mahoma sem to dopolnil, in zgodilo se je.',
        4: 'Ker sem vedel, da si trd in da je kita železna tilnik tvoj in čelo tvoje jekleno,',
        5: 'zato sem ti to naznanjal od nekdaj; ko se ni še zgodilo, sem ti povedal to, da bi ne govoril: Malik moj je storil to in izdolbena ali ulita podoba moja je zapovedala tisto.',
        6: 'Slišal si to; ogleduj vse to! in vi, nočete li tega priznati? Odslej ti napovedujem novo in dosihdob skrito, česar nisi vedel.',
        7: 'Sedaj se to ustvarja, ne pa oddavna, in pred tem dnevom nisi slišal za to, da ne porečeš: Glej, vedel sem to.',
        8: 'Niti slišal nisi nič niti vedel, tudi od nekdaj ni bilo odprto uho tvoje; kajti poznal sem te, da ravnaš silno nezvesto in da se imenuješ prestopnik od materinega telesa.',
        9: 'Zaradi imena svojega zadržujem jezo svojo in zaradi hvale svoje jo krotim, tebi v prid, da te ne iztrebim.',
        10: 'Glej, prečistil sem te, a ne kot srebro; izbranega sem te naredil v topilnici bridkosti.',
        11: 'Zaradi sebe, zaradi sebe storim to, kajti kako bi se oskrunilo ime moje! in slave svoje ne dam drugemu.',
        12: 'Poslušaj me, o Jakob, in Izrael, poklicanec moj! Jaz sem večno isti, jaz sem prvi, jaz tudi poslednji.',
        13: 'Moja roka je vendar ustanovila zemljo in desnica moja razpela nebesa; ko sem jih poklical, brž so bila vsa tu.',
        14: 'Zberite se vi vsi in čujte: Kdo izmed onih je naznanil tisto? Ki ga Gospod ljubi, ta izpolni voljo njegovo nad Babilonom in roka njegova bode nad Kaldejci.',
        15: 'Jaz, jaz sem govoril, jaz sem ga tudi poklical; pripeljal sem ga, in pot njegova bode uspešna.',
        16: 'Pristopite k meni, čujte to! Od početka nisem na skrivnem govoril; od tistega časa, ko se je zgodilo to, sem bil pri tem. In sedaj me je poslal Gospod Jehova in duh njegov. –',
        17: 'Tako pravi Gospod, odrešenik tvoj, Svetnik Izraelov: Jaz sem Gospod, Bog tvoj, ki te učim, kar ti je v korist, ki te spremljam po potu, po katerem ti je hoditi.',
        18: 'O da bi bil pazil na zapovedi moje! tedaj bi bil kakor reka mir tvoj in pravičnost tvoja kakor morsko valovje;',
        19: 'in kakor pesek bi bil zarod tvoj in rojeni iz osrčja tvojega kakor kamenjiče njegovo; njegovo ime bi se ne zatrlo in ne pogubilo izpred mojega obličja.',
        20: 'Pojdite ven iz Babilona, bežite od Kaldejcev; z zmagoslavnim glasom naznanjajte, pripovedujte to, razširjajte to do kraja zemlje! Govorite: Odkupil je Gospod hlapca svojega Jakoba.',
        21: 'In žejni niso bili, ko jih je vodil po puščavah; točil jim je vode iz skale: razklal je skalo, in vode so tekle!',
        22: 'Ni ga miru, pravi Gospod, brezbožnim.',
    },
    49: {
        1: 'Poslušajte me, otoki, in pazite, ljudstva iz daljave! Gospod me je poklical od materinega telesa, od osrčja matere moje se me je spominjal.',
        2: 'In naredil je usta moja kakor oster meč, s senco roke svoje me je zakril; in naredil me je za pšico izbrušeno, v tulu svojem me je skril.',
        3: 'In mi je rekel: Hlapec si moj, Izrael, po katerem se bom oslavljal. –',
        4: 'Jaz pa sem rekel: Brezuspešno sem se trudil, brezkoristno in za nič sem potratil moč svojo; vendar pa je pravica moja pri Gospodu in plačilo moje je pri Bogu mojem.',
        5: 'Sedaj pa govori Gospod, ki me je izobrazil od materinega telesa za hlapca svojega, naj Jakoba nazaj pripeljem k njemu in da bodi Izrael zbran k njemu (ker sem slaven v očeh Gospodovih in Bog moj je postal moja moč),',
        6: 'govori, pravim: Malo je, da si mi hlapec, da bi povzdignil rodove Jakobove ter nazaj pripeljal ohranjence Izraelove; tudi te postavim za luč poganskim narodom, da bodeš zveličanje moje prav do konca zemlje.',
        7: 'Tako pravi Gospod, odrešenik Izraelov, Svetnik njegov, njemu, ki ga zaničuje vsakdo, ki je gnus narodov, hlapcu gospodovalcev: Kralji te bodo videli in spoštljivo vstali, knezi se bodo klanjali zaradi Gospoda, ki je zvest, Svetnika Izraelovega, ki te je izvolil.',
        8: 'Tako pravi Gospod: Ob času milosti sem te uslišal in v dan zveličanja sem ti pomagal; in stražil te bom in te dal v zavezo ljudstvu, da povzdigneš deželo, da v posest razdeliš opustošene dediščine,',
        9: 'da porečeš jetnikom: Pojdite ven! njim, ki sede v teminah: Pridite na svetlo! Po potih se bodo pasli in po vseh golih hribih imeli svojo pašo.',
        10: 'Lačni ne bodo, ne žejni, tudi zračna prikazen jih ne omami in solnce ne zadene; kajti njih milostnik jih bo vodil in poleg vrelcev vodá jih bo peljal.',
        11: 'In vse svoje gore naredim, da bodo prelazne, in moje ceste se bodo z nasipom povišale.',
        12: 'Glej, ti pridejo od daleč, in glej, ti od severa in od zahoda, in ti iz dežele Sinimcev.',
        13: 'Prepevajte, nebesa, in raduj se, zemlja, in pojoč bobnite, gore! zakaj Gospod je potolažil ljudstvo svoje in se je usmilil siromakov svojih.',
        14: 'A Sion je rekel: Jehova me je zapustil in Gospod me je pozabil.',
        15: 'More li žena pozabiti dojenca svojega, da bi se ne usmilila sina telesa svojega? In ko bi tudi matere pozabile, jaz vendar ne pozabim tebe!',
        16: 'Glej, na obe dlani sem si te vdolbel; zidovi tvoji so vedno pred mano.',
        17: 'Hiteli bodo k tebi otroci tvoji; podiralci tvoji in opustoševalci tvoji odidejo iz tebe.',
        18: 'Ozri se kroginkrog in glej: tisti vsi se zbirajo in prihajajo k tebi. Kakor res živim, govori Gospod, z vsemi tistimi se boš oblekla kakor z lepotičjem, obvezala si jih boš kakor nevesta.',
        19: 'Zakaj, kar se tiče tvojih razvalin in podrtih mest tvojih in porušene dežele tvoje – sedaj bodeš res pretesna za prebivalce; in tisti, ki so te požirali, odidejo daleč.',
        20: 'Še poreko, da boš slišala, otroci osamljenja tvojega: Pretesno mi je to mesto; naredi mi prostora, da morem prebivati!',
        21: 'Tedaj porečeš v srcu svojem: Kdo mi je rodil tiste, ko sem bila brez otrok in nerodovitna, pregnana in sem se semtertja potikala? in kdo mi je vzredil téle? Glej, saj sem bila zapuščena samica, kje so bili tile?',
        22: 'Tako pravi Gospod Jehova: Glej, proti narodom povzdignem roko svojo in proti ljudstvom postavim zastavo svojo, in prineso sinove tvoje v naročju in hčere tvoje bodo nosili sem na svojih ramah.',
        23: 'In kralji bodo redniki tvoji in njih kneginje dojke tvoje; klanjali se ti bodo z obličjem do tal in prah tvojih nog bodo lizali. In spoznaš, da sem jaz Gospod: ne osramoté se, ki me čakajo.',
        24: 'Se li more velikanu odvzeti plen? ali se morejo oteti, ki so ujeti po pravici?',
        25: 'Res, tako pravi Gospod: Tudi jetniki velikanovi se mu vzamejo in plen siloviteža se otme; kajti jaz se bom boril zoper tiste, ki se s teboj bore, in otroke tvoje rešim jaz.',
        26: 'In storim, da bodo zatiralci tvoji jedli lastno svoje meso, in kakor z vinom se bodo upijanjali s svojo krvjo; in spozna vse meso, da sem jaz Gospod zveličar tvoj in odrešenik tvoj, Mogočni Jakobov.',
    },
    50: {
        1: 'Tako pravi Gospod: Kje je matere vaše ločitni list, s katerim sem jo odslovil? ali kdo je izmed upnikov mojih, ki sem mu vas prodal? Glejte, zaradi svojih krivic ste prodani in zaradi vaših prestopkov je odslovljena mati vaša.',
        2: 'Zakaj ni bilo nikogar, ko sem prišel? ko sem klical, nihče ni odgovoril? Je li mar roka moja prekratka, da bi otela? ali pa ni v meni moči nobene za rešenje? Glej, s karanjem svojim posušam morje, reke izpreminjam v puščavo, da njih ribe gnijejo in mrjo od žeje, zato ker ni vode.',
        3: 'Nebesa oblačim v črnino in raševino jim napravljam za odejo.',
        4: 'Gospod Jehova mi je dal izurjen jezik, da znam o pravem času izreči besedo trudnemu. Zbuja me sleherno jutro, zbuja mi uho, da poslušam kakor učenec.',
        5: 'Gospod Jehova mi je odprl uho, in jaz se nisem upiral, ne se umaknil.',
        6: 'Život svoj sem izpostavil njim, ki so me bili, in lice svoje njim, ki so me tezali; obličja svojega nisem skril sramotenju in pljuvanju.',
        7: 'Kajti Gospod Jehova mi pomaga, zato nisem bil osramočen; zatorej sem nastavil obličje svoje kakor pretrd kamen in vem, da ne pridem v sramoto.',
        8: 'Blizu je on, ki me opravičuje; kdo se bo prepiral z menoj? Stopiva si nasproti! Kdo hoče poskusiti pravdo zoper mene? naj pride k meni!',
        9: 'Glej, Gospod Jehova mi bo pomagal: kdo je, ki bi me obsodil? Glej, vsi skup se postarajo kakor sukno, molj jih pokonča.',
        10: 'Kdo je med vami, ki se boji Gospoda, ki posluša hlapca njegovega glas? Kdor hodi po temi, komur ni svetlobe, upaj v ime Gospodovo in opiraj se na Boga svojega!',
        11: 'Glejte, vi vsi, ki vžigate ogenj, z ognjenimi strelami se oborožujete: pojdite v žar ognja svojega in v požare, ki ste jih zapalili. To se vam zgodi od moje roke, v bolesti boste ležali.',
    },
    51: {
        1: 'Poslušajte me vi, ki hodite za pravičnostjo, ki iščete Gospoda! Glejte na skalo, iz katere ste izsekani, in v votlino jame, iz katere ste izkopani!',
        2: 'Glejte na Abrahama, očeta svojega, in na Saro, ki vas je rodila: kajti poklical sem ga, ko je bil edinec, in sem ga blagoslovil in ga pomnožil.',
        3: 'Zakaj Gospod je potolažil Sion, potolažil je vse razvaline njegove in je naredil puščavo njegovo kakor raj in samoto njegovo kakor vrt Gospodov; veselje in radost bo na njem, zahvala in psalmov glas.',
        4: 'Poslušajte me, ljudstvo moje, in narod moj, obrnite ušesa v me! kajti postava pride od mene, in pravico svojo postavim ljudstvom za svetlobo.',
        5: 'Blizu je pravičnost moja, izšlo je zveličanje moje, in roke moje bodo sodile ljudstva, v meni bodo imeli upanje otoki in čakali bodo rame moje.',
        6: 'Povzdignite proti nebesom oči in glejte zemljo spodaj! zakaj nebesa izginejo kakor dim in zemlja se postara kakor obleka, in prebivalci njeni pomrjo enako. Ali zveličanje moje bode vekomaj in pravičnost moja se ne okruši.',
        7: 'Poslušajte me vi, ki poznate pravičnost, ljudstvo, ki ima postavo mojo v srcu svojem: Ne bojte se zasramovanja smrtnega človeka in ne plašite se njih preklinjanja!',
        8: 'Zakaj kakor sukno jih razje molj in kakor volno jih razgrize črvič; pravičnost moja pa bode vekomaj in zveličanje moje od roda do roda.',
        9: 'Zbudi se, zbudi, obleci moč, o rama Gospodova! Zbudi se kakor v starih časih, pri nekdanjih rodovih! Ali nisi ti tista, ki je razdrobila Egipt, ki je presunila morskega velikana?',
        10: 'Ali nisi ti tista, ki je posušila morje, velikega brezna vode, ki je naredila morske globočine za pot, po katerem naj preidejo odkupljeni?',
        11: 'In odrešenci Gospodovi se vrnejo ter pridejo na Sion s petjem, in večna radost bode nad njih glavo; veselje in radost jih objame, a žalovanje in zdihovanje pobegne.',
        12: 'Jaz, jaz sam sem tolažitelj vaš. Kdo si ti, da se bojiš človeka, ki umrje, in sina človekovega, ki izgine kakor seno?',
        13: 'in da zabiš Gospoda, stvarnika svojega, ki je razpel nebo in ustanovil zemljo, in si v strahu vedno, vsak dan, zaradi togote stiskalčeve, ko se pripravlja, da bi pogubil? In kje je togota stiskalčeva?',
        14: 'Hitro bo izpeljan v prostost tisti, ki je sključen v okovih, in ne umre in ne pade v jamo, tudi ne bo pogrešal kruha svojega.',
        15: 'Zakaj jaz sem Gospod, Bog tvoj, ki razburjam morje, da bučé njegovi valovi; Gospod nad vojskami je ime njegovo.',
        16: 'In položil sem besede svoje v usta tvoja in zakril sem te z roke svoje senco, da zgradim nebesa in ustanovim zemljo ter rečem Sionu: Ljudstvo si moje.',
        17: 'Zbudi se, zbudi, vstani, jeruzalemska hči, ki si iz roke Gospodove pila togote njegove čašo; kupo, čašo omotno si pila, izsrebala.',
        18: 'Nikogar ni bilo, da bi jo bil vodil, izmed vseh otrok, ki jih je rodila, ne enega, ki bi jo bil prijel za roko, izmed vseh sinov, ki jih je vzredila.',
        19: 'Tisto dvoje se ti je prigodilo, kdo bi te miloval? –: razdejanje in podrtje, lakota in meč. Kako naj te potolažim?',
        20: 'Otroci tvoji so onemogli, leže po vseh ulicah in voglih kakor jelen v mreži; polni so togote Gospodove, grožnje Boga tvojega.',
        21: 'Zato čuj vendar, o ponižana in pijana, a ne vina:',
        22: 'Tako govori Gospod tvoj, Jehova, in Bog tvoj, ki se poteguje za pravdo ljudstva svojega: Glej, iz roke tvoje jemljem čašo omotno, čašo togote svoje: ne boš je več pila.',
        23: 'Ampak dam jo v roko njih, ki te ponižujejo, ki so govorili duši tvoji: Vrzi se na tla, da pojdemo čeznjo! In ti si naredila kakor tla hrbet svoj in kakor cesto čezenj gredočim.',
    },
    52: {
        1: 'Zbudi se, zbudi, obleci moč svojo, o Sion; obleci oblačila dike svoje, o Jeruzalem, sveto mesto! Kajti odslej ne stopi več v te neobrezani in nečisti.',
        2: 'Otresi si prah, vstani, sedi, Jeruzalem; reši se vezi vratu svojega, o ujeta hči sionska!',
        3: 'Kajti tako pravi Gospod: Brez plačila ste bili prodani in brez denarja boste odkupljeni.',
        4: 'Zakaj tako pravi Gospod Jehova: V Egipt doli je bilo šlo ljudstvo moje s početka, da bi tujčevalo tam, in Asirec ga je tlačil za nič.',
        5: 'Sedaj pa, kaj mi je tukaj storiti? govori Gospod; kajti ljudstvo moje so na tuje vzeli brez plačila! gospodovalci njegovi ukajo, govori Gospod, in neprestano, ves dan je v zaničevanju ime moje.',
        6: 'Zato bo ljudstvo moje spoznalo ime moje; zato spoznajo prav tisti dan, da sem jaz tisti, ki govori: Glej, tukaj sem!',
        7: 'Kako lepe so na gorah noge blagovestnika, ki proglaša mir, oznanja blagovest o dobrem, proglaša zveličanje, ki govori Sionu: Bog tvoj kraljuje!',
        8: 'Glas ogledovalcev tvojih! Povzdigujejo glas, skupaj veselo pojo, kajti vidijo iz oči v oči, da pelje Gospod nazaj Sion.',
        9: 'Vdajte se radosti, skupaj pojte veselo, razvaline jeruzalemske! zakaj Gospod je potolažil ljudstvo svoje, odrešil Jeruzalem.',
        10: 'Razgalil je Gospod svetosti svoje ramo pred očmi vseh narodov, in vsi kraji zemlje bodo videli našega Boga zveličanje. –',
        11: 'Odstopite, odstopite, idite odondod, ničesar nečistega se ne doteknite! Pojdite izsredi njega, očistite se vi, ki nosite posode Gospodove!',
        12: 'Kajti ne odidete v naglici in ne boste hodili begoma; ker Gospod bo hodil pred vami in zadnja straža vam bode Bog Izraelov.',
        13: 'Glej, hlapec moj bo modro ravnal; povzdigne se in vzviša, in visok bode silno.',
        14: 'Kakor so o tebi osupnili mnogi (tako je bil obraz njegov spačen, bolj nego katerega moža, in podoba njegova bolj nego otrok človeških),',
        15: 'tako pripravi v strmenje mnogo narodov; zaradi njega si kralji zatisnejo usta. Zakaj videli bodo, kar jim ni bilo povedano, in česar niso čuli, bodo razumeli.',
    },
    53: {
        1: 'Kdo je veroval oznanilu našemu in komu se je razodela rama Gospodova?',
        2: 'Kajti on je vzrastel kakor mladika pred njim in kakor korenina iz suhe zemlje. Ni imel podobe, ne lepote; in ko smo ga videli, ni imel mične zunanjosti, da bi si ga bili želeli.',
        3: 'Zaničevan je bil in preziran med možmi, mož bolečin in izkušen v trpljenju, in kakor človek, pred katerim skrivajo obličje, je bil zaničevan, in nič ga nismo čislali.',
        4: 'Zares, on je nosil bolezni naše in si je naložil bolečine naše; mi pa ga smo šteli za kaznjenega, ki ga je Bog udaril in ponižal.',
        5: 'A on je bil ranjen zaradi naših prestopkov, je bil potrt zaradi naših krivic; kazen ga je zadela zaradi našega miru in rane njegove so bile nam v ozdravljenje.',
        6: 'Mi vsi smo tavali kakor ovce, obrnili smo se vsak na svoj pot; in Gospod mu je naložil nas vseh krivice.',
        7: 'Mučili so ga, a ponižal se je in ni odprl ust svojih kakor jagnje, ki ga peljejo v zakol, in kakor ovca, ki molči pred strižci svojimi; in ni odprl svojih ust.',
        8: 'Iz stiske in iz sodbe je bil vzet – a izmed njegovih vrstnikov kdo je pomislil, da je bil odrezan iz dežele živečih? zaradi prestopka ljudstva mojega ga je zadel udarec.',
        9: 'In dali so mu grob pri brezbožnih, a pri bogatinu je bil po mučni smrti svoji, zato ker ni storil krivice in ni bilo zvijače v ustih njegovih.',
        10: 'Ali Gospod ga je hotel streti, on ga je izročil trpljenju. Ko izvrši duša njegova daritev za greh, bo videl zarod, podaljšal dni svoje, in kar je Gospodu po volji, bo uspevalo v roki njegovi.',
        11: 'Od nadloge duše svoje bo videl sad in se sitil. S poznanjem svojim bo pravični hlapec moj mnoge storil pravične; in njih krivice bo naložil nase.',
        12: 'Zato mu dam velike v delež in delil bo plen z mogočnimi; zato ker je žrtvoval dušo svojo v smrt in je bil grešnikom prištet; on je nesel greh mnogih in prosil za grešnike.',
    },
    54: {
        1: 'Prepevaj, nerodovitna, ki nisi rodila; vdaj se radosti in glasno vpij, ki nisi trpela porodnih bolečin! zakaj več sinov bo imela zapuščena nego omožena, pravi Gospod.',
        2: 'Razširi prostor šatora svojega in pregrinjala stanov tvojih naj raztegnejo, ne brani! Podaljšaj vrvi svoje in kole svoje pritrdi!',
        3: 'Kajti na desno in na levo prodereš in seme tvoje podeduje narode in opustošena mesta napolni z ljudmi.',
        4: 'Ne boj se, ker ne boš osramočena, in ne bodi oblita z nečastjo, ker ne prideš v sramoto; temuč sramoto mladosti svoje pozabiš in vdovstva svojega nečasti se ne boš več spominjala.',
        5: 'Kajti soprog tvoj je on, ki te je ustvaril, Gospod nad vojskami je ime njegovo; in odrešenik tvoj je Svetnik Izraelov; Bog vse zemlje se bo imenoval.',
        6: 'Zakaj kakor ženo zapuščeno, žalostno v srcu te pokliče Gospod, kakor ženo mladosti, ko je zavržena, pravi Bog tvoj.',
        7: 'Za kratek trenotek sem te bil zapustil, ali zberem te z usmiljenjem velikim;',
        8: 'v nekolikem srdu sem bil za trenotek skril obličje svoje pred teboj, ali v večni milosti se te usmilim, govori Gospod, odrešenik tvoj.',
        9: 'Kajti kakor vode Noetove mi je to: kakor sem prisegel, da ne pridejo več vode Noetove na zemljo, tako sem prisegel, da se ne razsrdim zoper tebe in te ne pokaram.',
        10: 'Kajti gore se bodo pač umeknile in hribi se genili, a milost moja se ne umakne od tebe in miru mojega zaveza se ne gane, govori Gospod, milostnik tvoj.',
        11: 'O ubožica, ki te preganjajo nevihte, ki nimaš tolažbe! glej, jaz položim kamene tvoje v svinčeni sijajnik in v podstavo ti denem safire;',
        12: 'in iz rubina naredim line tvoje in vrata tvoja iz ognjencev in vso mejo tvojo iz milovidnih kamenov.',
        13: 'In vsi otroci tvoji bodo učenci Gospodovi in obilen mir bode otrokom tvojim.',
        14: 'Po pravičnosti boš utrjena. Daleč se umakni bridkosti, ker se ti ni ničesar bati, in strahu, ker se ti ne bo bližal.',
        15: 'Glej, čeprav se zbirajo zoper tebe, to ni od mene; kdor se zbira zoper tebe, pade ob tebi.',
        16: 'Glej, jaz sem ustvaril kovača, ki piha v goreče oglje in nareja orodje za delo svoje; enako sem jaz ustvaril morilca, da pokončuje.',
        17: 'Nobeno orodje, narejeno zoper tebe, ne bo imelo uspeha, in sleherni jezik, ki se postavi zoper tebe na sodbo, obsodiš. To je dediščina hlapcev Gospodovih in njih pravičnost, ki prihaja od mene, govori Gospod.',
    },
    55: {
        1: 'Hej, vsi, katerikoli ste žejni, pridite k vodam, in kateri nimate denarja, pridite, kupite in jejte! Pridite, pravim, kupite brez denarja in brez plačila vina in mleka!',
        2: 'Čemu trošite denar za to, kar ni kruh, in trud svoj za to, kar ne more nasititi? Poslušajte vendar mene in jejte, kar je dobro, in tolstino veselo uživaj duša vaša!',
        3: 'Nagnite uho in pridite k meni, poslušajte, in duša vaša bo živela! In sklenem z vami zavezo večno: milosti Davidove, stanovitne.',
        4: 'Glej, za pričo narodom sem ga postavil, za vojvodo in zapovednika narodom.',
        5: 'Glej, rod, ki ga nisi spoznal, pokličeš, in rodovi, ki te niso spoznali, priteko k tebi, zaradi Gospoda, Boga tvojega, in zavoljo Svetnika Izraelovega, ker te je oslavil.',
        6: 'Iščite Gospoda, dokler ga morete najti, kličite ga, dokler je blizu!',
        7: 'Zapusti naj brezbožnik pot svoj in mož krivični misli svoje in povrni se h Gospodu, in usmilil se ga bo, in k Bogu našemu, ker je bogat v odpuščanju.',
        8: 'Kajti misli moje niso vaše misli, tudi vaša pota niso moja pota, pravi Gospod.',
        9: 'Marveč kakor so nebesa višja od zemlje, tako so pota moja višja nego vaša pota in misli moje nego vaše misli.',
        10: 'Kajti kakor pada dež ali sneg z neba in se ne vrača tja, temuč napaja zemljo ter jo dela rodovitno, da iz nje raste, da daje seme sejalcu in lačnemu kruh:',
        11: 'tako bode beseda moja, ki prihaja iz mojih ust: ne povrne se k meni prazna, temuč izvrši, kar me veseli, in bo uspeh imela v tem, za kar jo pošljem.',
        12: 'Zakaj z radostjo izidete in z mirom vas bodo spremljali; gore in hribi zaženo pred vami radostno vpitje in vsa drevesa poljska bodo z rokami ploskala.',
        13: 'Namesto grmovja zrastejo ciprese, namesto koprive vstane mirta: in bode Gospodu v slavno ime, v znamenje večno, ki se ne iztrebi.',
    },
    56: {
        1: 'Tako pravi Gospod: Pazite na pravico in strezite pravičnosti! kajti skoraj pride zveličanje moje in pravičnost moja se razodene.',
        2: 'Blagor človeku, ki dela to, in sinu človekovemu, ki se trdno drži tega: ki hrani soboto, da bi je ne oskrunil, in varuje roko svojo, da bi ne storil nič zlega.',
        3: 'Inozemec pa, ki se je pridružil Gospodu, naj ne govori, rekoč: Gospod me gotovo loči od svojega ljudstva; in skopljenec ne govóri: Glej, jaz sem suho drevo.',
        4: 'Zakaj tako govori Gospod o skopljencih, ki spoštujejo sobote moje in volijo to, kar mene veseli, in trdno drže zavezo mojo:',
        5: 'njim dam v hiši svoji in sredi zidov svojih prostora in ime boljše mimo sinov in hčer; ime večno jim dam, ki se ne iztrebi.',
        6: 'Inozemce pa, ki so se pridružili Gospodu, da mu strežejo in da ljubijo ime Gospodovo, da mu bodo hlapci: kdorkoli hrani soboto, da bi je ne oskrunil, in kateri trdno drže zavezo mojo,',
        7: 'nje tudi pripeljem h gori svetosti svoje in jih razveselim v molitveni hiši svoji, njih žgalne in klalne daritve bodo prijetne na oltarju mojem. Kajti hiša moja se bo imenovala dom molitve vsem ljudstvom.',
        8: 'Gospod Jehova, ki zbira razkropljence Izraelove, govori: Še druge bom zbral k njemu, k zbranim njegovim.',
        9: 'Vse živali poljske, pridite jest, vsa živad v gozdu!',
        10: 'Njegovi čuvaji so slepi, vsi so brez spoznanja; kolikor jih je, so nemi psi, ki ne morejo lajati; sanjajoč ležé, ljubijo spanje.',
        11: 'In tisti psi so požrešni, ne vedo, kdaj so siti; in to so pastirji! Niso zmožni kaj razumeti, vsi se obračajo na svojo pot, vsak se žene za svojim dobičkom od vseh strani:',
        12: '„Pridite, vina vzamem, in izpirali si bomo grlo s pijačo opojno; in jutrišnji dan bodi današnjemu podoben in še veliko boljši!“',
    },
    57: {
        1: 'Pravični gine, a nihče ne premisli v srcu, in z milostjo obdarovane pobira smrt, a nihče se ne zmeni, da se izpred nesreče pobira pravični.',
        2: 'V pokoj gre pravični; počivajo na ležiščih svojih, katerikoli hodijo v poštenosti svoji.',
        3: 'Vi pa, približajte se, vražarice otroci, prešeštnika in nečistnice zarod!',
        4: 'Zoper koga se razveseljujete? komu se režite in kažete jezik? Ali niste rojeni v grehu, niste li seme lažnivo,',
        5: 'ki se razvnemate za malike pod slehernim drevesom zelenečim, ki koljete otročiče po dolinah, pod skalnimi razpokami?',
        6: 'Med gladkimi kameni v potoku je tvoj del, nečistnica; oni, oni so delež tvoj; tudi njim si izlivala pitno daritev, darovala jedilno daritev. Ali naj se za to potolažim?',
        7: 'Na visoki, vzvišeni gori si napravila ležišče svoje; tudi si hodila tja gori opravljat daritev.',
        8: 'In za vrati in za podbojem si postavila spomenik svoj. Kajti izneverila si se meni in si šla gori razkrit se, razširila si ležišče svoje in izgovorila sebi plačilo od njih; rada si se družila ž njimi, ozirala se po njih migljaju.',
        9: 'In hodila si h kralju z oljem in mnogo si rabila dišeča mazila, in pošiljala si poslance svoje daleč in se poniževala prav do pekla.',
        10: 'Na svojih mnogih potih si bila trudna, a nisi rekla: Zaman je! Poživila se je moč tvoja, zato nisi opešala.',
        11: 'In koga si se plašila in bala, da si se lagala in se nisi spominjala mene, ne premislila tega v srcu? Nisem li jaz molčal, in to od nekdaj? in mene se nisi bala.',
        12: 'Jaz razglasim pravičnost tvojo in dela tvoja, nič ti ne bodo koristila.',
        13: 'Ko boš vpila, naj te rešijo zbrani maliki tvoji! toda nje vse pobere veter, sapa jih odnese. Kdor pa se zateka k meni, dobi deželo v last in podeduje goro svetosti moje.',
        14: 'In govorili bodo: Nasipajte, nasipajte, napravite pot, odpravite vsako spotiko s pota ljudstva mojega!',
        15: 'Zakaj tako pravi Visoki in Vzvišeni, ki prebiva v večnosti in ki mu je ime Sveti: Na višavi in v svetišču prebivam, tudi ž njim, ki je potrtega in ponižanega duha, da oživim duha ponižanih in oživim srce potrtih.',
        16: 'Kajti vekomaj se ne bom prepiral in brezkončno se ne srdil, ker bi njih duh onemogel pred obličjem mojim in duše, ki jih sem jaz ustvaril.',
        17: 'Zaradi krivične dobičkoželjnosti njegove sem se razsrdil in ga udaril, skril sem se in se srdil; on pa se je tem bolj odvrnil po srca svojega potu.',
        18: 'Pota njegova vidim, ali ozdravim ga; in vodil ga bom in dajal tolažbe njemu in žalujočim njegovim.',
        19: 'Ustvarjam sad ustnic: Mir, mir njemu, ki je daleč, in njemu, ki je blizu, pravi Gospod; in hočem ga ozdraviti.',
        20: 'Brezbožni pa so kakor morje razdraženo: mirovati ne more in vode njegove izmetavajo blato in nesnago.',
        21: 'Ni ga miru, pravi Bog moj, brezbožnim.',
    },
    58: {
        1: 'Vpij iz vsega grla, ne prenehaj! kakor tromba povzdigni glas svoj in oznanjaj ljudstvu mojemu njih pregreho in hiši Jakobovi njih grehe!',
        2: 'Iščejo me pač vsak dan in žele znati pota moja kakor narod, ki streže pravičnosti in ni zapustil pravice Boga svojega; vprašujejo me po pravičnih naredbah, žele, da bi se jim Bog približal.',
        3: '„Zakaj se postimo, in ti ne vidiš? ponižujemo dušo svojo, in se ne zmeniš za to?“Glejte, tisti dan, ko se postite, iščete, kar vam je v veselje, in pritiskate vse delavce svoje.',
        4: 'Glejte, postite se, da bi se pravdali in prepirali in da bi tepli s krivično pestjo. Ne postite se dandanašnji, da bi se slišal glas vaš na višavi.',
        5: 'Ali je tak post, kakršnega volim? dan, ko človek muči dušo svojo? Pripogibati kakor bičje glavo svojo in postlati si ležišče z raševnikom in pepelom: ali boš to imenoval post in dan po volji Gospodu?',
        6: 'Ali ni to post, kakršnega volim: da razrešite krivičnosti spone, da snamete sužnji jarem ter oprostite tlačene in razbijete sleherni jarem?',
        7: 'Ne li, da deliš lačnemu kruh svoj in da siromake izgnane pripelješ domov? ko vidiš nagega, da ga pokriješ, in se ne skrivaš pred sorodnim mesom svojim?',
        8: 'Tedaj napoči kakor zarja svetloba tvoja in zdajci zacvete zdravje tvoje, in pred teboj pojde pravičnost tvoja, slava Gospodova bode zadnja straža tvoja.',
        9: 'Tedaj boš klical, in Gospod te usliši, vpil boš, in odgovori ti: Glej, tu sem! Ako odpraviš izmed sebe jarem, iztezanje prsta v zasmeh in ničemurno govorjenje,',
        10: 'podeliš pa gladnemu iz srca svojega in nasitiš dušo potrto: tedaj prisije v temi svetloba tvoja in temina tvoja postane kakor poldan.',
        11: 'In Gospod te bo vodil vedno in v najhujši suši ti bo sitil srce in kosti tvoje naredil čile; in bodeš kakor namočen vrt in kakor vrelec vodá, ki se nikdar ne posuše.',
        12: 'In kateri so od tebe, sezidajo stare razvaline: podstave prejšnjih rodov postaviš zopet, in imenoval se boš Zagrajevalec vrzeli, Popravljalec cest v prebivanje.',
        13: 'Če obrneš od sobote nogo svojo, da ne boš delal, kar te veseli, v sveti dan moj, in boš soboto imenoval naslado, sveti dan Gospodov častitljiv, in če ga boš častil, ne hodeč po svojih potih, ne delajoč, kar te veseli, in ne govoreč praznih besed:',
        14: 'tedaj se boš razveseljeval v Gospodu, in dam ti, da boš jezdil po višinah zemlje, in storim, da boš užival dediščino Jakoba, očeta svojega; zakaj usta Gospodova so govorila.',
    },
    59: {
        1: 'Glejte, ni prekratka roka Gospodova, da ne more rešiti, tudi uho njegovo ni gluho, da ne more slišati;',
        2: 'ali krivice vaše so postale pregrada med vami in Bogom vašim, in grehi vaši so zagrnili obličje njegovo pred vami, da ne sliši.',
        3: 'Zakaj roke vaše so oskrunjene s krvjo in prsti vaši s krivico, ustne vaše govore laži, jezik vaš golči krivičnost.',
        4: 'Nihče ne kliče po pravičnosti in nihče se ne poteguje za pravdo v resnici; stavijo up na ničemurnost in govore laž, spočenjajo nadlogo in rode zlobo.',
        5: 'Jajca modrasova vale in pajčevine tko; kdor jé njih jajca, umre, in če se katero stare, skoči iz njega gad.',
        6: 'Njih tkanina ni za obleko in ni se mogoče odevati ž njih izdelki: njih dejanja so dejanja krivična in delo silovitosti je v njih rokah.',
        7: 'Njih noge teko k hudemu in hite prelivat kri nedolžno; njih misli se pečajo z zlobo; razdevanje in podiranje je na njih cestah.',
        8: 'Pota miru ne poznajo in nobene pravice ni po njih sledovih; steze svoje si kvarijo: kdorkoli stopi na katero izmed njih, nima miru.',
        9: 'Zato je daleč od nas pravica in pravičnost ne prihaja do nas. Čakamo svetlobe, a glej: le tema! čakamo jasnega svita, a hodimo po črni temini!',
        10: 'Kakor slepci otipavamo steno, tavamo kakor brez oči; zadevamo se prav opoldne kakor ob mraku; med zdravimi smo kakor mrtvi.',
        11: 'Renčimo vsi kakor medvedje, žalostno grulimo kakor golobje. Čakamo pravice, ali ni je, rešenja, a daleč je od nas.',
        12: 'Kajti pomnožile so se pregrehe naše pred teboj in grehi naši pričajo zoper nas; zakaj pregreh svojih smo si v svesti in krivice svoje poznamo:',
        13: 'da odpadamo od Gospoda in ga tajimo in se obračamo, da ne bi šli za Bogom svojim; zatiranje govorimo in odpad, sprejemamo v se besede lažnive in jih iz srca govorimo.',
        14: 'Tako je odvrnjena pravica, in pravičnost stoji oddaleč; zakaj resnica je padla na ulicah in poštenost ne more vstopiti.',
        15: 'In resnica je redka reč, in kdor se ogiblje hudega, je drugim v plen. To je videl Gospod, in hudo je bilo v očeh njegovih, da ni nikake pravice.',
        16: 'In videl je, da ni nobenega moža, in se je zavzel, da ni nobenega posrednika. Zato mu je rešitev napravila rama njegova, in pravičnost njegova, ta ga je podpirala.',
        17: 'In oblekel je pravičnost kakor oklep in dejal si čelado zveličanja na glavo; oblekel je, pravim, maščevanja oblačilo in ogrnil se je z gorečnostjo kakor s plaščem.',
        18: 'Prav po dejanjih, prav po njih bo povračal, togoto nasprotnikom svojim, kazen sovražnikom svojim; še otokom bo plačal povračilo.',
        19: 'In bali se bodo od zahoda imena Gospodovega in slave njegove od solnčnega vzhoda. Ko se kakor reka privali sovražnik, ga dih Gospodov zapodi v beg.',
        20: 'In Sionu pride odrešenik in njim, ki se odvračajo od pregrehe v Jakobu, govori Gospod.',
        21: 'Jaz pa – to je moja zaveza ž njimi, pravi Gospod: Duh moj, ki je nad teboj, in besede moje, ki sem jih položil v usta tvoja, se ne umaknejo iz tvojih ust, ne iz zaroda tvojega ust, ne iz ust potomcev tvojega zaroda, pravi Gospod, od tega časa vekomaj.',
    },
    60: {
        1: 'Vstani, svéti se, hči sionska! zakaj svetloba tvoja je prišla in slava Gospodova je zasijala nad teboj.',
        2: 'Kajti glej, tema pokriva zemljo in mrak narode; a nad teboj zasije Gospod in slava njegova bode očitna nad teboj.',
        3: 'In pridejo narodi k svetlobi tvoji in kralji k svitu, ki ti sije.',
        4: 'Povzdigni oči kroginkrog in poglej: vsi oni se zbirajo in prihajajo k tebi; sinovi tvoji gredo iz daljave in hčere tvoje prinašajo v naročju.',
        5: 'Tedaj boš videla in od veselja sijala, in srce ti bo močno utripalo in se širilo; zakaj obilnost morja se obrne do tebe, bogastvo narodov dospe k tebi.',
        6: 'Velblodov roj te pokrije, dromedarji iz Madiana in Efe; vsi pridejo iz Sabe, zlata prineso in kadila in veselo bodo oznanjali slavna dela Gospodova.',
        7: 'Vse črede kedarske se bodo zbirale k tebi; ovni nebajotski ti bodo stregli; prišli bodo na moj oltar v blagougodje meni; in okrasil bom hišo dike svoje. –',
        8: 'Kdo so oni, ki se zletavajo kakor gost oblak in kakor golobje k linam svojim?',
        9: 'Kajti mene bodo čakali otoki in tarsiške ladje najprej, da pripeljejo sinove tvoje iz daljave, srebro in zlato svoje s seboj, za ime Gospoda, Boga tvojega, in za Svetnika Izraelovega, ker te je odičil.',
        10: 'In zidali bodo tujci zidove tvoje in njih kralji ti bodo stregli; zakaj v srdu svojem sem te udaril, a v blagovoljnosti svoji sem se te usmilil.',
        11: 'In vrata tvoja bodo odprta neprestano, noč in dan se ne zapro, da pripeljejo k tebi bogastvo narodov ob spremstvu njih kraljev.',
        12: 'Kajti tisti narod in tisto kraljestvo, ki ti ne bo služilo, pogine, in ti narodi se popolnoma pokončajo.',
        13: 'Slava libanonska dojde k tebi, ciprese, platane in zelenike skupno, dičit mesto svetišča mojega; in oslavim nog svojih mesto.',
        14: 'In pripognjeni pridejo k tebi sinovi tlačiteljev tvojih, in priklonijo se pred stopali nog tvojih vsi zaničevalci tvoji, in imenovali te bodo Mesto Gospodovo, Sion Svetnika Izraelovega.',
        15: 'V odmeno, da si bila zapuščena in sovražena, da ni šel nihče skozi te, te napravim v lepoto večno, v veselje od roda do roda.',
        16: 'Sesala boš tudi mleko narodov in prsi kraljev boš sesala, in spoznaš, da sem jaz, Gospod, tvoj Zveličar in jaz, Mogočni Jakobov, tvoj Odrešenik.',
        17: 'Namesto brona prinesem zlata in namesto železa pripeljem srebra in namesto lesa brona in železa namesto kamenja. In postavim ti za oblastvo mir in za upravništvo pravičnost.',
        18: 'Več ne bode slišati o silovitosti v deželi tvoji, o pustošenju in podiranju po pokrajinah tvojih; temuč imenovala boš obzidje svoje Zveličanje in vrata svoja Hvalo.',
        19: 'Ne bode ti več solnce za svetlobo po dnevi in za svit nočni ti ne bo svetil mesec, marveč Gospod ti bode svetloba večna in Bog tvoj tebi za diko.',
        20: 'Ne zajde več solnce tvoje in mesec tvoj se ne skrije, zakaj Gospod ti bode svetloba večna. In konec bode žalovanja tvojega dnevom.',
        21: 'In ljudstvo tvoje – vsi bodo pravični, za vekomaj bodo podedovali deželo, kakor mladika, ki sem jo zasadil, rok mojih delo, meni v poveličanje.',
        22: 'Iz najmanjšega jih bode tisoč, iz šibkega mogočen narod. Jaz Gospod pospešim to ob svojem času.',
    },
    61: {
        1: 'Duh Gospoda Jehove je nad mano, zato ker me je Gospod pomazilil, da naj oznanjam blagovestje krotkim; poslal me je obvezovat potrte v srcu, oznanjat svobodo jetnikom in zaprtim, da se jim odpira ječa;',
        2: 'da oklicujem milostno leto Gospodovo in dan maščevanja Boga našega, da tolažim vse žalujoče,',
        3: 'da poskrbim za žalujoče na Sionu in jim dam diko namesto pepela, olje veselja namesto žalosti, hvalni plašč namesto duha obupnega; da bi se imenovali hrasti pravičnosti, sadež Gospodov, njemu v poveličanje.',
        4: 'In pozidajo stare razvaline in postavijo, kar je bilo v nekdanjih časih porušeno, ter obnove zapuščena mesta, pustišča mnogih rodov.',
        5: 'In tujci bodo stali in pasli črede vaše in inozemci bodo oratarji in vinogradniki vaši.',
        6: 'Vi pa se boste imenovali duhovniki Gospodovi, strežaje Boga našega vas bodo zvali. Uživali boste bogastvo narodov in ž njih slavo se ponašali.',
        7: 'Za svojo sramoto dobite dvojno; in namesto nečasti se bodo veselili svojega deleža; kajti dobodo v svoji deželi dvojno posest in veselje bodo imeli večno.',
        8: 'Zakaj jaz, Gospod, ljubim pravico, sovražim zlobno plenjenje; in dam jim njih povračilo v resnici in večno zavezo sklenem ž njimi.',
        9: 'In znano bode med poganskimi narodi njih seme in njih rojenci med ljudstvi: vsi, ki jih bodo videli, pripoznajo, da so seme, ki ga je blagoslovil Gospod.',
        10: 'Veselil se bom, veselil v Gospodu, raduje se naj duša moja v Bogu svojem! Kajti odel me je z obleko zveličanja, s plaščem pravičnosti me ogrnil, kakor se ženin po duhovniško pokriva z vencem in kakor se nevesta diči z dragotinami svojimi.',
        11: 'Kakor namreč zemlja rodi svoje rastline in kakor vrt poganja setev svojo, tako stori Gospod Jehova, da bo rasla pravičnost in hvala pred vsemi narodi.',
    },
    62: {
        1: 'Zavoljo Siona ne bom molčal in zaradi Jeruzalema ne bom miroval, dokler ne vzide kakor svit pravičnost njegova in zveličanje njegovo ne zagorí kakor plamenica.',
        2: 'In narodi bodo videli pravičnost tvojo in vsi kralji slavo tvojo, in imenovali te bodo z novim imenom, katero izreko usta Gospodova.',
        3: 'In prekrasen venec bodeš v roki Gospodovi in kraljevo naglavje v roki Boga svojega.',
        4: 'Ne bodo ti več rekli: Zapuščenka! in deželi tvoji ne bodo več pravili Puščava, marveč imenovali te bodo: Hefziba in deželo tvojo: Beula; zakaj Gospod se bo radoval v tebi in dežela tvoja bo omožena.',
        5: 'Kajti kakor se poroči mladenič z devico, se poroče s teboj sinovi tvoji, in kakor se ženin veseli neveste, se bo veselil tebe Bog tvoj.',
        6: 'Na zidove tvoje, o Jeruzalem, sem postavil čuvaje; ves dan in vso noč ne bodo za trenotek molčali. Vi, ki spominjate Gospoda, ne privoščite si pokoja',
        7: 'in ne dajajte Mu pokoja, dokler ne utrdi Jeruzalema in dokler ga ne napravi v hvalo na zemlji.',
        8: 'Prisegel je Gospod pri desnici svoji in pri rami moči svoje: Ne dam več žita tvojega za jed sovražnikom tvojim in inozemci ne bodo pili vina tvojega, za katero si se trudil!',
        9: 'Temuč kateri spravljajo žito, ga bodo jedli in hvalili Gospoda, in kateri zbirajo vino, ga bodo pili v vežah svetišča mojega.',
        10: 'Idite, idite skozi vrata! Pripravljajte ljudstvu pot! Nasipajte, nasipajte cesto, odpravljajte kamenje! Visoko povzdignite zastavo ljudstvom!',
        11: 'Glej, Gospod je razglasil prav do kraja zemlje: Povejte hčeri sionski: Glej, rešenje tvoje se bliža! glej, plačilo njegovo je pri njem in povračilo njegovo pred njim!',
        12: 'In imenovali jih bodo Sveto ljudstvo, Rešence Gospodove; in tebe bodo imenovali Mesto, ki po njem vsi vprašujejo, ki ne bo več zapuščeno.',
    },
    63: {
        1: 'Kdo je ta, ki prihaja od Edoma, v rdeče pobarvani obleki iz Bozre? Krasen je v svoji obleki, ponosno stopa v obili moči svoji! – Jaz sem, ki govorim v pravičnosti, premogočen za rešenje. –',
        2: 'Zakaj si rdeč po obleki in oblačila tvoja kakor njega, ki tlači v tlačilnici? –',
        3: 'Tlačil sem v tlačilnici sam, in izmed ljudstev ni bilo nikogar z menoj; zatorej sem jih teptal v jezi svoji in jih gazil v togoti svoji, da se je ž njih životnim sokom oškropila obleka moja in sem si vsa oblačila omadeževal.',
        4: 'Zakaj dan maščevanja je bil v srcu mojem in moje leto odrešenja je prišlo.',
        5: 'In oziral sem se, a ni bilo nobenega pomočnika, in strmel sem, da ni nikogar, ki bi podpiral. Tedaj mi je rešenje prinesla rama moja, in togota moja, ta me je podpirala.',
        6: 'In teptal sem ljudstva v jezi svoji in sem jih upijanil v togoti svoji, in njih životni sok sem izlil na tla.',
        7: 'Milosti Gospodovih se bom hvalno spominjal, slavnih del Gospodovih, po vsem, kar nam je podelil Gospod, in obilne dobrote hiši Izraelovi, ki jim jo je izkazal po usmiljenju svojem in po obilosti milosti svojih.',
        8: 'Kajti rekel je: Res, ljudstvo moje so, sinovi, ki ne bodo ravnali lažnivo. Torej jim je bil rešitelj.',
        9: 'V vsej njih stiski je bil sam stiskan, in angel obličja njegovega jih je reševal. V svoji ljubezni in usmiljenosti jih je odkupil sam in dvignil jih je nase ter jih nosil vse dni nekdanje.',
        10: 'Ali oni so se uprli in žalili duha svetosti njegove; zato se jim je izpremenil v sovražnika, sam se je boril proti njim.',
        11: 'Tedaj se je spominjalo ljudstvo njegovo dni nekdanjih, dni Mojzesovih: Kje je, ki jih je izpeljal z morja s pastirji črede svoje vred? Kje je, ki je mednje dal duha svetosti svoje?',
        12: 'ki jih je spremljal Mojzesu na desnici z veličastno ramo svojo? ki je razklal vode pred njimi, da bi si napravil ime večno?',
        13: 'ki jih je vodil skozi globočine kakor konja po puščavi, da se niso spoteknili?',
        14: 'Kakor žival stopa nazaj v dolino, jih je peljal duh Gospodov v pokoj: tako si vodil ljudstvo svoje, da si napraviš ime veličastno.',
        15: 'Ozri se iz nebes in poglej iz prebivališča svetosti in veličasti svoje! kje je gorečnost tvoja in kje mogočna dela tvoja? Nagib svojega srca in svojo usmiljenost zadržuješ meni.',
        16: 'Saj ti si oče naš; kajti Abraham ne ve za nas in Izrael nas ne pozna, ti, o Gospod, si oče naš; odrešenik naš od vekomaj ti je ime.',
        17: 'Zakaj pripuščaš, o Gospod, da zahajamo od potov tvojih, zakaj si nam zakrknil srce, da se te ne bojimo? Vrni se k nam zaradi hlapcev svojih, zavoljo rodov dediščine svoje!',
        18: 'Le malo časa jo je imelo v posesti ljudstvo svetosti tvoje: sovražniki naši so razteptali svetišče tvoje.',
        19: 'Postali smo kakor tisti, ki jim nikoli nisi gospodoval, ki se niso imenovali po tvojem imenu!',
    },
    64: {
        1: 'O da bi predrl nebesa in prišel doli, da bi se od obličja tvojega raztopile gore',
        2: '(kakor ogenj požiga protje in voda vre od ognja), da oznaniš ime svoje nasprotnikom svojim, da bi strepetali narodi pred obličjem tvojim,',
        3: 's tem, da delaš strahovite reči, ki jih nismo pričakovali; o da stopiš doli, da bi se od obličja tvojega raztopile gore!',
        4: 'Zakaj od veka se ni slišalo, nikdar niso čula ušesa, tudi oko ni videlo Boga razen tebe, ki bi toliko delal za njega, ki ga čaka.',
        5: 'Naproti prihajaš njemu, ki se veseli pravičnosti in ji streže, njim, ki se spominjajo tebe na potih svojih. Glej, ti si se srdil, in mi smo grešili; v tem smo že dolgo časa, bomo li rešeni?',
        6: 'In vsi vkup smo postali kakor neznažnik in vse pravičnosti naše so kakor umazana cunja; in venemo kakor listje, kolikorkoli nas je in krivice naše nas odnašajo kakor veter.',
        7: 'In ni ga, ki bi klical ime tvoje, ki bi se zbudil, da se poprime tebe; kajti skril si obličje svoje pred nami in nas izročil oblasti krivic naših.',
        8: 'Ali sedaj, o Gospod, ti si oče naš; mi smo glina, ti pa si nam lončar, in vsi smo tvoje roke delo.',
        9: 'Ne togóti se, o Gospod, presilno in ne spominjaj se vekomaj krivice! Glej, ozri se na nas, prosimo, mi vsi smo ljudstvo tvoje.',
        10: 'Mesta svetosti tvoje so puščava, Sion je puščava, Jeruzalem je pustinja.',
        11: 'Sveta in prekrasna hiša naša, ki so te v njej hvalili očetje naši, je požgana z ognjem in vse, kar nam je bilo dragoceno, je v razvalinah.',
        12: 'Hočeš li, o Gospod, ob toliki revi v sebi zadržavati usmiljenje, boš li molčal in nas tepel presilno?',
    },
    65: {
        1: 'Dal sem se iskati njim, ki niso po meni vpraševali; dal sem se najti njim, ki me niso iskali. Narodu, ki se ni imenoval po mojem imenu, sem rekel: Tu sem, tu sem!',
        2: 'Iztezal sem roke svoje ves dan k ljudstvu upornemu, ki hodijo po svojih mislih, po potu, ki ni dober,',
        3: 'k ljudstvu, ki me vedno dražijo v lice s tem, da darujejo po vrtih in žgo kadilo na opeki,',
        4: 'ki sede med grobovi in prenočujejo v skritih krajih, ki jedo meso svinjsko in imajo juho od gnusnega mesa v posodah svojih,',
        5: 'ki govore: Ostani zase, meni se ne približaj, ker svetejši sem od tebe: ti so dim v mojem nosu, ogenj, goreč ves dan.',
        6: 'Glej, pisano je to pred menoj. Ne bom molčal, ako ne povrnem; da, povrnem njim v nedrje',
        7: 'krivice vaše in očetov vaših krivice vkup, pravi Gospod, ki so kadilo žgali na gorah in me sramotili na gričih; zatorej odmerim najprej njih plačilo njim v nedrje.',
        8: 'Tako pravi Gospod: Kakor se reče o grozdu, če je soka v njem: Ne pogúbi ga, ker je blagoslov v njem: tako hočem storiti zaradi hlapcev svojih, da ne pogubim vsega ljudstva.',
        9: 'In storim, da pride seme iz Jakoba in iz Jude dedič mojih gorá; in izvoljenci moji bodo podedovali deželo in hlapci moji bodo prebivali ondi.',
        10: 'In Saron bode pašnik čredam in dolina Ahor ležišče govedi za ljudstvo moje, ki me je iskalo.',
        11: 'Vi pa, ki zapuščate Gospoda, ki zabite goro svetosti moje, ki pripravljate mizo Sreči in natakate pitne dari Usodi:',
        12: 'vas sem prisodil meču, da se morate vsi pripogniti v zakol, zato ker mi niste odgovorili, ko sem klical, in niste poslušali, ko sem govoril, temuč ste delali, kar je hudo v mojih očeh, in ste izvolili, kar mi ni po volji.',
        13: 'Zatorej pravi tako Gospod Jehova: Glej, hlapci moji bodo jedli, vi pa boste lačni; glej, hlapci moji bodo pili, vi pa boste žejni; glej, hlapci moji se bodo veselili, vi pa se boste sramovali;',
        14: 'glej, hlapci moji bodo peli od srčnega veselja, vi pa boste kričali od srčne bolečine in tulili od dušne bridkosti.',
        15: 'In zapustite ime svoje v kletvico izvoljencem mojim; in s smrtjo te udari Gospod Jehova. Hlapcem svojim pa da drugo ime,',
        16: 'da se bo blagoslavljal v Bogu resnice, kdor se hoče blagoslavljati na zemlji, in bo prisegel pri Bogu resnice, kdor se hoče blagoslavljati na zemlji, in bo prisegel pri Bogu resnice, kdor hoče prisegati na zemlji; kajti pozabijo se stiske prejšnje in bodo skrite pred očmi mojimi.',
        17: 'Zakaj, glej, jaz ustvarjam nova nebesa in zemljo novo, in o prejšnjem ne bode spomina in ne pride več na misel.',
        18: 'Ali veselite in radujte se vekomaj tega, kar jaz ustvarjam. Zakaj, glejte, jaz preustvarjam Jeruzalem v radost in ljudstvo njegovo v veselje.',
        19: 'In radoval se bom nad Jeruzalemom in veselil se ljudstva svojega, in ne bo se več čul v njem joka glas, ne vpitja glas.',
        20: 'Ne bode odondod več otroka, ki bi živel le malo dni, ne starca, ki bi ne dopolnil svojih dni; kajti kdor umre stoleten, bode še mladenič, a grešnik, sto let star, bo proklet.',
        21: 'In zidali bodo hiše ter v njih prebivali, in sadili vinograde in jedli njih sad.',
        22: 'Ne bodo zidali, kdo drugi pa prebival, ne bodo sadili, kdo drugi pa užival; zakaj kakor so dnevi drevesa, bodo ljudstva mojega dnevi, in rok svojih delo bodo dolgo uživali izvoljenci moji.',
        23: 'Trudili se ne bodo brezuspešno in rodili ne bodo otrok za naglo smrt; kajti seme bodo blagoslovljenih od Gospoda in njih zarod ž njimi.',
        24: 'In zgodi se, da odgovorim, preden bodo klicali; ko bodo še govorili, jih uslišim.',
        25: 'Volk in jagnje se bosta pasla skupaj in lev bo slamo grizel kakor vol, kači pa bode prah hrana. Ne bodo delali škode, ne pogubno ravnali po vsej gori svetosti moje, pravi Gospod.',
    },
    66: {
        1: 'Tako pravi Gospod: Nebo je prestol moj in zemlja nogam mojim podnožje. Kakšna bi neki bila hiša, ki bi jo mi zidali? in kje li počivanju mojemu mesto?',
        2: 'Saj vse to je naredila roka moja in po njej je vse to postalo, govori Gospod. Ali na tega se ozrem: na ubožca in potrtega v duhu in na njega, ki trepeče pred besedo mojo.',
        3: 'Kdor kolje vola, je, kakor kdor ubija moža, kdor daruje drobnico, kakor kdor seče glavo psu, kdor prinaša pitni dar, kakor bi daroval kri svinjsko, kdor žge kadilo v spomin, kakor kdor hvali malika: res, oni so izvolili pota svoja in gnusob svojih se veseli njih duša.',
        4: 'Tudi jaz izvolim, kar jih boli, in pripeljem nadnje, česar jih je strah; zato ker mi, ko sem klical, ni nihče odgovoril, ko sem govoril, niso poslušali, temuč so delali, kar je hudo v očeh mojih, in so izvolili tisto, kar mi ni po volji.',
        5: 'Čujte besedo Gospodovo, ki trepetate pred besedo njegovo! Bratje vaši, ki vas sovražijo in vas pehajo od sebe zaradi imena mojega, govore: Naj se Gospod izkaže častit, da vidimo radost vašo! Toda osramočeni bodo.',
        6: 'Čujte, hrupa glas iz mesta! glas iz svetišča! glas Gospodov, ki povrača sovražnikom svojim, kar so zaslužili!',
        7: 'Ko je niso še obšle porodne težave, je rodila; ko je ni še napadla bolečina, je povila moško dete.',
        8: 'Kdo je slišal kaj takega, kdo je videl kaj enakega? More li dežela biti rojena v enem dnevi? se li porodi narod mahoma? Komaj so Sion obšle težave, in že je rodil sinove svoje.',
        9: 'Ali bi jaz odprl maternico, a ne dal poroditi? pravi Gospod; ali bi jaz, ki dajem roditi, zopet zadržal? veli Bog tvoj.',
        10: 'Veselite se z Jeruzalemom in radujte se nad njim vsi, ki ga ljubite, udeležujte se veselja ž njim, ki ste žalovali nad njim!',
        11: 'da sesate in se nasitite na prsih tolažb njegovih, da se nasrkate in se vam dobro godi od obilnosti slave njegove.',
        12: 'Kajti tako pravi Gospod: Glej, jaz napeljem proti njemu kakor reko mir in kakor poplavljajoč potok slavo narodov, in boste sesali; v naročjih vas bodo nosili in na kolenih ljubkali.',
        13: 'Kakor če koga tolaži mati njegova, tako hočem jaz tolažiti vas; in v Jeruzalemu boste obliti s tolažbo.',
        14: 'In boste videli, in veselilo se bo srce vaše, in kosti vaše se razcveto kako nežna trava. In očitna bo roka Gospodova pri hlapcih njegovih in nevolja proti sovražnikom njegovim.',
        15: 'Zakaj, glej, Gospod pride z ognjem in vozovi njegovi bodo podobni vrtincu, da povračuje jezo svojo s togoto in karanje svoje z gorečimi plameni.',
        16: 'Kajti Gospod bo sodbo vršil z ognjem in z mečem svojim proti vsemu mesu, in mnogo jih bode, ki jih prebode Gospod.',
        17: 'Kateri se posvečujejo in se očiščajo za malikovanje na vrtih, za enim v sredi, kateri jedo meso svinjsko, gnusobo in miši, skup se pokončajo, govori Gospod.',
        18: 'Jaz pa vem njih dela, njih misli. Pride čas, da zberem vse narode in jezike; in pridejo in bodo gledali slavo mojo.',
        19: 'In postavim znamenje med njimi, in izmed njih ubežnikov pošljem k narodom v Tarsis, Pul in Lud, ki streljajo z lokom, v Tubal in Javan, na daljne otoke, ki niso slišali vesti o meni in niso videli slave moje; in oznanjali bodo slavo mojo med narodi.',
        20: 'In pripeljejo vse brate vaše izmed vseh narodov v dar Gospodu na konjih, na vozeh in nosilih, na mezgih in dromedarjih na goro svetosti moje, v Jeruzalem, pravi Gospod, kakor sinovi Izraelovi prinašajo pitno daritev v snažni posodi v hišo Gospodovo.',
        21: 'In tudi izmed njih jih vzamem za duhovnike in levite, pravi Gospod.',
        22: 'Zakaj kakor bodo ona nova nebesa in zemlja nova, ki jih hočem narediti, stala pred menoj, tako bo stalo seme vaše in ime vaše.',
        23: 'In zgodi se, da bo od mlaja do mlaja in od sobote prihajalo vse meso molit pred mene, pravi Gospod.',
        24: 'In pojdejo ven in videli bodo mrtva trupla tistih ljudi, ki so odpadli od mene; zakaj njih črv ne umre in njih ogenj ne ugasne, in gnusoba bodo vsemu mesu.',
    },
}
